import java.util.*;
import java.io.*;

public class Main {
    static class Rib {
        long b, u, c, f;
        int back;
        Rib(long b, long u, long c, long f, int back) {
            this.b = b; this.u = u; this.c = c; this.f = f; this.back = back;
        }
    }

    static void addRib(List<List<Rib>> g, long a, long b, long u, long c) {
        g.get((int)a).add(new Rib(b, u, c, 0, g.get((int)b).size())));
        g.get((int)b).add(new Rib(a, 0, -c, 0, g.get((int)a).size() - 1));
    }

    static class K {
        static long n, m, k, c, d;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        // Read initial input
        st = new StringTokenizer(br.readLine());
        K.n = Long.parseLong(st.nextToken());
        K.m = Long.parseLong(st.nextToken());
        K.k = Long.parseLong(st.nextToken());
        K.c = Long.parseLong(st.nextToken());
        K.d = Long.parseLong(st.nextToken());

        int n = (int)(50 * 99 + 1);
        int m = (int)K.m;
        int kVal = (int)K.k;
        List<List<Rib>> g = new ArrayList<>();
        for (int i=0; i<n; i++) g.add(new ArrayList<>());
        int s = 0;
        int t = 1;

        long tim=99;
        long INF = 1000L * 1000L * 1000L;

        int[] lr = new int[55];
        for (int i=1; i<=K.k; i++){
            lr[i] = Integer.parseInt(br.readLine());
            addRib(g,0,lr[i],1,0);
        }

        for (int j=0; j<tim-1; j++){
            for (int i=2; i<=K.n; i++){
                addRib(g,j*50+i,(j+1)*50+i,50,K.c);
            }
        }

        for (int j=1; j<tim; j++){
            addRib(g,j*50+1,1,50,0);
        }

        String line;
        long flow=0, cost=0;
        List<List<Rib>> graph = g;

        // Read edges
        for (int i=0; i<K.m; i++) {
            line = br.readLine();
            st = new StringTokenizer(line);
            long x = Long.parseLong(st.nextToken());
            long y = Long.parseLong(st.nextToken());
            // Store adjacency
            // Using array of lists
            // But our structure is already in g
            // Stores in vr[x], vr[y]
            // We can store separately if needed, but not necessary
            // Here just process edges

            if (x>=0 && y>=0 && x<=K.n && y<=K.n) {
                for (int j=0; j<tim-1; j++){
                    for (int l=0; l<50; l++){
                        long capacityOffset = (K.c + (K.d)*((l+1)*(l+1) - (l*l)));
                        addRib(g, j*50 + (int)x, (j+1)*50 + (int)y,1,capacityOffset);
                        addRib(g, j*50 + (int)y, (j+1)*50 + (int)x,1,capacityOffset);
                    }
                }
            }
        }

        while (true) {
            long[] d = new long[n];
            Arrays.fill(d, INF);
            int[] id = new int[n];
            int[] p = new int[n];
            int[] p_rib = new int[n];

            Queue<Integer> q = new LinkedList<>();
            q.add(s);
            d[s] = 0;
            while (!q.isEmpty()) {
                int v = q.poll();
                id[v] = 2;
                for (int i=0; i<graph.get(v).size(); i++) {
                    Rib r = graph.get(v).get(i);
                    if (r.f < r.u && d[v] + r.c < d[(int)r.b]) {
                        d[(int)r.b] = d[v] + r.c;
                        if (id[(int)r.b] == 0) {
                            q.add((int)r.b);
                            id[(int)r.b] = 2;
                        } else if (id[(int)r.b]==2) {
                            // Move to front for Zero/One approach? Ignoring for simplicity
                            q.add((int)r.b);
                        }
                        p[(int)r.b] = v;
                        p_rib[(int)r.b] = i;
                    }
                }
            }

            if (d[t]==INF) break;

            long addFlow = K.k - flow;
            for (int v=t; v!=s; v= p[v]){
                int pv = p[v];
                int pr = p_rib[v];
                long remCap = graph.get(pv).get(pr).u - graph.get(pv).get(pr).f;
                if (remCap < addFlow) addFlow = remCap;
            }

            for (int v=t; v!=s; v= p[v]){
                int pv = p[v];
                int pr = p_rib[v];
                int backIdx = graph.get(pv).get(pr).back;
                graph.get(pv).get(pr).f += addFlow;
                graph.get((int)graph.get(pv).get(pr).b).get(backIdx).f -= addFlow;
                cost += graph.get(pv).get(pr).c * addFlow;
            }
            flow += addFlow;
        }

        System.out.println(cost);
    }
}

