import java.util.*;

public class MinCostFlow {
    static final int N = 10000;
    static final int M = N * 100;
    static final long INF = Long.MAX_VALUE >> 5;

    static class FlowGraph {
        int[] head = new int[N];
        int[] v = new int[M];
        int[] nxt = new int[M];
        long[] c = new long[M];
        long[] w = new long[M];
        int[] cost = new int[M];
        int ptr, t;
        long totalCost;

        boolean[] vis = new boolean[N];
        int[] dis = new int[N];
        int[] id = new int[N];
        int[] cur = new int[N];

        void paddEdge(int u, int v_, long ww, int cc) {
            this.v[ptr] = v_;
            this.w[ptr] = ww;
            this.c[ptr] = cc;
            this.nxt[ptr] = head[u];
            head[u] = ptr++;
        }

        boolean spfa(int s, int t) {
            Arrays.fill(vis, false);
            Arrays.fill(dis, -1);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            dis[s] = 0;
            id[s] = 1;
            while (!q.isEmpty()) {
                int nd = q.poll();
                vis[nd] = false;
                for (int i = head[nd]; i != -1; i = nxt[i]) {
                    if (w[i] > 0 && (dis[v[i]] == -1 || dis[v[i]] > dis[nd] + c[i])) {
                        dis[v[i]] = dis[nd] + c[i];
                        if (!vis[v[i]]) {
                            vis[v[i]] = true;
                            q.offer(v[i]);
                        }
                    }
                }
            }
            return dis[t] != -1;
        }

        long dfs(int pos, long flow, int t) {
            if (pos == t) return flow;
            vis[pos] = true;
            long tmp = flow;
            for (int i = cur[pos] != -1 ? cur[pos] : head[pos]; i != -1; i = nxt[i]) {
                if (!vis[v[i]] && w[i] > 0 && dis[v[i]] == dis[pos] + c[i]) {
                    cur[pos] = i;
                    long fl = dfs(v[i], Math.min(flow, w[i]), t);
                    totalCost += fl * c[i];
                    w[i] -= fl;
                    w[i ^ 1] += fl;
                    flow -= fl;
                    if (flow == 0) break;
                }
            }
            return tmp - flow;
        }

        void addEdge(int u, int v_, long ww, int cc) {
            paddEdge(u, v_, ww, cc);
            paddEdge(v_, u, 0, -cc);
        }

        long dinic(int s, int t) {
            totalCost = 0;
            this.t = t;
            while (spfa(s, t)) {
                Arrays.fill(cur, -1);
                Arrays.fill(vis, false);
                dfs(s, INF, t);
            }
            return totalCost;
        }

        FlowGraph() {
            Arrays.fill(head, -1);
            Arrays.fill(nxt, -1);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int kk = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        int[] a = new int[kk + 1];
        for (int i = 1; i <= kk; i++) {
            a[i] = sc.nextInt();
        }

        int s = 0;
        int t = n * 100 + 1;
        FlowGraph g = new FlowGraph();
        for (int i = 1; i <= 100; i++) {
            g.addEdge(i, t, INF, 0);
        }
        for (int i = 1; i <= kk; i++) {
            g.addEdge(s, (a[i] - 1) * 100 + 1, 1, 0);
        }
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j < 100; j++) {
                g.addEdge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, INF, c);
            }
        }

        for (int _ = 0; _ < m; _++) {
            int t1 = sc.nextInt();
            int t2 = sc.nextInt();
            for (int i = 1; i < 100; i++) {
                int val = c + d * (i * i - (i - 1) * (i - 1));
                g.addEdge((t1 - 1) * 100 + i, (t2 - 1) * 100 + i + 1, 1, val);
                g.addEdge((t2 - 1) * 100 + i, (t1 - 1) * 100 + i + 1, 1, val);
            }
        }
        System.out.println(g.dinic(s, t));
        sc.close();
    }
}

