import java.util.*;
import java.io.*;

public class MaxFlowMinCost {
    static class Line {
        int nxt, t, c, l;
        Line(int nxt, int t, int c, int l) {
            this.nxt = nxt;
            this.t = t;
            this.c = c;
            this.l = l;
        }
    }

    static final int Maxn = 5500;
    static final int Maxm = 35500;
    static final int INF = 1000000000;
    static Line[] g = new Line[Maxm];
    static int[] fir = new int[Maxn];
    static int tl = 1;

    static int S, T, n, m, k, C, D;
    static int[][] pl = new int[105][105];
    static int[][] st = new int 105][105];
    static Data[] s = new Data[105];
    static boolean[] in = new boolean[Maxn];
    static int[] pre = new int[Maxn];
    static int[] lp = new int[Maxn];
    static int[] flow = new int[Maxn];
    static int[] dis = new int[Maxn];
    static Queue<Integer> q = new LinkedList<>();

    static class Data {
        int f, t;
        Data(int f, int t) {
            this.f = f;
            this.t = t;
        }
    }

    static int P(int x, int y) {
        return x * n + y;
    }

    static void adl(int f, int t, int c, int cost) {
        g[++tl] = new Line(fir[f], t, c, cost);
        fir[f] = tl;
        g[++tl] = new Line(fir[t], f, 0, -cost);
        fir[t] = tl;
    }

    static int spfa() {
        Arrays.fill(dis, INF);
        Arrays.fill(flow, 0);
        flow[S] = INF;
        dis[S] = 0;
        q.clear();
        q.offer(S);
        Arrays.fill(in, false);
        in[S] = true;
        while (!q.isEmpty()) {
            int u = q.poll();
            in[u] = false;
            for (int i = fir[u]; i != 0; i = g[i].nxt) {
                int v = g[i].t;
                if (g[i].c > 0 && dis[v] > dis[u] + g[i].l) {
                    dis[v] = dis[u] + g[i].l;
                    flow[v] = Math.min(flow[u], g[i].c);
                    lp[v] = i;
                    pre[v] = u;
                    if (!in[v]) {
                        in[v] = true;
                        q.offer(v);
                    }
                }
            }
        }
        return flow[T];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer stoken = new StringTokenizer(br.readLine());
        n = Integer.parseInt(stoken.nextToken());
        m = Integer.parseInt(stoken.nextToken());
        k = Integer.parseInt(stoken.nextToken());
        C = Integer.parseInt(stoken.nextToken());
        D = Integer.parseInt(stoken.nextToken());

        int totalNodes = n + k;
        S = P(n + k, n) + 1;
        T = S + 1;

        for (int i = 0; i <= Maxm; i++) g[i] = null;
        Arrays.fill(fir, 0);
        tl = 1;

        // add edge from S to super-source
        adl(P(0, 1), T, INF, 0);

        int p;
        String line = br.readLine();
        stoken = new StringTokenizer(line);
        for (int i = 1; i <= k; i++) {
            p = Integer.parseInt(stoken.nextToken());
            adl(S, P(0, p), 1, 0);
        }

        s = new Data[m * 2 + 1];
        for (int i = 1; i <= m; i++) {
            line = br.readLine();
            stoken = new StringTokenizer(line);
            int f1 = Integer.parseInt(stoken.nextToken());
            int t1 = Integer.parseInt(stoken.nextToken());
            s[2 * i] = new Data(f1, t1);
            s[2 * i - 1] = new Data(t1, f1);
        }
        m *= 2;

        for (int t = 1; t <= n + k; t++) {
            for (int i = 1; i <= n; i++) {
                adl(P(t - 1, i), P(t, i), INF, 0);
            }
            for (int i = 1; i <= m; i++) {
                adl(P(t - 1, s[i].f), P(t, s[i].t), 1, D);
                pl[t][i] = tl;
                st[t][i] = 1;
            }
            adl(P(t, 1), T, INF, t * C);
        }

        int cans = 0;
        while (true) {
            int sav = spfa();
            if (sav == 0) break;
            int u = T;
            while (u != S) {
                int las = pre[u];
                g[lp[u]].c -= sav;
                g[lp[u] ^ 1].c += sav;
                u = las;
            }
