import java.util.*;

public class Main {
    static class Pair {
        int first, second;
        Pair(int f, int s) {
            this.first = f;
            this.second = s;
        }
    }

    static final int iinf = 0x3f3f3f3f;
    static final long linf = 0x3f3f3f3f3f3f3f3fL;

    static final int N = 50;
    static int n, m, k, c, d, mxt;

    static final int fN = (N * 3 + 1) * N + 2;
    static int s, t, fn;
    static ArrayList<Integer>[] e = new ArrayList[fN];
    static ArrayList<Integer> to = new ArrayList<>();
    static ArrayList<Integer> fw = new ArrayList<>();
    static ArrayList<Integer> co = new ArrayList<>();

    static int[] dep = new int[fN];
    static int[] pre = new int[fN];
    static boolean[] vis = new boolean[fN];

    static void adde(int u, int v, int w, int c) {
        e[u].add(to.size()); to.add(v); fw.add(w); co.add(c);
        e[v].add(to.size()); to.add(u); fw.add(0); co.add(-c);
    }

    static boolean spfa() {
        Arrays.fill(dep, 0x3f3f3f3f);
        Arrays.fill(pre, -1);
        Arrays.fill(vis, false);
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        vis[s] = true;
        dep[s] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            vis[u] = false;
            for (int vIdx : e[u]) {
                int v = to.get(vIdx);
                if (fw.get(vIdx) != 0 && dep[v] > dep[u] + co.get(vIdx)) {
                    dep[v] = dep[u] + co.get(vIdx);
                    pre[v] = vIdx;
                    if (!vis[v]) {
                        q.offer(v);
                        vis[v] = true;
                    }
                }
            }
        }
        return dep[t] < iinf;
    }

    static Pair mcmf() {
        int flowSum = 0, costSum = 0;
        while (spfa()) {
            int f = iinf;
            for (int u = t; u != s; u = to.get(pre[u] ^ 1)) {
                f = Math.min(f, fw.get(pre[u]));
            }
            for (int u = t; u != s; u = to.get(pre[u] ^ 1)) {
                int preEdgeIdx = pre[u];
                fw.set(preEdgeIdx, fw.get(preEdgeIdx) - f);
                fw.set(preEdgeIdx ^ 1, fw.get(preEdgeIdx ^ 1) + f);
            }
            flowSum += f;
            costSum += dep[t] * f;
        }
        return new Pair(flowSum, costSum);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < fN; i++) {
            e[i] = new ArrayList<>();
        }
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();
        mxt = N * 3 + 1;

        s = 0;
        t = 0;
        fn = 0;

        // Read initial U values
        for (int i = 0; i < k; i++) {
            int u = sc.nextInt() - 1;
            adde(s, u, 1, 0);
        }

        int totalNodes = mxt * n;
        int maxNodeId = totalNodes - 1;

        // Read edges
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            for (int layer = 0; layer < mxt - 1; layer++) {
                int fromU = layer * n + u;
                int toV = (layer + 1) * n + v;
                adde(fromU, toV, 1, 2 * d * (k + 1) - d);
                adde(toV - (layer + 1) * n + v + (layer) * n, (layer + 1) * n + u, 1, 2 * d * (k + 1) - d);
            }
        }

        // Edges within layers for the same node
        for (int uIdx = 0; uIdx < n; uIdx++) {
            for (int layer = 0; layer < mxt - 1; layer++) {
                int fromNode = layer * n + uIdx;
                int toNode = (layer + 1) * n + uIdx;
                adde(fromNode, toNode, k, 0);
            }
        }

        // Connecting layers to sink with cost
        fn = (t = totalNodes) + 1;
        s = 0;
        t = totalNodes;
        for (int i = 0; i < mxt; i++) {
            adde(i * n, t, k, i * c);
        }

        Pair ans = mcmf();
        assert ans.first == k;
        System.out.println(ans.second);
    }
}

