                for (int i = 0; i < n; i++) {
                    if (dist[i] < Long.MAX_VALUE) {
                        potential[i] += dist[i];
                    }
                }

                for (int i = 0; i < n; i++) {
                    if (supply[i] < 0 && last[i] != null) {
                        long resid = -supply[i];
                        int v = i;
                        int s = -1;
                        while (last[v] != null) {
                            int idx = (int) last[v];
                            Edge e = null;
                            for (Edge ed : network.adj.get((int) e.src)) {
                                if ((long) ed.rev == idx) {
                                    e = ed;
                                    break;
                                }
                            }
                            if (e == null) break;
                            if (e.cap < resid) {
                                resid = e.cap;
                            }
                            v = e.src;
                        }
                        if (resid == 0) continue;
                        v = i;
                        while (last[v] != null) {
                            int idx = (int) last[v];
                            Edge e = null;
                            for (Edge ed : network.adj.get((int) e.src)) {
                                if ((long) ed.rev == idx) {
                                    e = ed;
                                    break;
                                }
                            }
                            if (e == null) break;
                            e.cap -= resid;
                            e.rev.cap += resid;
                            v = e.src;
