    static class MCMF {
        int n, m;
        ArrayList<Edge> e = new ArrayList<>();
        ArrayList<Integer>[] g = new ArrayList[maxn];
        int[] inq = new int[maxn];
        int[] d = new int[maxn];
        int[] p = new int[maxn];
        int[] a = new int[maxn];

        public MCMF() {
            for (int i = 0; i < maxn; i++) {
                g[i] = new ArrayList<>();
            }
        }

        void init(int n) {
            this.n = n;
            for (int i = 0; i <= n; i++) {
                g[i].clear();
            }
            e.clear();
        }

        void add(int from, int to, int cap, int cost) {
            e.add(new Edge(from, to, cap, 0, cost));
            e.add(new Edge(to, from, 0, 0, -cost));
            int m = e.size();
            g[from].add(m - 2);
            g[to].add(m - 1);
        }

        boolean bellman(int s, int t, int[] flowRef, int[] costRef) {
            Arrays.fill(d, (int) inf);
            Arrays.fill(inq, 0);
            d[s] = 0; inq[s] = 1; p[s] = -1; a[s] = Integer.MAX_VALUE;
            Queue<Integer> Q = new LinkedList<>();
            Q.offer(s);
            while (!Q.isEmpty()) {
                int u = Q.poll();
                inq[u] = 0;
                for (int i : g[u]) {
                    Edge ee = e.get(i);
                    if (ee.cap > ee.flow && d[ee.to] > d[u] + ee.cost) {
                        d[ee.to] = d[u] + ee.cost;
                        p[ee.to] = i;
                        a[ee.to] = Math.min(a[u], ee.cap - ee.flow);
                        if (inq[ee.to] == 0) {
                            Q.offer(ee.to);
                            inq[ee.to] = 1;
                        }
                    }
                }
            }
            if (d[t] == (int) inf)
                return false;
            flowRef[0] += a[t];
            costRef[0] += d[t] * a[t];
            int u = t;
            while (u != s) {
                Edge e1 = e.get(p[u]);
                e1.flow += a[t];
