public class Main {
    static final int maxn = 5000010;
    static final int inf = 1000000000;

    static int n, m, k, v1, v2, s, t;
    static int[] dis = new int[maxn];
    static boolean[] vis = new boolean[maxn];

    static class Edge {
        int to, nxt, v, c;
        public Edge(int to, int nxt, int v, int c) {
            this.to = to;
            this.nxt = nxt;
            this.v = v;
            this.c = c;
        }
    }

    static Edge[] e = new Edge[maxn * 4]; // allocate enough space
    static int[] head = new int[maxn];
    static int edge_cnt;

    static int p(int x, int k) {
        return x + (k - 1) * n;
    }

    static void add(int from, int to, int val, int cost) {
        e[++edge_cnt] = new Edge(to, head[from], val, cost);
        head[from] = edge_cnt;
        e[++edge_cnt] = new Edge(from, head[to], 0, -cost);
        head[to] = edge_cnt;
    }

    static boolean spfa() {
        Queue<Integer> q = new LinkedList<>();
        for (int i = s; i <= t; ++i) {
            dis[i] = inf;
            vis[i] = false;
        }
        q.add(s);
        dis[s] = 0;
        vis[s] = true;
        while (!q.isEmpty()) {
            int x = q.poll();
            vis[x] = false;
            for (int i = head[x]; i != 0; i = e[i].nxt) {
                int y = e[i].to;
                int c = e[i].c;
                if (dis[y] <= dis[x] + c || e[i].v == 0) continue;
                dis[y] = dis[x] + c;
                if (!vis[y]) {
                    vis[y] = true;
                    q.add(y);
                }
            }
        }
        return dis[t] != inf;
    }

    static int dfs(int x, int lim) {
        if (x == t) return lim;
        vis[x] = true;
        int res = lim;
        for (int i = head[x]; i != 0; i = e[i].nxt) {
            int y = e[i].to;
            int v = e[i].v;
            if (dis[y] != dis[x] + e[i].c || v == 0 || vis[y]) continue;
            int flow = dfs(y, Math.min(res, v));
            if (flow > 0) {
                e[i].v -= flow;
                e[(i ^ 1)].v += flow;
                res -= flow;
                if (res == 0) break;
            }
        }
        return lim - res;
    }

