import java.util.*;

public class FlowNetwork {
    static class Edge {
        int b, l, c, ne;
        public Edge(int b, int c, int l, int ne) {
            this.b = b;
            this.c = c;
            this.l = l;
            this.ne = ne;
        }
    }

    static final int MAXN = 55;
    static final int MAXT = 2 * MAXN;
    static final int MAXP = 2 * MAXN * MAXN;
    static final int MAXE = 5 * MAXT * MAXN * MAXN;
    static final int INF = 1000000000;

    static int[] cnt = new int[MAXN];
    static int[][] id = new int[MAXN][MAXT];
    static boolean[] flag = new boolean[MAXE];
    static int[] dis = new int[MAXP];
    static List<Edge> eg = new ArrayList<>();
    static int[] egh = new int[MAXP];
    static int et, eCount, S, E, pct;

    static int N, M, K, C, D;

    static int min(int a, int b) { return a < b ? a : b; }
    static int max(int a, int b) { return a > b ? a : b; }

    static int rd(Scanner sc) {
        return sc.nextInt();
    }

    static boolean spfa() {
        for (int i = 1; i <= pct; i++) {
            flag[i] = false;
            dis[i] = INF;
        }
        dis[S] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(S);
        while (!q.isEmpty()) {
            int p = q.poll();
            flag[p] = false;
            for (int i = egh[p]; i != 0; i = eg.get(i).ne) {
                Edge e = eg.get(i);
                if (e.l == 0) continue;
                int b = e.b;
                if (dis[b] > dis[p] + e.c) {
                    dis[b] = dis[p] + e.c;
                    if (!flag[b]) {
                        q.offer(b);
                        flag[b] = true;
                    }
                }
            }
        }
        return dis[E] < INF;
    }

    static int dinic(int x, int y) {
        if (x == S) return y;
        flag[x] = true;
        int tmp = y;
        for (int i = egh[x]; i != 0; i = eg.get(i).ne) {
            Edge e = eg.get(i);
            int b = e.b;
            if (flag[b] || e.l == 0 || dis[x] < dis[b] + e.c) continue;
            int re = dinic(b, min(tmp, e.l));
            if (re > 0) {
                e.l -= re;
                eg.get(i ^ 1).l += re;
                tmp -= re;
                if (tmp == 0) break;
            }
        }
        return y - tmp;
    }

    static void addEdge(int a, int b, int c, int l) {
        eg.add(new Edge(b, c, l, egh[a]));
        egh[a] = ++et;
    }

    static void add(int a, int b, int c, int l) {
        addEdge(a, b, c, l);
        addEdge(b, a, -c, 0);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        eCount = 0;
        et = 1; // edges are 1-based
        Arrays.fill(egh, 0);
        eg.clear();

        N = rd(sc);
        M = rd(sc);
        K = rd(sc);
        C = rd(sc);
        D = rd(sc);
        for (int i = 1; i <= K; i++) {
            cnt[i] = 0;
            int tmp = rd(sc);
            cnt[i] = tmp;
        }

        pct = 2;
        int totalNodes = N * (K + M + 2) + 2;
        S = 1;
        E = 2;
        for (int i = 1; i <= N; i++) {
            for (int j = 1; j <= K + M + 2; j++) {
                id[i][j] = ++pct;
                if (i == 1) {
                    add(id[i][j], E, C * (j - 1), Integer.MAX_VALUE);
                }
                if (j > 1) {
                    add(id[i][j - 1], id[i][j], 0, Integer.MAX_VALUE);
                }
            }
            if (cnt[i] > 0) {
                add(S, id[i][1], 0, cnt[i]);
            }
        }

        for (int i = 1; i <= M; i++) {
            int a = rd(sc);
            int b = rd(sc);
            for (int j = 1; j <= K + M + 1; j++) {
                for (int k = 1; k <= 2 * K - 1; k += 2) {
                    add(id[a][j], id[b][j + 1], k * D, 1);
                    add(id[b][j], id[a][j + 1], k * D, 1);
                }
            }
        }

        int totalFlow = 0;
        long totalCost = 0;
        while (spfa()) {
            Arrays.fill(flag, false);
            int flow;
            while ((flow = dinic(E, Integer.MAX_VALUE)) > 0) {
                totalFlow += flow;
                totalCost += (long) dis[E] * flow;
            }
        }
        if (totalFlow != K) {
            System.out.println("0");
            return;
        }
        System.out.println(totalCost);
    }
}

