            v = new int[n];
            prio = new int[n];
            curflow = new int[n];
            prevedge = new int[n];
            prevnode = new int[n];
            pot = new int[n];
            adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
        }

        public void addEdge(int s, int t, int cap, int cost) {
            Edge a = new Edge(t, 0, cap, cost, adj.get(t).size());
            Edge b = new Edge(s, 0, 0, -cost, adj.get(s).size());
            adj.get(s).add(a);
            adj.get(t).add(b);
        }

        public int[] minCostFlow(int s, int t) {
            int flow = 0;
            int flowCost = 0;
            final int INF = (int)1e9;
            PriorityQueue<Long> q = new PriorityQueue<>();

            while (true) {
                q.clear();
                Arrays.fill(prio, Integer.MAX_VALUE);
                prio[s] = 0;
                curflow[s] = Integer.MAX_VALUE;
                q.offer(((long)prio[s] << 32) + s);

                while (!q.isEmpty()) {
                    long cur = q.poll();
                    int d = (int)(cur >> 32);
                    int uNode = (int)(cur & 0xffffffffL);
                    if (d != prio[uNode])
                        continue;
                    for (int i = 0; i < adj.get(uNode).size(); ++i) {
                        Edge e = adj.get(uNode).get(i);
