        int v, c, w, next;
        int rev;  // index of the reverse edge
        Edge(int v, int c, int w, int next, int rev) {
            this.v = v;
            this.c = c;
            this.w = w;
            this.next = next;
            this.rev = rev;
        }
    }

    static void addEdge(int a, int b, int c, int w) {
        edges.add(new Edge(b, c, w, head[a], edgeIndex + 1));
        int revIndexA = edgeIndex++;
        edges.add(new Edge(a, 0, -w, head[b], revIndexA));
        int revIndexB = edgeIndex++;
        head[a] = revIndexA;
        head[b] = revIndexB;
