        static int[] fr = new int[N];
        static int[] id = new int[N];
        static int S, T, cost;
        static List<Edge> edges = new ArrayList<>();

        static class Edge {
            int to, next, val, cost;
            public Edge(int to, int next, int val, int cost) {
                this.to = to;
                this.next = next;
                this.val = val;
                this.cost = cost;
            }
        }

        static void init() {
            Arrays.fill(head, -1);
            edges.clear();
            cnt = 0;
            cost = 0;
        }

        static void ae(int u, int v, int w, int c) {
            edges.add(new Edge(v, head[u], w, c));
            head[u] = cnt++;
            edges.add(new Edge(u, head[v], 0, -c));
            head[v] = cnt++;
        }

        static boolean SPFA() {
            Arrays.fill(dis, Integer.MAX_VALUE / 2);
            dis[S] = 0;
            boolean[] in = new boolean[N];
            Queue<Integer> q = new LinkedList<>();
            q.offer(S);
            in[S] = true;
            while (!q.isEmpty()) {
                int x = q.poll();
                in[x] = false;
                for (int i = head[x]; i != -1; i = edges.get(i).next) {
                    Edge e = edges.get(i);
                    if (e.val == 0) continue;
                    if (dis[e.to] > dis[x] + e.cost) {
                        dis[e.to] = dis[x] + e.cost;
                        fr[e.to] = x;
                        id[e.to] = i;
                        if (!in[e.to]) {
                            in[e.to] = true;
                            q.offer(e.to);
                        }
                    }
                }
            }
            if (dis[T] == Integer.MAX_VALUE / 2) return false;
            int x = T, mn = Integer.MAX_VALUE / 2;
            while (x != S) {
                mn = Math.min(mn, edges.get(id[x]).val);
                x = fr[x];
            }
            cost += dis[T] * mn;
            x = T;
            while (x != S) {
                edges.get(id[x]).val -= mn;
                edges.get(id[x] ^ 1).val += mn;
                x = fr[x];
            }
            return true;
        }

        static int run() {
            while (SPFA()){}
            return cost;
        }
    }

