import java.util.*;
import java.io.*;

public class Main {
    static class MCMF {
        static final int N = 30000;
        static final int M = 7010010;
        int[] h = new int[N];
        int[] ing = new int[N];
        int[] pre = new int[N];
        int[] to = new int[M];
        int[] ne = new int[M];
        long[] cap = new long[M];
        long[] dis = new long[N];
        long[] cost = new long[M];
        int e, s, t, n;
        long flow, mincost;
        static final long INF = Long.MAX_VALUE / 2;

        void ini(int _n) {
            Arrays.fill(h, -1);
            n = _n;
            e = 0;
        }

        void liu(int u, int v, long c, long w) {
            to[e] = v;
            ne[e] = h[u];
            cap[e] = c;
            cost[e] = w;
            h[u] = e++;
        }

        void link(int u, int v, long c, long w) {
            liu(u, v, c, w);
            liu(v, u, 0, -w);
        }

        boolean spfa() {
            Arrays.fill(dis, INF);
            Arrays.fill(ing, 0);
            Queue<Integer> Q = new LinkedList<>();
            dis[s] = 0;
            Q.add(s);
            ing[s] = 1;
            while (!Q.isEmpty()) {
                int c = Q.poll();
                ing[c] = 0;
                for (int k = h[c]; k != -1; k = ne[k]) {
                    if (cap[k] > 0) {
                        int v = to[k];
                        if (dis[c] + cost[k] < dis[v]) {
                            dis[v] = dis[c] + cost[k];
                            pre[v] = k;
                            if (ing[v] == 0) {
                                Q.add(v);
                                ing[v] = 1;
                            }
                        }
                    }
                }
            }
            return dis[t] != INF;
        }

        Map<String, Integer> nodeMap;
        int nodeCount;

        void setNodes(int totalNodes) {
            nodeMap = new HashMap<>();
            nodeCount = totalNodes;
        }

        int getNodeId(int i, int j) {
            String key = i + "," + j;
            if (!nodeMap.containsKey(key)) {
                nodeMap.put(key, ++nodeCount);
            }
            return nodeMap.get(key);
        }

        Pair<Long, Long> run(int s, int t) {
            this.s = s;
            this.t = t;
            flow = 0;
            mincost = 0;
            while (spfa()) {
                long pl = Long.MAX_VALUE;
                int p, k;
                for (p = t; p != s; p = to[pre[p] ^ 1]) {
                    k = pre[p];
                    if (cap[k] < pl) {
                        pl = cap[k];
                    }
                }
                for (p = t; p != s; p = to[pre[p] ^ 1]) {
                    cap[pre[p]] -= pl;
                    cap[pre[p] ^ 1] += pl;
                }
                mincost += pl * dis[t];
                flow += pl;
            }
            return new Pair<>(flow, mincost);
        }
    }

    static class Pair<U, V> {
        public U first;
        public V second;
        public Pair(U f, V s) {
            first = f;
            second = s;
        }
    }

    static final long INF = Long.MAX_VALUE / 2;

    public static void main(String[] args) throws IOException {
