int cnt = 1, hed[N], to[N], nxt[N], val[N], w[N];
int dis[N], incf[N], pre[N]; bool inq[N];

void add(int x, int y, int z, int v) {
	to[++cnt] = y, nxt[cnt] = hed[x], hed[x] = cnt, val[cnt] = z, w[cnt] = v;
	to[++cnt] = x, nxt[cnt] = hed[y], hed[y] = cnt, val[cnt] = 0, w[cnt] = -v;
}
bool spfa() {
	memset(incf, 0, sizeof(incf)), memset(dis, INF, sizeof(dis));
	memset(inq, 0, sizeof(inq)); queue<int> q;
	q.push(s), incf[s] = INF, inq[s] = 1, dis[s] = 0;
	for(; !q.empty();) {
		int u = q.front(); q.pop(); inq[u] = 0;
		for(int i = hed[u]; i; i = nxt[i]) {
			if(!val[i] || dis[to[i]] <= dis[u] + w[i]) continue;
			dis[to[i]] = dis[u] + w[i];
			incf[to[i]] = min(incf[u], val[i]);
			pre[to[i]] = i; if(!inq[to[i]]) inq[to[i]] = 1, q.push(to[i]);
		}
	}
	return dis[t] != INF;
}
void update() {
	int tmp = t;
	for(; tmp != s;) {
		int i = pre[tmp];
		val[i] -= incf[t], val[i ^ 1] += incf[t], tmp = to[i ^ 1];
	}
	ans += incf[t] * dis[t];
}
int main() {
	scanf("%d%d%d%d%d", &n, &m, &k, &c, &d), t = (n + k - 1) * n + 1;
	for(int i = 1, x; i <= k; i++) scanf("%d", &x), add(s, x, 1, 0);
	for(int i = 1, x, y; i <= m; i++) {
		scanf("%d%d", &x, &y);
		for(int j = 1; j <= n + k; j++)
			for(int h = 1; h <= k; h++) {
				add(x + (j - 1) * n, y + j * n, 1, d * h * 2 - d + c);
				add(y + (j - 1) * n, x + j * n, 1, d * h * 2 - d + c);
			}
	}
	for(int i = 1; i < n + k; i++) {
		for(int j = 2; j <= n; j++)
			add(j + (i - 1) * n, j + i * n, INF, c);
		add(1 + (i - 1) * n, 1 + i * n, INF, 0);
	}
	for(; spfa();) update();
	printf("%d\n", ans);
	return 0;
