import java.util.*;
import java.io.*;

class MinCostMaxFlow {
    static class Edge {
        int src, dst, rev;
        long flow, cap;
        long cost;
        public Edge(int src, int dst, int rev, long flow, long cap, long cost) {
            this.src = src;
            this.dst = dst;
            this.rev = rev;
            this.flow = flow;
            this.cap = cap;
            this.cost = cost;
        }
    }

    int n;
    List<List<Edge>> adj;
    long[] potential;
    long oo = Long.MAX_VALUE;
    long[] dist;
    Edge[] back;

    public MinCostMaxFlow(int n) {
        this.n = n;
        this.adj = new ArrayList<>();
        for (int i=0; i<n; i++) {
            adj.add(new ArrayList<>());
        }
        potential = new long[n];
        dist = new long[n];
        back = new Edge[n];
    }

    public void addEdge(int src, int dst, long cap, long cost) {
        Edge e1 = new Edge(src, dst, adj.get(dst).size(), 0, cap, cost);
        Edge e2 = new Edge(dst, src, adj.get(src).size(), 0, 0, -cost);
        adj.get(src).add(e1);
        adj.get(dst).add(e2);
    }

    private long rcost(Edge e) {
        return e.cost + potential[e.src] - potential[e.dst];
    }

    private long dijkstra(int source, int sink) {
        Arrays.fill(dist, oo);
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        dist[source] = 0;
        pq.offer(new long[]{0, source});
        while (!pq.isEmpty()) {
            long[] p = pq.poll();
            long d = p[0];
            int u = (int)p[1];
            if (dist[u] < d) continue;
            if (u == sink) break;
            for (Edge e : adj.get(u)) {
                if (e.flow < e.cap && dist[e.dst] > dist[e.src] + rcost(e)) {
                    dist[e.dst] = dist[e.src] + rcost(e);
                    back[e.dst] = e;
                    pq.offer(new long[]{dist[e.dst], e.dst});
                }
            }
        }
        return dist[sink];
    }

    public long[] maxFlow(int source, int sink) {
        long flow = 0;
        long cost = 0;
        for (List<Edge> edges : adj) {
            for (Edge e : edges) e.flow = 0;
        }
        Arrays.fill(potential, 0);
        Arrays.fill(dist, 0);
        Arrays.fill(back, null);
        while (dijkstra(source, sink) < oo) {
            for (int u=0; u<n; u++) {
                if (dist[u] < dist[sink]) {
                    potential[u] += dist[u] - dist[sink];
                }
            }
            long f = Long.MAX_VALUE;
            for (Edge e = back[sink]; e != null; e = back[e.src]) {
                f = Math.min(f, e.cap - e.flow);
            }
            for (Edge e = back[sink]; e != null; e = back[e.src]) {
                e.flow += f;
                adj.get(e.dst).get(e.rev).flow -= f;
            }
            flow += f;
            cost += f * (potential[sink] - potential[source]);
        }
        return new long[]{flow, cost};
    }
}

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int size = (n + 2) * 102;
        MinCostMaxFlow g = new MinCostMaxFlow(size);
        for (int i=0; i<102; i++) {
            g.addEdge(i*(n+2)+1, i*(n+2), 100, i*c);
        }
        for (int i=0; i<101; i++) {
            for (int j=0; j<n+1; j++) {
                int from = j + (i*(n+2));
                int to = j + ((i+1)*(n+2));
                g.addEdge(from, to, 100, 0);
            }
        }

        int[] uArr = new int[k];
        for (int i=0; i<k; i++) {
            uArr[i] = Integer.parseInt(br.readLine());
            g.addEdge(n+1, uArr[i], 1, 0);
        }

        for (int i=0; i<m; i++) {
            st=new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            for (int j=0; j<101; j++) {
                for (int f=0; f<k; f++) {
                    long costVal = ((2*f)+1)*d;
                    g.addEdge(u + (j*(n+2)), v + ((j+1)*(n+2)), 1, costVal);
                    g.addEdge(v + (j*(n+2)), u + ((j+1)*(n+2)), 1, costVal);
                }
            }
        }

        long[] result = g.maxFlow(n+1, 101*(n+2));
        System.out.println(result[1]);
    }
}

