public class Main {
    static class Edge {
        int from, to;
        long cap, cost, flow;
        Edge(int from, int to, long cap, long cost) {
            this.from = from; this.to = to; this.cap = cap; this.cost = cost; this.flow = 0;
        }
    }

    static final int maxn = 5007;
    static final long INF = (long) 1e9;

    static ArrayList<Edge> edges = new ArrayList<>();
    static List<Integer>[] g = new ArrayList[maxn];
    static long[] d = new long[maxn], phi = new long[maxn];
    static int[] par = new int[maxn];

