        Arrays.fill(dis, inf);
        Arrays.fill(vis, false);
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        dis[s] = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            vis[u] = false;
            for (int i = head[u]; i != 0; i = edges.get(i - 1).next) {
                Edge e = edges.get(i - 1);
