            int flow = inf;
            for (int x = t; x != s; x = edges.get(pre[x] ^ 1).to) {
                flow = Math.min(flow, edges.get(pre[x] - 1).val);
            }
            for (int x = t; x != s; x = edges.get(pre[x] ^ 1).to) {
