import java.util.*;

public class MinCostFlow {
    static class Edge {
        int u, v;
        int cap, flow;
        int cost;

        public Edge(int u, int v, int cap, int flow, int cost) {
            this.u = u;
            this.v = v;
            this.cap = cap;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static class MCMF {
        int n, m, s, t;
        List<List<Integer>> G;
        List<Edge> E;
        int[] p, inq;
        long[] d, a;

        public MCMF(int n) {
            this.n = n;
            G = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                G.add(new ArrayList<>());
            }
            E = new ArrayList<>();
            p = new int[n];
            inq = new int[n];
            d = new long[n];
            a = new long[n];
        }

        void addEdge(int u, int v, int cap, int cost) {
            E.add(new Edge(u, v, cap, 0, cost));
            E.add(new Edge(v, u, 0, 0, -cost));
            m = E.size();
            G.get(u).add(m - 2);
            G.get(v).add(m - 1);
        }

        boolean BelmanFord(long[] flowOut, long[] costOut) {
            Arrays.fill(d, Long.MAX_VALUE);
            Arrays.fill(inq, 0);
            d[s] = 0;
            p[s] = -1;
            a[s] = Long.MAX_VALUE;

            Queue<Integer> Q = new LinkedList<>();
            Q.offer(s);
            inq[s] = 1;

            while (!Q.isEmpty()) {
                int u = Q.poll();
                inq[u] = 0;
                for (int idx : G.get(u)) {
                    Edge e = E.get(idx);
                    if (e.cap > e.flow && d[e.v] > d[u] + e.cost) {
                        d[e.v] = d[u] + e.cost;
                        p[e.v] = idx;
                        a[e.v] = Math.min(a[u], e.cap - e.flow);
                        if (inq[e.v] == 0) {
                            Q.offer(e.v);
                            inq[e.v] = 1;
                        }
                    }
                }
            }

            if (d[t] == Long.MAX_VALUE)
                return false; // no augmenting path

            long flowVal = a[t];
            long costVal = d[t];
            int u = t;
            while (u != s) {
                int edgeIdx = p[u];
                E.get(edgeIdx).flow += flowVal;
                E.get(edgeIdx ^ 1).flow -= flowVal;
                u = E.get(edgeIdx).u;
            }
            flowOut[0] += flowVal;
            costOut[0] += flowVal * costVal;
            return true;
        }

        long[] Mincost(int s, int t) {
            this.s = s;
            this.t = t;
            long totalFlow = 0;
            long totalCost = 0;
            long[] flowArr = new long[1];
            long[] costArr = new long[1];
            while (BelmanFord(flowArr, costArr)) {
                totalFlow += flowArr[0];
                totalCost += costArr[0];
            }
            return new long[]{totalFlow, totalCost};
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(); // number of nodes
        int m = sc.nextInt(); // number of edges
        int k = sc.nextInt(); // number of units per node
        int C = sc.nextInt(); // cost comparison values
        int D = sc.nextInt(); // delay factor

        int totalNodes = n * k + 2;
