            for (int j = 1; j < k; j++) {
                int a = u * k + j - 1;
                int b = v * k + j;
                int c = v * k + j - 1;
                int d = u * k + j;
                for (int cnt = 1, cc = D; cnt <= k; cnt++, cc += 2 * D) {
                    solver.addEdge(a, b, 1, cc);
                    solver.addEdge(c, d, 1, cc);
                }
            }
        }

        long[] result = solver.Mincost(source, sink);
        System.out.println(result[1]);
        sc.close();
    }
}

