	vector<pair<int, int> > make(char *str, int &root) {
		int i, cur = 1;
		vector<pair<int, int> > E(10000);
		stack<int> S;
		for (i = 0; str[i]; i++) {
			char cc = str[i];
			if (cc >= '1' && cc <= '9') {
				E[cur].first = cc - '0';
				E[cur].second = 0;
				S.push(cur);
				cur++;
			}
			else if (cc == ')') {
				int a, b;
				a = S.top(); S.pop();
				b = S.top(); S.pop();
				E[cur].first = a; E[cur].second = b;
				S.push(cur);
				cur++;
			}
		}
		root = cur - 1;
		return E;
	}
