import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] a = new int[6];

        int n = sc.nextInt();

        if (n - 0 > 0) {
            a[0] = sc.nextInt();
        }
        if (n - 1 > 0) {
            a[1] = sc.nextInt();
        }
        if (n - 2 > 0) {
            a[2] = sc.nextInt();
        }
        if (n - 3 > 0) {
            a[3] = sc.nextInt();
        }
        if (n - 4 == 1) {
            a[4] = sc.nextInt();
        }
        n--;
        Arrays.sort(a, 0, n + 1);
        int t = (a[0] + a[n]) >> 1;

        int i = -1;
        int j = n + 1;
        while (i + 1 < n && a[++i] <= t);
        while (j - 1 >= 0 && a[--j] >= t);

        int result;
        if ((a[i] - t) < (t - a[j]) && (a[i] - t) < (a[i - 1] - t)) {
            result = a[i];
        } else if (i - 1 >= 0 && (a[i - 1] - t) < (a[j] - t) && (a[i - 1] - t) < (a[j] - t)) {
            result = a[i - 1];
        } else {
            result = a[j];
        }
        System.out.println(result);
