  int real_n, k;
  scanf("%d %d", &real_n, &k);
  int n = 0;
  for (int i = 0; i < real_n; i++) {
    scanf("%lf", real_p + i);
    if (real_p[i] > 1e-4) {
      id[n] = i;
      p[n++] = real_p[i];
    }
  }
  k = min(k, n);
  kb[0] = 0;
  for (int t = 1; t < (1 << n); t++) {
    kb[t] = kb[t & (t - 1)] + 1;
  }
  for (int t = 0; t < (1 << n); t++) {
    f[t] = 0.0;
