    if (kb[t] == k) {
      for (int j = 0; j < n; j++) {
        if (t & (1 << j)) {
          ans[id[j]] += f[t];
        }
      }
      continue;
    }
    double total = 0;
    for (int j = 0; j < n; j++) {
      if (t & (1 << j)) {
        continue;
      }
