            p[i] = sc.nextDouble();
        }

        double[][] dp = new double[2][1 << n];
        for (int i = 0; i < 2; i++) {
            Arrays.fill(dp[i], 0.0);
        }

        boolean[] isgood = new boolean[n];
        List<Integer> good = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (p[i] != 0) {
                isgood[i] = true;
                good.add(i);
            }
        }

        int c = 0;
        dp[0][0] = 1.0;

        double[] sum = new double[1 << n];
        sum[0] = 1.0;
        for (int j = 1; j < (1 << n); j++) {
            int x = Integer.numberOfTrailingZeros(j);
            sum[j] = sum[j ^ (1 << x)] - p[x];
        }

        int limit = Math.min(good.size(), k);
        for (int i = 0; i < limit; i++) {
            c = 1 - c;
            Arrays.fill(dp[c], 0.0);
            for (int j = 0; j < (1 << n); j++) {
                if (Integer.bitCount(j) != i)
                    continue;
                for (int next : good) {
                    if (((j >> next) & 1) == 0) {
                        double denom = sum[j];
                        if (denom != 0) {
                            dp[c][j ^ (1 << next)] += dp[1 - c][j] * p[next] / denom;
                        }
                    }
                }
            }
        }

        c = 1 - c;
