        final int N = 20;
        double[] _P = new double[N];
        double[] P = new double[N];
        double[] Q = new double[N];

        int[] ind = new int[N];

        int n = 0;
        double eps = 1e-9;

        for (int i = 0; i < _n; i++) {
            _P[i] = scanner.nextDouble();
            if (_P[i] > eps) {
                P[n] = _P[i];
                ind[i] = n;
                n++;
            } else {
                ind[i] = -1;
            }
        }

        k = Math.min(k, n);

        double[] D = new double[1 << N];
        double[] sum = new double[1 << N];

        // Initialize D and sum arrays
        D[0] = 1.0;
        for (int i = 1; i < (1 << n); i++) {
            sum[i] = 0.0;
        }

        for (int i = 1; i < (1 << n); i++) {
            for (int j = 0; j < n; j++) {
                if (((i >> j) & 1) != 0) {
                    sum[i] = sum[i ^ (1 << j)] + P[j];
                    break;
                }
            }
        }

