            dp[msk] = Div(ri, 1.0 - same);
        }

        Val tot = new Val(1.0, 0.0);
        for (int msk = 1; msk < (1 << n); msk++) {
            if (((msk & (1 << vr))) == 0) {
                tot = Add(tot, dp[msk]);
            }
        }

        double alp = (1.0 - tot.se) / tot.fi;

        Val bad = new Val(0.0, 0.0);
        for (int msk = 0; msk < (1 << n); msk++) {
            if ((msk & (1 << vr)) != 0) continue;
            int bitsCount = Integer.bitCount(msk);
            if (bitsCount >= k) {
                bad = Add(bad, dp[msk]);
            }
        }

        return 1.0 - (alp * bad.fi + bad.se);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        for (int i = 0; i < n; i++) {
            p[i] = sc.nextDouble();
        }

        for (int i = 0; i < n; i++) {
            System.out.printf("%.12f%c", Solve(i), (i + 1 == n ? '\n' : ' '));
        }
        sc.close();
    }
}

