        dp[0] = 1.0;
        int flag = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            int qb = countBits(mask);
            if (qb > k)
                continue;
            if (dp[mask] < 1e-100)
                continue;
            if (qb == k)
                flag = 1;
            double rem_sum = 1.0 - sum[mask];
            if (rem_sum < 1e-6)
                continue;
            for (int i = 0; i < n; i++) {
                if (((mask >> i) & 1) == 1)
                    continue;
                double chance_move = dp[mask] * prob[i] / rem_sum;
                dp[mask | (1 << i)] += chance_move;
            }
        }

        if (flag == 0) {
            for (int i = 0; i < n; i++) {
                if (prob[i] < 1e-6)
                    ans[i] = 0.0;
                else
                    ans[i] = 1.0;
            }
        } else {
            for (int mask = 0; mask < (1 << n); mask++) {
                if (countBits(mask) == k) {
                    for (int i = 0; i < n; i++) {
                        if (((mask >> i) & 1) == 1)
                            ans[i] += dp[mask];
                    }
                }
            }
        }

        System.out.printf("%.12f", ans[0]);
        for (int i = 1; i < n; i++) {
            System.out.print(" ");
            System.out.printf("%.12f", ans[i]);
        }
        System.out.println();
        scanner.close();
    }
}

