import java.util.Scanner;

public class Main {
    static class DSU {
        int[] r, p;

        public void init(int n) {
            r = new int[n];
            p = new int[n];
            for (int i = 0; i < n; i++) {
                p[i] = i;
                r[i] = 1;
            }
        }

        public int par(int i) {
            if (i == p[i]) return i;
            return p[i] = par(p[i]);
        }

        public void unite(int i, int j) {
            i = par(i);
            j = par(j);
            if (i == j) return;
            if (r[i] < r[j]) {
                int temp = i;
                i = j;
                j = temp;
            }
            p[j] = i;
            r[i] += r[j];
        }
    }

    static long pw(long x, long p, long M) {
        long r = 1;
        while (p > 0) {
            if ((p & 1) == 1) r = (r * x) % M;
            x = (x * x) % M;
            p >>= 1;
        }
        return r;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();

        final long mod = 1000000007;

        if (k == 0) {
            System.out.println(pw(n, n - 1, mod));
            sc.close();
            return;
        }

        DSU d = new DSU();
        d.init(n);
        for (int i = 0; i < n; i++) {
            d.unite(i, (int)((long)i * k % n));
        }

        long ans = 1;
        for (int i = 0; i < n; i++) {
            if (d.par(i) != i) continue;
            long t = pw(k, d.r[d.par(i)], n);
            if (t == 1) {
                ans = (ans * n) % mod;
            }
        }
        System.out.println(ans);
        sc.close();
    }
}

