            rnk = new int[n];
            comps = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int u) {
            if (parent[u] != u) {
                parent[u] = find(parent[u]);
            }
            return parent[u];
        }

        public void merge(int u, int v) {
            u = find(u);
            v = find(v);
            if (u == v) return;
            if (rnk[u] > rnk[v]) {
                int temp = u;
                u = v;
                v = temp;
            }
            parent[u] = v;
            if (rnk[u] == rnk[v]) {
                rnk[v]++;
            }
            comps--;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        boolean[] seen = new boolean[(int)p];
        DisjointSet dsu = new DisjointSet((int)p);

        for (long i = 0; i < p; i++) {
            for (long j = i; !seen[(int)j]; j = (j * k) % p) {
                seen[(int)j] = true;
                dsu.merge((int)i, (int)j);
            }
        }

        int c = dsu.comps;
        if (k != 1) c--;
        System.out.println(modpow(p, c));
        sc.close();
    }
}

