import java.util.Scanner;

public class Main {
    static final long e5 = 100000L;
    static final long e6 = 1000000L;
    static final long e7 = 10000000L;
    static final long e9 = 1000000000L;
    static final long MOD = e9 + 7;

    // (base^power) % mod, safe for long
    static long pow_mod(long base, long power, long mod) {
        long result = 1;
        while (power > 0) {
            if ((power & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            power >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLong()) {
            long p = sc.nextLong();
            long k = sc.nextLong();

            if (k == 0) {
                System.out.println(pow_mod(p, p - 1, MOD));
                continue;
            }
            if (k == 1) {
                System.out.println(pow_mod(p, p, MOD));
                continue;
            }
            boolean[] bs = new boolean[(int) p];
            long pow = 0;
            for (long i = 1; i < p; i++) {
                if (bs[(int) i]) continue;
                long j = i;
                long w = 0;
                while (!bs[(int) j]) {
                    w++;
                    bs[(int) j] = true;
                    j = (j * k) % p;
                }
                if (pow_mod(k, w, p) == 1) pow++;
            }
            System.out.println(pow_mod(p, pow, MOD));
        }
        sc.close();
    }
}

