public class Main {
    static final long mod = 1000000007;

    // Recursive modular exponentiation
    static long mu(long x, long y) {
        if (y == 1) return x % mod;
        long tmp = mu(x, y / 2);
        tmp = (tmp * tmp) % mod;
        if (y % 2 == 0) return tmp;
        return (tmp * x) % mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(mu(p, p - 1));
        } else if (k == 1) {
            System.out.println(mu(p, p));
        } else {
            int m = 1;
            int t = k;
            while (true) {
                m++;
                t = (int) ((long) t * k % p);
                if (t == 1) {
                    System.out.println(mu(p, (p - 1) / m));
                    break;
                }
            }
        }
        sc.close();
    }
}

