public class Main {
    static final double PI = 3.1415926535897932384626433832795028841971693992;
    static final int mod = 1000000007;

    static long pow(long a, long p) {
        long res = 1;
        while (p > 0) {
            if (p % 2 == 1) {
                res *= a;
                res %= mod;
            }
            a *= a;
            a %= mod;
            p /= 2;
        }
