            a = (a * a) % mod;
            b >>= 1;
        }
        return tmp;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLong()) {
            long p = sc.nextLong();
            long k = sc.nextLong();

            if (k == 0) {
                System.out.println(fun1(p, p - 1));
                continue;
            }

            if (k == 1) {
                System.out.println(fun1(p, p));
                continue;
            }

            long sum = 0;
            long tmp = 1;
            long next = -1;
            while (next != 1) {
                next = (k * tmp) % p;
                tmp = next;
                sum++;
            }
            System.out.println(fun1(p, (p - 1) / sum));
        }
        sc.close();
    }
}

