public class Main {
    static long[] parent;
    static long[] rating;
    static final long mod = 1000000007;

    static long getBit(long n, int i) {
        return ((n & (1L << i)) != 0) ? 1 : 0;
    }

    static long setBit0(long n, int i) {
        return n & (~(1L << i));
    }

    static long setBit1(long n, int i) {
        return n | (1L << i);
    }

    static long toggleBit(long n, int i) {
        return n ^ (1L << i);
    }

    static long lastOne(long n) {
        return n & (-n);
    }

    static void readLong(BufferedReader br, StringTokenizer st, long[] x) throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        x[0] = Long.parseLong(st.nextToken());
    }

    static long findParent(long root) {
        while (parent[(int) root] != root) {
            root = parent[(int) root];
        }
        return root;
    }

    static void findUnion(long root1, long root2) {
        long par1 = findParent(root1);
        long par2 = findParent(root2);
        if (rating[(int) par1] >= rating[(int) par2]) {
            parent[(int) par2] = par1;
            rating[(int) par1]++;
        } else {
            parent[(int) par1] = par2;
            rating[(int) par2]++;
        }
    }

    static void ini(int n) {
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
            rating[i] = 0;
        }
    }

    static long modularExponentiation(long x, long n, long M) {
        if (n == 0)
            return 1;
        if (n % 2 == 0)
            return modularExponentiation((x * x) % M, n / 2, M);
        else
            return (x * modularExponentiation((x * x) % M, (n - 1) / 2, M)) % M;
    }

