template<typename T>
static T FastPow(const T a, const T p)
{
    T res = 1;

    T mask = 1;
    T powPart = a;

    const size_t bitsCount = sizeof(T) * 8;
    for (size_t i = 0; i < bitsCount; i++)
    {
        if (p & mask)
        {
            res *= powPart;
            res %= Mod;
        }
        mask <<= 1;
        powPart *= powPart;
        powPart %= Mod;
    }

    return res;
}

