            long p = Long.parseLong(parts[0]);
            long k = Long.parseLong(parts[1]);
            boolean res = solve(p, k, out);
            if (!res) {
                break;
            }
            // If not multiple test mode, break after first
            if (!multipleTestMode) {
                break;
            }
        }
        out.flush();
    }

    static boolean solve(long p, long k, PrintWriter out) {
        if (k == 0) {
            long ans = fastPow(p, p - 1);
            out.println(ans);
            return true;
        }
        if (k == 1) {
            long ans = fastPow(p, p);
            out.println(ans);
            return true;
        }
        long groups = 0;
        boolean[] used = new boolean[(int) p + 1];
        long ans = 1;

        for (long x = 1; x < p; x++) {
            if (used[(int) x]) {
                continue;
            }

            groups += 1;
            ans = (ans * p) % MOD;

            long v = x;
            while (!used[(int) (v * k % p)]) {
                used[(int) (v * k % p)] = true;
                v = (v * k) % p;
            }
        }
        out.println(ans);
        return true;
    }

    static long fastPow(long a, long p) {
        long res = 1;
        long base = a % MOD;
        while (p > 0) {
            if ((p & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            p >>= 1;
        }
        return res;
    }
}

