import java.util.Scanner;

public class Main {
    static long mod = 1000000007L;
    static int[] P = new int[1000001];

    static int add(int i, int j) {
        long res = i + j;
        return (int) (res < mod ? res : res - mod);
    }

    static int mult(long i, long j) {
        return (int) ((i * j) % mod);
    }

    static int pwr(int i, int k) {
        long r = 1;
        long base = i;
        int exponent = k;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                r = mult(r, base);
            }
            base = mult(base, base);
            exponent >>= 1;
        }
        return (int) r;
    }

    static int beb(int a, int m) {
        for (int i = 0; i < P.length; ++i) {
            P[i] = -1;
        }
        int s = (int) Math.sqrt(m);
        long originalMod = mod;
        mod = m;
        int r = 1 % m;
        int d = pwr(a, m - 2);
        for (int i = 0; i <= s; i++) {
            if (P[r] == -1) P[r] = i;
            r = mult(r, d);
            if (r == 1 % m) {
                mod = (int) originalMod;
                return i + 1;
            }
        }

        d = pwr(a, s);
        r = d;
        for (int i = 1; i <= s; i++) {
            if (P[r] > -1) {
                mod = (int) originalMod;
                return s * i + P[r];
            }
            r = mult(r, d);
        }
        mod = (int) originalMod;
        return -1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();

        if (k == 1) {
            System.out.println(pwr(p, p));
        } else if (k == 0) {
            System.out.println(pwr(p, p - 1));
        } else {
            int result = pwr(p, (p - 1) / beb(k, p));
            System.out.println(result);
        }
        scanner.close();
    }
}

