            if (a == parent[(int)a]) {
                return a;
            }
            long base = findSet(parent[(int)a]);
            parent[(int)a] = base;
            return base;
        }

        void unionSet(long a, long b) {
            a = findSet(a);
            b = findSet(b);
            if (a != b) {
                Random rand = new Random();
                if (rand.nextInt(2) == 0) {
                    long temp = a;
                    a = b;
                    b = temp;
                }
                parent[(int)b] = a;
            }
        }
    }

    static long countCycles(int p, int k) {
        DSU dsu = new DSU(p);
        for (int i = 1; i < p; i++) {
            int ki = (k * i) % p;
            dsu.unionSet(i, ki);
        }

        boolean[] found = new boolean[p];
        long count = 0;
        for (int i = 1; i < p; i++) {
            long base = dsu.findSet(i);
            if (!found[(int)base]) {
                found[(int)base] = true;
                count++;
            }
        }
        return count;
    }

    static long countSolutions(int p, int k) {
        long cycles;
        if (k == 0) {
            cycles = p - 1;
        } else if (k == 1) {
            cycles = p;
        } else {
            cycles = countCycles(p, k);
        }

        long count = 1L;
        for (int i = 0; i < cycles; i++) {
            count = (count * p) % MOD;
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        long count = countSolutions(p, k);
        System.out.println(count);
        int end = sc.nextInt();
        sc.close();
    }
}

