import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        Arrays.sort(a);
        int t = sc.nextInt();
        int ans = -1;
        for (int i = 0; i < n; i++) {
            int up = upperBound(a, a[i] + t);
            if (up - i > ans) {
                ans = up - i;
            }
        }
        System.out.println(ans);
        sc.close();
    }

    // Implementing upper_bound similar to C++ std::upper_bound
    private static int upperBound(int[] arr, int key) {
        int left = 0, right = arr.length;
        while (left < right) {
            int mid = (left + right) / 2;
            if (arr[mid] <= key) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }
}

