			if (mat[bi*n+bj][p] < dis || t < dis) vis[p] = INF+1;
			continue;
		}
		for (int d = 0; d < 4; ++d)
		{
			int i = dir[d][0]+now.F;
			int j = dir[d][1]+now.S;
			if (i < 0 || j < 0 || i == n || j == n) continue;
			if (b[i][j] < '0' || b[i][j] > '9') continue;
			int q = i*n+j;
			if (vis[q] != INF) continue;
			vis[q] = dis+1;
			que.push(mp(i, j));
		}
	}
}

void build()
{
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
