        for (int i = 0; i < a.size(); i++) {
            for (int j = 0; j < a.size(); j++) {
                boolean okFlag = false;
                for (int k = 0; k <= t - 1; k++) {
                    if (moge[k][a.get(i).x][a.get(i).y][a.get(j).x][a.get(j).y]) {
                        okFlag = true;
                        break;
                    }
                }
                if (okFlag) {
                    G.get(i + 1).add(new Kraw(a.size() + 1 + j, 1000));
                    G.get(a.size() + 1 + j).add(new Kraw(i + 1, 0));
                }
            }
        }

        int odp = 0;
        while (true) {
            boolean[] odw = new boolean[wie];
            Arrays.fill(odw, false);
            Queue<Integer> Q2 = new LinkedList<>();
            odw[0] = true;
            Q2.add(0);
            int[] pop = new int[wie];
            Arrays.fill(pop, -1);
            while (!Q2.isEmpty()) {
                int akt = Q2.poll();
                for (Kraw edge : G.get(akt)) {
                    if (!odw[edge.a] && edge.res > 0) {
                        Q2.add(edge.a);
                        pop[edge.a] = akt;
                        odw[edge.a] = true;
                    }
                }
            }
            if (pop[wie - 1] == -1) break;
            List<Integer> path = new ArrayList<>();
            int akt = wie - 1;
            while (akt != -1) {
                path.add(akt);
                akt = pop[akt];
            }
            Collections.reverse(path);
            int flow = Integer.MAX_VALUE;
            for (int i = 0; i < path.size() - 1; i++) {
                int from = path.get(i), to = path.get(i + 1);
                for (Kraw e : G.get(from)) {
                    if (e.a == to) {
                        flow = Math.min(flow, e.res);
                        break;
                    }
                }
            }
            odp += flow;
            for (int i = 0; i < path.size() - 1; i++) {
                int from = path.get(i), to = path.get(i + 1);
                for (Kraw e : G.get(from)) {
                    if (e.a == to) {
                        e.res -= flow;
                        break;
                    }
                }
                for (Kraw e : G.get(to)) {
                    if (e.a == from) {
