        public Edge(int from, int to, long flow, long capacity) {
            this.from = from;
            this.to = to;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static class Maxflow {
        int s, t;
        ArrayList<Edge> edges = new ArrayList<>();
        ArrayList<Integer>[] g = new ArrayList[MAX_SIZE];
        int[] dist = new int[MAX_SIZE];
        int[] visited = new int[MAX_SIZE];
        int[] cur = new int[MAX_SIZE];

        @SuppressWarnings("unchecked")
        public Maxflow() {
            for (int i = 0; i < MAX_SIZE; i++) {
                g[i] = new ArrayList<>();
            }
        }

        void init() {
            edges.clear();
            for (int i = 0; i < MAX_SIZE; i++) {
                g[i].clear();
            }
        }

        void addedge(int from, int to, long capacity) {
            Edge e1 = new Edge(from, to, 0L, capacity);
            Edge e2 = new Edge(to, from, 0L, 0L);
            edges.add(e1);
            edges.add(e2);
            g[from].add(edges.size() - 2);
            g[to].add(edges.size() - 1);
        }

        boolean bfs() {
            Arrays.fill(visited, 0);
            Arrays.fill(dist, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            visited[s] = 1;
            dist[s] = 0;
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int i = 0; i < g[v].size(); i++) {
                    Edge e = edges.get(g[v].get(i));
                    int nxt = e.to;
                    if (visited[nxt] == 0 && e.capacity > e.flow) {
                        dist[nxt] = dist[v] + 1;
                        q.offer(nxt);
                        visited[nxt] = 1;
                    }
                }
            }
            return visited[t] == 1;
        }

        long dfs(int x, long cp) {
            if (x == t || cp == 0) {
                return cp;
            }
            long flow = 0;
            for (int i = cur[x]; i < g[x].size(); i++) {
                Edge e = edges.get(g[x].get(i));
                int y = e.to;
                if (dist[x] + 1 == dist[y]) {
                    long minn = Math.min(cp, e.capacity - e.flow);
                    long newflow = dfs(y, minn);
                    if (newflow > 0) {
                        e.flow += newflow;
                        edges.get(g[x].get(i) ^ 1).flow -= newflow;
                        flow += newflow;
                        cp -= newflow;
                        if (cp == 0) {
                            break;
                        }
                    }
                }
            }
            cur[x] = Math.max(cur[x], 0);
            return flow;
        }

        long Dinic() {
            long flow = 0;
            while (bfs()) {
                Arrays.fill(cur, 0);
                flow += dfs(s, INF);
            }
            return flow;
        }
