        to[pa] = t;
        cap[pa] = c;
        ant[pa] = adj[f];
        adj[f] = pa++;
        // Reverse edge with capacity 0
        int fRev = f ^ 1;
        int tRev = t ^ 1;
        to[pa] = fRev;
        cap[pa] = 0;
        ant[pa] = adj[t];
        adj[t] = pa++;
    }

