    public int gao(int n, List<Integer>[] e){
        cnt=0;
        Arrays.fill(pos, -1);
        Arrays.fill(rev, -1);
        for(int i=0; i<n; i++){
            Arrays.fill(v,0);
            if(match(i,e)) cnt++;
        }
        return cnt;
    }

    private boolean match(int x, List<Integer>[] e){
        for(int y : e[x]){
            if(v[y]==0){
                v[y]=1;
                if(rev[y]==-1 || match(rev[y], e)){
                    pos[x]=y;
