import java.util.*;

public class Main {

    static final int MAXN = 12;
    static final int INF = 1000000;

    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static int N, T;
    static char[][] grid1 = new char[MAXN][MAXN];
    static char[][] grid2 = new char[MAXN][MAXN];
    static int[][] A = new int[MAXN][MAXN];
    static int[][][][] B = new int[MAXN][MAXN][MAXN][MAXN];
    static int[][] depth = new int[MAXN][MAXN];

    static final int MAX_NETWORK_NODES = 205;

    static class Edge {
        int a, b, cap, flow;

        public Edge(int a, int b, int cap, int flow) {
            this.a = a;
            this.b = b;
            this.cap = cap;
            this.flow = flow;
        }
    }

    static List<Edge> e = new ArrayList<>();
    static List<Integer>[] g = new ArrayList[MAX_NETWORK_NODES];

    static int n, s, t;
    static int[] d = new int[MAX_NETWORK_NODES];
    static int[] ptr = new int[MAX_NETWORK_NODES];
    static int[] q = new int[MAX_NETWORK_NODES];

    static {
        for (int i=0; i<MAX_NETWORK_NODES; i++) {
            g[i] = new ArrayList<>();
        }
    }

    static void add_edge(int a, int b, int cap) {
        Edge e1 = new Edge(a, b, cap, 0);
        Edge e2 = new Edge(b, a, 0, 0);
        g[a].add(e.size()); e.add(e1);
        g[b].add(e.size()); e.add(e2);
    }

    static boolean bfs() {
        int qh=0, qt=0;
        q[qt++] = s;
        Arrays.fill(d, -1);
        d[s] = 0;
        while (qh<qt && d[t]==-1) {
            int v = q[qh++];
            for (int i=0; i<g[v].size(); ++i) {
                int id = g[v].get(i);
                int to = e.get(id).b;
                if (d[to]==-1 && e.get(id).flow<e.get(id).cap) {
                    q[qt++] = to;
                    d[to] = d[v]+1;
                }
            }
        }
        return d[t]!=-1;
    }

    static int dfs(int v, int flow) {
        if (flow==0) return 0;
        if (v==t) return flow;
        for (; ptr[v]<g[v].size(); ++ptr[v]) {
            int id = g[v].get(ptr[v]);
            int to = e.get(id).b;
            if (d[to]!=d[v]+1) continue;
            int pushed = dfs(to, Math.min(flow, e.get(id).cap - e.get(id).flow));
            if (pushed>0) {
                e.get(id).flow += pushed;
                e.get(id^1).flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int dinic() {
        int flow=0;
        while (true) {
            if (!bfs()) break;
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = dfs(s, INF)) > 0) {
                flow += pushed;
            }
        }
        return flow;
    }

    static int get_id(int x, int y) {
        return x*N + y;
    }

    static void build_network() {
        s=0; t=2*N*N+1;
        n=2*N*N+2;
        for (int i=0; i<N; i++) {
            for (int j=0; j<N; j++) {
                if (grid1[i][j] > '0' && grid1[i][j] <= '9') {
                    add_edge(s, 1 + get_id(i,j), grid1[i][j]-'0');
                }
                if (grid2[i][j] > '0' && grid2[i][j] <= '9') {
                    add_edge(N*N+1 + get_id(i,j), t, grid2[i][j]-'0');
                }
            }
        }
        for (int x1=0; x1<N; x1++) {
            for (int y1=0; y1<N; y1++) {
                for (int x2=0; x2<N; x2++) {
                    for (int y2=0; y2<N; y2++) {
                        if (B[x1][y1][x2][y2] > 0) {
                            add_edge(1+get_id(x1,y1), N*N+1+get_id(x2,y2), INF);
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        T = sc.nextInt();
        sc.nextLine();
        for (int i=0; i<N; i++) {
            grid1[i] = sc.nextLine().toCharArray();
        }
        for (int i=0; i<N; i++) {
            grid2[i] = sc.nextLine().toCharArray();
        }
        for (int i=0; i<N; i++) {
            for (int j=0; j<N; j++) {
                A[i][j] = INF;
            }
        }
        Queue<int[]> Q = new LinkedList<>();
        for (int x=0; x<N; x++) {
            for (int y=0; y<N; y++) {
                if (grid1[x][y]=='Z') {
                    for (int i=0; i<4; i++) {
                        int nx = x + dx[i];
                        int ny = y + dy[i];
                        if (nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y') {
                            A[nx][ny] = 1;
                            Q.offer(new int[]{nx, ny});
                        }
                    }
                }
            }
        }
        while (!Q.isEmpty()) {
            int[] p = Q.poll();
            int x = p[0], y=p[1];
            for (int i=0; i<4; i++) {
                int nx = x+dx[i], ny=y+dy[i];
                if (nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y' && grid1[nx][ny]!='Z' && A[nx][ny]==INF) {
                    A[nx][ny] = A[x][y]+1;
                    Q.offer(new int[]{nx, ny});
                }
            }
        }
        for (int x1=0; x1<N; x1++) {
            for (int y1=0; y1<N; y1++) {
                for (int x2=0; x2<N; x2++) {
                    for (int y2=0; y2<N; y2++) {
                        if (grid1[x1][y1]=='Y' || grid1[x1][y1]=='Z' || grid1[x2][y2]=='Y' || grid1[x2][y2]=='Z') {
                            B[x1][y1][x2][y2]=0;
                            continue;
                        }
                        for (int i=0; i<N; i++) {
                            for (int j=0; j<N; j++) {
                                depth[i][j]=INF;
                            }
                        }
                        Queue<int[]> Q2 = new LinkedList<>();
                        depth[x1][y1]=0;
                        Q2.offer(new int[]{x1,y1});
                        int c=0;
                        while (!Q2.isEmpty()) {
                            int[] p2 = Q2.poll();
                            int x = p2[0], y = p2[1];
                            if (x==x2 && y==y2) {
                                c=1; break;
                            }
                            if (depth[x][y]>=T || depth[x][y]>=A[x][y]) continue;
                            for (int i=0; i<4; i++) {
                                int nx=x+dx[i], ny=y+dy[i];
                                if (nx>=0 && nx<N && ny>=0 && ny<N && grid1[nx][ny]!='Y' && grid1[nx][ny]!='Z'
                                    && depth[nx][ny]==INF && depth[x][y]+1<=A[nx][ny]) {
                                    depth[nx][ny]=depth[x][y]+1;
                                    Q2.offer(new int[]{nx, ny});
                                }
                            }
                        }
                        B[x1][y1][x2][y2]= c==1 ? 1 : 0;
                    }
                }
            }
        }
        build_network();
        System.out.println(dinic());
    }
}

