                }
            }
        }

        for (int i = 0; i < N; i++) {
            Arrays.fill(reach_time[i], null);
            for (int j = 0; j < N; j++) {
                for (int ii = 0; ii < N; ii++) {
                    Arrays.fill(reach_time[i][j][ii], -1);
                }
            }
        }

        for (int si = 0; si < n; si++) {
            for (int sj = 0; sj < n; sj++) {
                if (g[si].charAt(sj) == '.') {
                    int startX = si, startY = sj;
                    reach_time[startX][startY][startX][startY] = 0;
                    Queue<int[]> q2 = new LinkedList<>();
                    q2.offer(new int[]{startX, startY});
                    while (!q2.isEmpty()) {
                        int[] uCell = q2.poll();
                        int ii = uCell[0], jj = uCell[1];
                        if (infect_time[ii][jj] == -1 || reach_time[startX][startY][ii][jj] < infect_time[ii][jj]) {
                            for (int d = 0; d < 4; d++) {
                                int ni = ii + di[d], nj = jj + dj[d];
                                if (0 <= ni && ni < n && 0 <= nj && nj < n && g[ni].charAt(nj) == '.') {
                                    if ((infect_time[ni][nj] == -1 || reach_time[startX][startY][ii][jj] + 1 <= infect_time[ni][nj]) &&
                                            reach_time[startX][startY][ni][nj] == -1) {
                                        reach_time[startX][startY][ni][nj] = reach_time[startX][startY][ii][jj] + 1;
                                        q2.offer(new int[]{ni, nj});
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        int src = 2 * n * n;
        int sink = 2 * n * n + 1;
        init_flow();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (n_scientists[i][j] > 0) {
                    add_edge(src, node(n, i, j, false), n_scientists[i][j]);
                }
