}

vector<vector<int>> bfs(int st_x, int st_y, vector<string> s) {
    vector<vector<int>> res(s.size(), vector<int>(s.size(), inf));
    res[st_x][st_y] = 0;
    deque<pii> b;
    b.emplace_back(st_x, st_y);

    while(b.size()) {
