            int x = v.f + xdir[i];
            int y = v.s + ydir[i];
            if (!check(x, y, s) || res[x][y] != inf) continue;

            res[x][y] = res[v.f][v.s] + 1;
            b.emplace_back(x, y);
        }
    }

