            int v = q[qh++];
            for (int id : g[v]) {
                int to = e.get(id).b;
                if (di[to] == -1 && e.get(id).flow < e.get(id).cap) {
                    di[to] = di[v] + 1;
                    q[qt++] = to;
                }
            }
        }
        return di[sink] != -1;
