public class Main {
    public static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();

        int x = 0;
        int y = 1;
        double dif = Double.POSITIVE_INFINITY;

        for (long j = 1; j <= n; j++) {
            long start = (a * j) / b - 1;
            long end = (a * j) / b + 1;
            for (long i = start; i <= end; i++) {
                double currentDiff = Math.abs((double) i / j - (double) a / b);
                if (currentDiff < dif) {
                    dif = currentDiff;
                    x = (int) i;
                    y = (int) j;
                }
            }
        }

        long gcdVal = gcd(x, y);
        System.out.println((x / gcdVal) + "/" + (y / gcdVal));
        sc.close();
    }
}

