import java.util.*;
import java.math.*;

public class Main {
    static long b, c, g, n, q, r, t, u, x, y, z;
    static TreeMap<Double, TreeSet<Ratio>> result = new TreeMap<>();

    static class Ratio implements Comparable<Ratio> {
        long numerator;
        long denominator;

        public Ratio(long numerator, long denominator) {
            this.numerator = numerator;
            this.denominator = denominator;
        }

        @Override
        public int compareTo(Ratio o) {
            int cmp = Long.compare(this.numerator * o.denominator, o.numerator * this.denominator);
            if (cmp == 0) {
                return 0;
            }
            return cmp;
        }
    }

    public static long gcd(long a, long b) {
        while (b != 0) {
            long tmp = b;
            b = a % b;
            a = tmp;
        }
        return a;
    }

    public static void save_ratio(long a) {
        g = gcd(a, b);
        long numerator = Math.abs(u - a * z);
        double key = (double) numerator / t;
        Ratio ratio = new Ratio(b / g, a / g);
        result.putIfAbsent(key, new TreeSet<>());
        result.get(key).add(ratio);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        x = sc.nextLong();
        y = sc.nextLong();
        n = sc.nextLong();

        g = gcd(x, y);
        x /= g;
        y /= g;
        q = x / y;
        r = (int) (x % y);

        for (b = 1; b <= n; ++b) {
            g = gcd(y, b);
            c = b / g;
            z = y / g;
            t = b * z;
            u = q * t + r * c;
            save_ratio(u / z);
            if (u % z != 0) {
                save_ratio((u + z - 1) / z);
            }
        }

        Map.Entry<Double, TreeSet<Ratio>> firstEntry = result.firstEntry();
        Ratio p = firstEntry.getValue().iterator().next();

        System.out.println(p.denominator + "/" + p.numerator);
        sc.close();
    }
}

