import java.util.Scanner;

public class Main {

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    static class Dro {
        long ch; // numerator
        long zn; // denominator

        public Dro() {
        }

        public Dro(long a, long b) {
            this.ch = a;
            this.zn = b;
        }

        public void subtract(Dro a) {
            this.ch = this.ch * a.zn - a.ch * this.zn;
            this.zn = this.zn * a.zn;
        }

        public boolean lessThan(Dro a) {
            return this.ch * a.zn < a.ch * this.zn;
        }

        public void simplify() {
            long j = gcd(this.ch, this.zn);
            this.ch /= j;
            this.zn /= j;
        }

        public void show() {
            System.out.println(this.ch + "/" + this.zn);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        Dro os = new Dro(50, 1);
        Dro na = new Dro(x, y);
        Dro ot = new Dro();

        for (long i = 1; i <= n; ++i) {
            Dro p = new Dro();
            long r = (na.ch * i) / na.zn;
            long z = (na.ch * i) % na.zn;
            if (z > (na.zn / 2)) {
                r++;
                z = na.zn - z;
            }
            p.ch = z;
            p.zn = i * na.zn;

            if (p.lessThan(os)) {
                os = new Dro(p.ch, p.zn);
                ot.ch = r;
                ot.zn = i;
            }
        }
        ot.show();
        sc.close();
    }
}

