        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        if (y <= n) {
            while (gcd(x, y) > 1) {
                long h = gcd(x, y);
                x /= h;
                y /= h;
            }
            System.out.println(x + "/" + y);
            return;
        }

        double res = 1e9;
        long p1 = 0, p2 = 0;

        for (long i = 1; i <= n; i++) {
            long h = lca(i, y);
            long w = x * (h / y);
            double temp1 = (double)(w - ((w / (h / i)) * (h / i))) / (double)h;
            if (res > temp1) {
                res = temp1;
                p1 = (w / (h / i));
                p2 = i;
            }
            long numerator = w + (h / i) - 1;
            long denominator = h / i;
            long multiple = ((numerator) / denominator) * denominator;
            double temp2 = (double)gcd(p1, p2) == 1 ? Math.abs(w - multiple) / (double)h
                                                    : Math.abs(w - multiple) / (double)h;
            if (res > temp2) {
                res = temp2;
                p1 = (numerator) / denominator;
                p2 = i;
            }
        }
        long h = gcd(p1, p2);
        p1 /= h;
        p2 /= h;
        System.out.println(p1 + "/" + p2);
        sc.close();
    }
}

