            ans = add(ans, (int)(((c - now) % MOD1 + MOD1) % MOD1), MOD2);
        }
        int start = (pos == 1) ? 1 : 0;
        for (int i = start; i <= 9; i++) {
            solve(pos + 1, now * 10 + i);
        }
    }

    static int lowerBound(List<Integer> list, int val) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= val)
