    }

    static long nxt(long val, long n) {
        if (val * 10 <= n) {
            return val * 10;
        } else {
            val++;
            if (val <= n) {
                while (val % 10 == 0) {
                    val /= 10;
                }
            } else {
                val = (val - 1) / 10 + 1;
                while (val % 10 == 0) {
                    val /= 10;
                }
            }
        }
        return val;
