                if (lastdig == n_str[firstdiff] - '0')
                    continue;
                if (len == SZ(n_str) and lastdig > n_str[firstdiff] - '0')
                    continue;
                
                auto curp = 10 * cur + lastdig;
                auto curstp = curst + char('0' + lastdig);
                
                // n = 23456
                // cur = 21??

                // who's less than us?
                // 1*
                // 20*
                // 21[smaller]

                int64_t base = 0;
                string tmp = "";
