                base += 1; // 1-based, not 0-based
                base -= curp * pw10[len - SZ(curstp)];
                for (int t = 0; t < SZ(variables); ++t)
                    variables[SZ(variables) - 1 - t] -= pw10[t] % mod;

                base %= mod;
