import java.util.*;
import java.io.*;

public class Main {

    static final long INF = (long) 1e15;
    static final int MOD = (int) 1e9 + 7;
    static final int MX = 1000010;
    static List<Long> ones = new ArrayList<>();
    static int ans = MX;

    static void bst(long x, int vv) {
        if (vv > ans)
            return;
        if (x == 0) {
            ans = vv;
            return;
        }
        int size = ones.size();
        int lbIndex = Collections.binarySearch(ones, x);
        if (lbIndex < 0) {
            lbIndex = -lbIndex - 1;
        }
        int ubIndex = Collections.binarySearch(ones, x);
        if (ubIndex < 0) {
            ubIndex = -ubIndex - 1;
        } else {
            ubIndex += 1;
        }
        if (lbIndex == ubIndex) {
            lbIndex -= 1;
        }
        long lbVal = ones.get(lbIndex);
        long ubVal = ones.get(ubIndex);
        long rem = x - lbVal;
        int cost = lbIndex; // zero-based index
        long rem2 = ubVal - x;
        bst(x % lbVal, vv + cost * (int)(x / lbVal));
        bst(rem2, vv + cost + 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        // Read input
        long n = Long.parseLong(br.readLine());

        // Initialize 'ones' list
        ones.clear();
        ones.add(0L);
        for (int i = 1; i <= 16; ++i) {
            long last = ones.get(ones.size() - 1);
            ones.add(last * 10 + 1);
        }

        // Run the recursive search
        bst(n, 0);

        // Output result
        System.out.println(ans);
    }
}

