	bool operator<(const step &c) const {
		return c.cost < cost;
	}
};

set<ll> visited;

bool wasVisited(ll c) {
	return visited.find(c) != visited.end();
}

step uupper(ll n){
	ll res = 0;
	int i = 0;
	while(res<n){
		res*=10;
		res++;
		i++;
	}
	return {res, i};
}

step upper(ll n){
	ll res = 0;
	int i = 0;
	while(res*10+1<=n){
		res*=10;
		res++;
		i++;
	}
	ll resmul = res;
	int imul = i;
	while(res < n){
		res+=resmul;
		i+=imul;
	}
	return {res, i};
}

step lower(ll n){
	ll res = 0;
	int i = 0;
	while(res*10+1<=n){
		res*=10;
		res++;
		i++;
	}
	ll resmul = res;
	int imul = i;
	while(res+resmul <= n){
		res+=resmul;
		i+=imul;
	}
	return {res, i};
}

