import java.util.PriorityQueue;
import java.util.HashSet;
import java.util.Set;

public class Main {
    static class Step implements Comparable<Step> {
        long val;
        int cost;

        Step(long val, int cost) {
            this.val = val;
            this.cost = cost;
        }

        @Override
        public int compareTo(Step c) {
            // For min-heap based on cost
            return Integer.compare(this.cost, c.cost);
        }
    }

    static Set<Long> visited = new HashSet<>();

    static boolean wasVisited(long c) {
        return visited.contains(c);
    }

    static Step uupper(long n) {
        long res = 0;
        int i = 0;
        while (res < n) {
            res = res * 10 + 1;
            i++;
        }
        return new Step(res, i);
    }

    static Step upper(long n) {
        long res = 0;
        int i = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            i++;
        }
        long resmul = res;
        int imul = i;
        while (res < n) {
            res += resmul;
            i += imul;
        }
        return new Step(res, i);
    }

    static Step lower(long n) {
        long res = 0;
        int i = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            i++;
        }
        long resmul = res;
        int imul = i;
        while (res + resmul <= n) {
            res += resmul;
            i += imul;
        }
        return new Step(res, i);
    }

    public static void main(String[] args) {
        java.util.Scanner sc = new java.util.Scanner(System.in);
        long n = sc.nextLong();

        PriorityQueue<Step> pq = new PriorityQueue<>();
        pq.add(new Step(n, 0));

        while (true) {
            Step current = pq.peek();
            if (current.val == 0) {
                System.out.println(current.cost);
                break;
            }
            pq.poll();

            if (wasVisited(current.val))
                continue;
            visited.add(current.val);

            for (Step next : new Step[]{ lower(current.val), upper(current.val), uupper(current.val) }) {
                next.cost += current.cost;
                next.val = Math.abs(current.val - next.val);
                pq.add(next);
            }
        }

        sc.close();
    }
}

