            digits++;
            n /= 10;
        }
        return digits;
    }

    static long ones(long n) {
        long res = 0;
        for (int i = 0; i < n; ++i)
            res = 10 * res + 1;
        return res;
    }

    static long aux2(long n) {
        if (n == 0) return 0;
        n = n < 0 ? -n : n;
        long d = nb_digits(n);
        return d + aux2(n - ones(d));
    }

    static long aux(long n, long sign, long acc, long max, int[] already_in) {
        if (acc >= max) return max;
        if (n == 0) return acc;

        if (n < 0) {
            n = -n;
            sign = -sign;
        }
        long d = nb_digits(n);
        long ones_d = ones(d);
        long res1 = max, res2 = max;

