import java.util.Scanner;

public class Main {
    static long n, ans;
    static long[] A = new long[20];
    static long[] B = new long[20];

    static void dfs(int pos, long now, long res) {
        if (res >= ans) return;
        if (pos == 0) {
            if (now == 0) ans = res;
            return;
        }
        long t = now / A[pos];
        long d = Math.abs(t) - 1;
        if (t < 0) d = -d;
        long s = Math.abs(t) + 1;
        if (t < 0) s = -s;
        dfs(pos - 1, now - t * B[pos], res + Math.abs(t) * pos);
        dfs(pos - 1, now - d * B[pos], res + Math.abs(d) * pos);
        dfs(pos - 1, now - s * B[pos], res + Math.abs(s) * pos);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 1; i <= 16; i++) B[i] = B[i - 1] * 10 + 1; // Initialize B array
        A[1] = 1;
        for (int i = 2; i <= 16; i++) A[i] = A[i - 1] * 10; // Initialize A array
        n = sc.nextLong();
        long m = n;
        int c = 0;
        while (m != 0) {
            c++;
            m /= 10;
        }
        ans = Long.MAX_VALUE; // Equivalent to 1e18
        dfs(c, n, 0);
        dfs(c, B[c + 1] - n, c + 1);
        System.out.println(ans);
