import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class GodAndMe {

    static Map<Long, Long> mp = new HashMap<>();

    static int numof(long x) {
        int ans = 0;
        while (x != 0) {
            ans++;
            x /= 10;
        }
        return ans;
    }

    static long nxt(long x) {
        long[] ans = new long[17];
        int p = 0;
        long tempX = x;
        while (tempX != 0) {
            ans[p++] = (tempX % 10) - (x < 0 ? -1 : 1);
            tempX /= 10;
        }
        long res = 0;
        for (int i = p - 1; i >= 0; i--) {
            res = res * 10 + ans[i];
        }
        return res;
    }

    static long prv(long x) {
        long c = 0;
        long cx = x;
        long tempX = x;
        while (tempX != 0) {
            c = c * 10 + (tempX % 10);
            tempX /= 10;
        }
        c = c * 10 + 1;
        return cx - c;
    }

    static long lst(long x) {
        while (x >= 10) {
            x /= 10;
        }
        return x;
    }

    static long del(long x) {
        long[] ans = new long[17];
        int p = 0;
        long tempX = x;
        while (tempX >= 10) {
            ans[p++] = tempX % 10;
            tempX /= 10;
        }
        long res = 0;
        for (int i = p - 1; i >= 0; i--) {
            res = res * 10 + ans[i];
        }
        return res;
    }

    static long f(long x) {
        if (x <= 11) {
            return Math.min(13 - x, x);
        }
        if (mp.containsKey(x))
            return mp.get(x);
        int n = 0;
        long t = 1;
        while (t < x) {
            t *= 10;
            t++;
            n++;
        }
        if (x * 2 >= t) {
            long res1 = f(t - x) + n + 1;
            long res2 = (x / (t / 10)) * n + f(x % (t / 10));
            long result = Math.min(res1, res2);
            mp.put(x, result);
            return result;
        } else {
            long result = (x / (t / 10)) * n + f(x % (t / 10));
            mp.put(x, result);
            return result;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        System.out.println(f(a));
        sc.close();
    }
}

