            long k1 = k / 10;
            long threshold = 6 * (long)Math.pow(10, l - 1) + k1 / 10;
            if (n1 > threshold) {
                n1 = k - n1;
                c += l + 1;
            } else {
                n1 = n1 - k1;
                c += l;
            }
        }
        if (n1 == 1) {
