import java.util.Scanner;

public class Main {
    static long[] xrr = new long[18];
    static int res = Integer.MAX_VALUE;

    static void dfs(int ans, long rem, int p) {
        if (ans > res)
            return;
        if (rem == 0) {
            res = Math.min(ans, res);
            return;
        }
        int need = (int) (rem / xrr[p]);
        if (need > 0) {
            dfs(ans + p * need, rem - (need * xrr[p]), p - 1);
        } else {
            // If need is zero, just proceed without recursion to avoid infinite loop
            dfs(ans, rem, p - 1);
        }
        int altNeed = need + 1;
        long newRem = altNeed * xrr[p] - rem;
        dfs(p * altNeed + ans, newRem, p - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        xrr[1] = 1;
        for (int i = 2; i < 18; i++) {
            xrr[i] = (10 * xrr[i - 1]) + 1;
        }
        long xp = x;
        while (xp > 0) {
            boolean found = false;
            for (int i = 1; i < 18; i++) {
                if (xrr[i] > xp) {
                    res += (i - 1);
                    xp -= xrr[i - 1];
                    found = true;
                    break;
                }
            }
            if (!found) {
                // If no break occurs in for loop, exit
                break;
            }
        }
        dfs(0, x, 16);
        System.out.println(res);
        sc.close();
    }
}

