import java.util.Scanner;

public class Main {
    // Helper method to count the number of digits in n
    public static int num(long n) {
        int count = 0;
        while (n != 0) {
            n /= 10;
            count++;
        }
        return count;
    }

    // Find the largest number consisting of all '1's that does not exceed n
    public static long find(long n) {
        int ex = num(n);
        long cur = 0, ad = 1;
        for (int i = 0; i <= ex - 1; i++) {
            cur += ad;
            ad *= 10;
        }
        if (cur <= n) {
            return cur;
        }
        return (cur - 1) / 10;
    }

    public static long process(long n) {
        if (n <= 6) {
            return n;
        }
        if (n <= 11) {
            return 13 - n;
        }
        long less = find(n);
        long more = less * 10 + 1;
        if (n % less == 0) {
            if (n <= more / 2 + less) {
                return num(less) * n / less;
            }
            return num(more) + process(more - n);
        } else {
            long _m = (n / less) * less;
            long res = process(_m) + process(n - _m);
            if (n > more / 2) {
                long resAlt = process(_m) + process(n - _m);
                long resOther = num(more) + process(more - n);
                res = Math.min(res, resOther);
            }
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(process(n));
        scanner.close();
    }
}

