import java.util.Scanner;

public class Main {
    static long[] a = new long[16];

    static long solve(long n, int step) {
        long ans = (long)Math.ceil((step + 1.0) * (double)(n / a[step]));
        n %= a[step];
        if (n == 0) {
            return ans;
        } else {
            long option1 = solve(n, step - 1);
            long option2 = (step + 1) + solve(a[step] - n, step - 1);
            return ans + Math.min(option1, option2);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        a[0] = 1;
        for (int i = 1; i < 16; ++i) {
            a[i] = a[i - 1] * 10 + 1;
        }
        long n = scanner.nextLong();
        System.out.println(solve(n, 15));
        scanner.close();
    }
}

