        if (solve.charAt(0) == '.') {
            solve = "dot" + solve.substring(1);
        } else if (solve.charAt(0) == '@') {
            solve = "at" + solve.substring(1);
        }

        if (solve.charAt(solve.length() - 1) == '.') {
            solve = solve.substring(0, solve.length() - 1) + "dot";
        } else if (solve.charAt(solve.length() - 1) == '@') {
            solve = solve.substring(0, solve.length() - 1) + "at";
        }
