        s = sc.nextLine();
        N = s.length();
        solve = "";

        int I = 0;
        while (I < N) {
            if (I + 3 <= N && s.substring(I, I + 3).equals("dot")) {
                solve += ".";
                I += 3;
            } else if (I + 2 <= N && s.substring(I, I + 2).equals("at")) {
                solve += "@";
                I += 2;
            } else {
                solve += s.charAt(I);
                I++;
            }
