import java.util.*;
public class Main {
    static final int mod = 1000000007;
    static Scanner sc = new Scanner(System.in);

    // MATH FUNCTIONS
    public static boolean isPrime(long n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (long i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }

    public static long pow(long a, long b, long m) {
        long res = 1;
        a %= m;
        while (b > 0) {
            if ((b & 1) == 1) res = (res * a) % m;
            a = (a * a) % m;
            b >>= 1;
        }
        return res;
    }

    public static long ncr(int n, int k) {
        if (k > n) return 0;
        long res = 1;
        if (k > n - k) k = n - k;
        for (int i = 0; i < k; i++) {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

    // SOLVE FUNCTION
    public static void solve() {
        String s = sc.next();
        boolean at = false;
        int n = s.length();
        System.out.print(s.charAt(0));
        boolean[] done = new boolean[n + 1];
        Arrays.fill(done, false);
        done[0] = true;
        int i = 1;
        while (i <= n - 3) {
            done[i] = true;
            if (s.charAt(i) == 'a' && s.charAt(i + 1) == 't' && !at) {
                System.out.print('@');
                at = true;
                done[i + 1] = true;
                i += 2;
            } else if (s.charAt(i) == 'd' && s.charAt(i + 1) == 'o' && s.charAt(i + 2) == 't' && i != n - 3) {
                System.out.print('.');
                done[i + 1] = true;
                done[i + 2] = true;
                i += 3;
            } else {
                System.out.print(s.charAt(i));
                i++;
            }
        }
        for (int j = 0; j < n; j++) {
            if (!done[j]) {
                System.out.print(s.charAt(j));
            }
        }
        System.out.println();
    }

    public static void main(String[] args) {
        // No need for file redirection in Java
        // Running solve directly
        solve();
    }
}

