import java.util.*;
import java.io.*;
public class Main {
    static final int MXN = (int) 1e9 + 7;
    static final long INF = (long) 1e18 + 7;

    static long nod(long a, long b) {
        if (b > a) {
            long temp = a; a = b; b = temp;
        }
        while (b > 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    static long nok(long a, long b) {
        return a * b / nod(a, b);
    }

    static void sp(int a, double b) {
        System.out.printf("%." + a + "f", b);
    }

    static long binpow(long a, long n) {
        if (n == 0) return 1;
        if (n % 2 == 1) return binpow(a, n - 1) * a;
        else {
            long b = binpow(a, n / 2);
            return b * b;
        }
    }

    static void solve(Scanner sc, PrintWriter pw) {
        String s = sc.nextLine();
        boolean ok = false;
        int length = s.length();

        for (int i = 0; i < length; ++i) {
            if (i + 1 < length && s.charAt(i) == 'a' && s.charAt(i + 1) == 't' && !ok && i != 0 && (i + 1) != length - 1) {
