                i++;
            } else {
                if (i + 2 < length && s.charAt(i) == 'd' && s.charAt(i + 1) == 'o' && s.charAt(i + 2) == 't' && i != 0 && (i + 2) != length - 1) {
                    pw.print('.');
                    i += 2;
                } else {
                    pw.print(s.charAt(i));
                }
            }
        }
        pw.println();
    }

    public static void main(String[] args) {
