public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str = scanner.nextLine();
        StringBuilder ans = new StringBuilder();
        boolean taken = false;

        for (int i = 0; i < str.length(); i++) {
            char currentChar = str.charAt(i);

            if (currentChar != 'a' && currentChar != 'd') {
                ans.append(currentChar);
                continue;
            }

            if (currentChar == 'a') {
                if (i == str.length() - 1 || str.charAt(i + 1) != 't' || ans.length() == 0 || taken) {
                    ans.append(currentChar);
                } else {
                    taken = true;
                    ans.append('@');
                    i++; // Skip the next 't'
                }
                continue;
            }

            // currentChar is 'd'
            if (i >= str.length() - 3 || !(str.charAt(i + 1) == 'o' && str.charAt(i + 2) == 't') || ans.length() == 0) {
                ans.append(currentChar);
                continue;
            }

            // Replace 'dot' with '.'
            ans.append('.');
            i += 2; // Skip 'o' and 't'
        }

        System.out.print(ans.toString());
        scanner.close();
    }
}

