        Scanner scanner = new Scanner(System.in);
        String a = scanner.nextLine();
        StringBuilder b = new StringBuilder();

        int i = 0;
        while (i < a.length()) {
            if (i + 1 < a.length() && a.charAt(i) == 'a' && a.charAt(i + 1) == 't') {
                b.append('@');
                i += 2;
            } else if (i + 2 < a.length() && a.charAt(i) == 'd' && a.charAt(i + 1) == 'o' && a.charAt(i + 2) == 't') {
                b.append('.');
                i += 3;
            } else {
                b.append(a.charAt(i));
                i += 1;
            }
        }

        String b_str = b.toString();
        boolean at = true;

        if (b_str.charAt(0) == '@') {
            System.out.print("at");
        } else if (b_str.charAt(0) == '.') {
            System.out.print("dot");
        } else {
            System.out.print(b_str.charAt(0));
        }

        for (int j = 1; j < b_str.length(); j++) {
            char ch = b_str.charAt(j);
            if (ch == '@') {
                if (at && j != b_str.length() - 1) {
                    System.out.print("@");
                    at = false;
                } else {
                    System.out.print("at");
                }
            } else if (ch == '.') {
                if (j != b_str.length() - 1) {
                    System.out.print(".");
                } else {
                    System.out.print("dot");
                }
            } else {
                System.out.print(ch);
            }
        }
        System.out.println();
        scanner.close();
    }
}

