import java.util.*;
import java.math.BigInteger;

public class Main {
    static final int MAX_N = 20;
    static final int MAX_MASK = 1 << 20;
    static final long MOD = 1000000007L;
    static long[] cnt = new long[MAX_MASK];
    static long[] cnt2 = new long[MAX_MASK];
    static long[][] a = new long[MAX_N][MAX_N];
    static int[] rev = new int[MAX_MASK];
    static int[] rev2 = new int[MAX_MASK];
    static int n, m;
    static int[] cor = new int[25];
    static Random rand = new Random();

    public static long modpow(long base, long exp) {
        long res = 1;
        long x = base % MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * x % MOD;
            x = x * x % MOD;
            exp >>= 1;
        }
        return res;
    }

    static void dfs(int cur, List<Integer> con, double prob) {
        if (cur == m) {
            int nxt = 0, id = 0;
            for (int j = 0; j < (1 << n); j++) {
                if (Integer.bitCount(j) != m) continue;
                List<Integer> vi = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (((j >> i) & 1) == 1) vi.add(i);
                }
                boolean ok = false;
                do {
                    for (int x = 0; x < m; x++) {
                        if (((con.get(x) >> vi.get(x)) & 1) == 0) {
                            ok = false;
                            break;
                        } else {
                            ok = true;
                        }
                    }
                    if (ok) break;
                } while (nextPermutation(vi));
                if (ok) id |= (1 << nxt);
                nxt++;
            }
            cnt[id] += prob;
            return;
        }
        for (int j = 0; j < (1 << n); j++) {
            con.add(j);
            double nw = prob;
            for (int k = 0; k < n; k++) {
                if (((j >> k) & 1) == 1) {
                    nw = nw * a[cur][k] % MOD;
                } else {
                    nw = nw * (MOD + 1 - a[cur][k]) % MOD;
                }
            }
            dfs(cur + 1, con, nw);
            con.remove(con.size() - 1);
        }
    }

    static void dfs2(int cur, List<Integer> con, double prob) {
        if (cur == n) {
            int nxt = 0, id = 0;
            for (int j = 0; j < (1 << n); j++) {
                if (Integer.bitCount(j) != n - m) continue;
                List<Integer> vi = new ArrayList<>();
                for (int i = 0; i < n; i++) {
                    if (((j >> i) & 1) == 1) vi.add(i);
                }
                boolean ok = false;
                do {
                    for (int x = 0; x < n - m; x++) {
                        if (((con.get(x) >> vi.get(x)) & 1) == 0) {
                            ok = false;
                            break;
                        } else {
                            ok = true;
                        }
                    }
                    if (ok) break;
                } while (nextPermutation(vi));
                if (ok) id |= (1 << nxt);
                nxt++;
            }
            cnt2[id] += prob;
            return;
        }
        for (int j = 0; j < (1 << n); j++) {
            con.add(j);
            double nw = prob;
            for (int k = 0; k < n; k++) {
                if (((j >> k) & 1) == 1) {
                    nw = nw * a[cur][k] % MOD;
                } else {
                    nw = nw * (MOD + 1 - a[cur][k]) % MOD;
                }
            }
            dfs2(cur + 1, con, nw);
            con.remove(con.size() - 1);
        }
    }

    static boolean nextPermutation(List<Integer> arr) {
        int i = arr.size() - 2;
        while (i >= 0 && arr.get(i) >= arr.get(i + 1)) i--;
        if (i < 0) return false;
        int j = arr.size() - 1;
        while (arr.get(j) <= arr.get(i)) j--;
        Collections.swap(arr, i, j);
        int l = i + 1, r = arr.size() - 1;
        while (l < r) {
            Collections.swap(arr, l, r);
            l++;
            r--;
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = sc.nextLong();
                long inv = modpow(100, MOD - 2);
                long norm = val * inv % MOD;
                a[i][j] = norm;
            }
        }

        if (n == 1) {
            System.out.println(a[0][0]);
            return;
        }

        m = n / 2;
        Arrays.fill(cnt, 0);
        dfs(0, new ArrayList<>(), 1.0);

        for (int i = 0; i < MAX_MASK; i++) {
            cnt[i] %= MOD;
        }

        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < MAX_MASK; j++) {
                if (((j >> i) & 1) == 1) {
                    cnt[j] = (cnt[j] + cnt[j ^ (1 << i)]) % MOD;
                }
            }
        }

        long all = cnt[(1 << 20) -1];

        Arrays.fill(cnt2, 0);
        dfs2(m, new ArrayList<>(), 1.0);
        for (int i = 0; i < MAX_MASK; i++) {
            cnt2[i] %= MOD;
        }

        Arrays.fill(rev, -1);
        int nd = 0;
        for (int i = 0; i < (1 << n); i++) {
            if (Integer.bitCount(i) != m) continue;
            rev[i] = nd++;
        }

        Arrays.fill(rev2, -1);
        nd = 0;
        for (int i = 0; i < (1 << n); i++) {
            if (Integer.bitCount(i) != n - m) continue;
            cor[nd] = rev[( (1 << n) - 1) ^ i];
            rev2[i] = nd++;
        }

        long ans = 0;
        for (int i = 0; i < (1 << nd); i++) {
            long cur = cnt2[i];
            int mask = 0;
            for (int j = 0; j < nd; j++) {
                if (((i >> j) & 1) == 1) continue;
                else mask += (1 << cor[j]);
            }
            long val = (cur * ((all - cnt[mask]) % MOD)) % MOD;
            ans = (ans + val) % MOD;
        }
        System.out.println((ans + MOD) % MOD);
        sc.close();
    }
}

