import java.util.*;
import java.io.*;

public class E2MarekAndMatchingHardVersion {
    static final int S = 128;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        solve(br, out);
        out.flush();
    }

    public static void solve(BufferedReader br, PrintWriter out) throws IOException {
        int N = Integer.parseInt(br.readLine());
        int[][] P = new int[N][N];
        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().split(" ");
            for (int j = 0; j < N; j++) {
                P[i][j] = Integer.parseInt(parts[j]);
            }
        }

        Map<BitSet, FieldMod> G = new HashMap<>();
        BitSet oneBitSet = new BitSet(S);
        oneBitSet.set(0); // equivalent to bitset with first bit set
        G.put(oneBitSet, new FieldMod(1));

        for (int i = 0; i < N; ++i) {
            Map<List<Integer>, FieldMod> H = new HashMap<>();
            for (Map.Entry<BitSet, FieldMod> entry : G.entrySet()) {
                List<Integer> S_list = new ArrayList<>();
                BitSet gBits = entry.getKey();
                for (int m = 0; m < (1 << N); ++m) {
                    if (gBits.get(m))
                        S_list.add(m);
                }
                H.put(S_list, entry.getValue());
            }
            G.clear();

            for (int j = 0; j < (1 << N); ++j) {
                FieldMod pst = new FieldMod(1);
                for (int k = 0; k < N; ++k) {
                    if (((j >> k) & 1) == 1)
                        pst.multiply(new FieldMod(P[i][k]));
                    else
                        pst.multiply(new FieldMod(100 - P[i][k]));
                }
                for (Map.Entry<List<Integer>, FieldMod> hEntry : H.entrySet()) {
                    List<Integer> hS = hEntry.getKey();
                    FieldMod hVal = hEntry.getValue();

                    BitSet ansBits = new BitSet(S);
                    for (int l = 0; l < N; ++l) {
                        if (((j >> l) & 1) == 0) continue;
                        for (int m : hS) {
                            if (((m >> l) & 1) == 0) {
                                int mOr = m | (1 << l);
                                ansBits.set(mOr);
                            }
                        }
                    }
                    if (ansBits.cardinality() > 0) {
                        G.put(ansBits, G.getOrDefault(ansBits, new FieldMod(0)).add(hVal.multiply(pst)));
                    }
                }
            }
        }

        FieldMod ans = new FieldMod(0);
        for (Map.Entry<BitSet, FieldMod> entry : G.entrySet()) {
            ans = ans.add(entry.getValue());
        }

        int totalDivisions = N * N;
        for (int i = 0; i < totalDivisions; ++i) {
            ans.divide(new FieldMod(100));
        }
        out.println(ans);
    }

    static class FieldMod {
        static final int MOD = 1000000007;
        long value;

        public FieldMod(long v) {
            value = v % MOD;
            if (value < 0) value += MOD;
        }

        public FieldMod add(FieldMod other) {
            return new FieldMod(this.value + other.value);
        }

        public FieldMod multiply(FieldMod other) {
            return new FieldMod(this.value * other.value);
        }

        public void divide(FieldMod other) {
            this.value = (this.value * other.inverse().value) % MOD;
        }

        public FieldMod inverse() {
            return new FieldMod(modInverse(this.value, MOD));
        }

        private static long modInverse(long a, long m) {
            long m0 = m, t, q;
            long x0 = 0, x1 = 1;
            if (m == 1) return 0;
            while (a > 1) {
                q = a / m;
                t = m;
                m = a % m;
                a = t;
                t = x0;
                x0 = x1 - q * x0;
                x1 = t;
            }
            if (x1 < 0) x1 += m0;
            return x1;
        }

        @Override
        public String toString() {
            return Long.toString(value);
        }
    }
