import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_N = 10;
    static final int MOD = 1000000007;
    static int[][] a = new int[MAX_N][MAX_N];

    // Utility functions for modular arithmetic
    static int add(int a, int b) {
        a += b;
        if(a >= MOD) a -= MOD;
        return a;
    }

    static int sub(int a, int b) {
        a -= b;
        if(a < 0) a += MOD;
        return a;
    }

    static int mul(int a, int b) {
        return (int)((a * 1L * b) % MOD);
    }

    static int power(int a, int n) {
        int res = 1;
        int base = a;
        while(n > 0) {
            if((n & 1) == 1) res = mul(res, base);
            base = mul(base, base);
            n >>= 1;
        }
        return res;
    }

    static int rev(int a) {
        return power(a, MOD - 2);
    }

    static int divv(int a, int b) {
        return mul(a, rev(b));
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        for(int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            for(int j = 0; j < n; j++) {
                a[i][j] = Integer.parseInt(st.nextToken());
                a[i][j] = divv(a[i][j], 100);
            }
        }

        ArrayList<Pair<List<Integer>, Integer>> sets = new ArrayList<>();
        ArrayList<Pair<List<Integer>, Integer>> newSets;

        List<Integer> initialSet = new ArrayList<>();
        initialSet.add(0);
        sets.add(new Pair<>(initialSet, 1));

        for(int g = 0; g < n; g++) {
            newSets = new ArrayList<>();
            for(int mask = 0; mask < (1 << n); mask++) {
                int value = 1;
                for(int j=0; j<n; j++) {
                    if(((mask >> j) & 1) != 0)
                        value = mul(value, a[j][g]);
                    else
                        value = mul(value, sub(1, a[j][g]));
                }

                for(Pair<List<Integer>, Integer> np : sets) {
                    List<Integer> np_fs = np.first;
                    int np_sc = np.second;

                    List<Integer> newSet = new ArrayList<>();
                    for(int mask2 : np_fs) {
                        int possible = (~mask2) & mask;
                        while(possible != 0) {
                            int pos = possible & (-possible);
                            newSet.add(mask2 | pos);
                            possible ^= pos;
                        }
                    }
                    if(newSet.isEmpty()) continue;
                    Collections.sort(newSet);
                    // Remove duplicates
                    newSet = new ArrayList<>(new LinkedHashSet<>(newSet));
                    newSets.add(new Pair<>(newSet, mul(np_sc, value)));
                }
            }
            // Sort newSets
            Collections.sort(newSets, (p1, p2) -> {
                List<Integer> s1 = p1.first;
                List<Integer> s2 = p2.first;
                int len = Math.min(s1.size(), s2.size());
                for(int i=0; i<len; i++) {
                    int cmp = Integer.compare(s1.get(i), s2.get(i));
                    if(cmp != 0) return cmp;
                }
                return Integer.compare(s1.size(), s2.size());
            });
            // Merge duplicates
            ArrayList<Pair<List<Integer>, Integer>> merged = new ArrayList<>();
            int i = 0;
            while(i < newSets.size()) {
                int j = i;
                int sumVal = 0;
                List<Integer> keys = new ArrayList<>();
                List<Integer> currentKey = new ArrayList<>(newSets.get(i).first);
                while(j < newSets.size() && newSets.get(j).first.equals(currentKey)) {
                    sumVal = add(sumVal, newSets.get(j).second);
                    j++;
                }
                merged.add(new Pair<>(currentKey, sumVal));
                i = j;
            }
            sets = merged;
        }

        int res = 0;
        for(Pair<List<Integer>, Integer> np : sets) {
            res = add(res, np.second);
        }
        System.out.println(res);
    }

    // Simple Pair class
    static class Pair<F, S> {
        public F first;
        public S second;
        public Pair(F f, S s) {
            first = f;
            second = s;
        }
    }
}

