import java.util.*;
import java.math.*;

public class Main {
    static final int MOD = 1000000007;
    static final int MAX_N = 7;
    static Map<BitSet, Integer> idMap = new HashMap<>();
    static int N, cnt;
    static int[][] P = new int[MAX_N][MAX_N];
    static long[][][] dp = new long[2][70003];
    static int[][] trans = new int[70003][128];
    static long[] prob = new long[128];
    static long iv100;

    public static long poww(long a, int b) {
        long times = 1;
        while (b > 0) {
            if ((b & 1) == 1)
                times = times * a % MOD;
            a = a * a % MOD;
            b >>= 1;
        }
        return times;
    }

    public static int dfs(BitSet x) {
        if (idMap.containsKey(x))
            return idMap.get(x);
        int nd = ++cnt;
        idMap.put(x, nd);
        BitSet[] tmp = new BitSet[N];
        for (int i = 0; i < N; i++)
            tmp[i] = new BitSet(1 << N);

        // Build tmp array
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < (1 << N); j++) {
                if ((j & (1 << i)) != 0)
                    tmp[i].set(j | (1 << i));
                else
                    tmp[i].set(j);
            }
        }

        for (int i = 0; i < (1 << N); i++) {
            BitSet tp = (BitSet) x.clone();
            for (int j = 0; j < N; j++) {
                if (((i >> j) & 1) == 1) {
                    tp.or(tmp[j]);
                }
            }
            trans[nd][i] = dfs(tp);
        }
        return nd;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        BitSet tmpBitSet = new BitSet();
        tmpBitSet.set(0);
        dfs(tmpBitSet);
        iv100 = poww(100, MOD - 2);
        // Read P
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                P[i][j] = sc.nextInt();
            }
        }
        for (int i = 0; i < 2; i++) {
            Arrays.fill(dp[i], 0);
        }
        dp[0][1] = 1;
        int x = 0;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < (1 << N); j++) {
                prob[j] = 1;
                for (int k = 0; k < N; k++) {
                    long numerator = j >> k & 1 ? P[i][k] : (100 - P[i][k]);
                    prob[j] = prob[j] * iv100 % MOD * numerator % MOD;
                }
            }
            for (int j = 0; j < 70003; j++)
                dp[x ^ 1][j] = 0;
            x ^= 1;
            for (int j = 1; j <= cnt; j++) {
                if (dp[x ^ 1][j] != 0) {
                    for (int k = 0; k < (1 << N); k++) {
                        int t = trans[j][k];
                        dp[x][t] = (dp[x][t] + dp[x ^ 1][j] * prob[k]) % MOD;
                    }
                }
            }
        }
        BitSet answerSet = new BitSet();
        answerSet.set(0);
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < (1 << N); j++) {
                if (answerSet.get(j))
                    answerSet.set(j | (1 << i));
            }
        }
        int answer = dp[x][idMap.get(answerSet)];
        System.out.println(answer);
        sc.close();
    }
}

