import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static class Modular {
        long val;
        Modular(long v) {
            val = v % MOD;
            if (val < 0) val += MOD;
        }
        Modular add(Modular b) {
            return new Modular((this.val + b.val) % MOD);
        }
        Modular subtract(Modular b) {
            return new Modular((this.val - b.val + MOD) % MOD);
        }
        Modular multiply(Modular b) {
            return new Modular((this.val * b.val) % MOD);
        }
        Modular divide(Modular b) {
            return this.multiply(inv(b));
        }
        static Modular inv(Modular a) {
            return new Modular(invGeneral(a.val, MOD));
        }
    }

    static long invGeneral(long a, long b) {
        a %= b;
        if (a == 0) return b == 1 ? 0 : -1;
        long x = invGeneral(b, a);
        return x == -1 ? -1 : ((1 - b * x) / a + b) % b;
    }

    static long pow(long a, long p) {
        long result = 1;
        long base = a;
        while (p > 0) {
            if ((p & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            p >>= 1;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        Modular[][] p = new Modular[n][n];

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                double val = Double.parseDouble(st.nextToken());
                p[i][j] = new Modular(Math.round(val * 100));
                p[i][j] = p[i][j].divide(new Modular(100));
            }
        }

        long[] no = new long[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                if (((j >> i) & 1) == 0) {
                    no[i] |= 1L << j;
                }
            }
        }

        Map<Long, Modular> m = new HashMap<>();
        m.put(1L, new Modular(1));

        for (int i = 0; i < n; i++) {
            Map<Long, Modular> M = new HashMap<>();
            for (Map.Entry<Long, Modular> t : m.entrySet()) {
                for (int j = 0; j < (1 << n); j++) {
                    long res = 0;
                    Modular prob = new Modular(1);
                    for (int k = 0; k < n; k++) {
                        if (((j >> k) & 1) == 1) {
                            prob = prob.multiply(p[i][k]);
                            res |= (no[k] << (1 << k));
                        } else {
                            prob = prob.multiply(new Modular(1).subtract(p[i][k]));
                        }
                    }
                    M.put(res, M.getOrDefault(res, new Modular(0)).add(t.getValue().multiply(prob)));
                }
            }
            m = M;
        }

        System.out.println(m.getOrDefault((1L << n) - 1, new Modular(0)).val);
    }
}

