import java.util.*;
import java.io.*;

public class Main {
    static class Mint {
        private static final int MD = (int)1e9+7;
        private long v;

        public Mint() {
            this.v = 0;
        }

        public Mint(long _v) {
            setV(_v % MD + MD);
        }

        public Mint setV(long _v) {
            this.v = _v;
            if (v >= MD) v -= MD;
            return this;
        }

        public boolean isZero() {
            return v != 0;
        }

        public Mint neg() {
            return new Mint().setV(0).subtract(this);
        }

        public Mint add(Mint r) {
            return new Mint().setV(this.v + r.v);
        }

        public Mint subtract(Mint r) {
            return new Mint().setV(this.v + MD - r.v);
        }

        public Mint multiply(Mint r) {
            return new Mint().setV(this.v * r.v % MD);
        }

        public Mint divide(Mint r) {
            return this.multiply(r.inv());
        }

        public Mint pow(long n) {
            Mint x = this;
            Mint r = new Mint(1);
            while (n > 0) {
                if ((n & 1) == 1) r = r.multiply(x);
                x = x.multiply(x);
                n >>= 1;
            }
            return r;
        }

        public Mint inv() {
            return pow(MD - 2);
        }

        public String toString() {
            return String.valueOf(v);
        }
    }

    static class Pair {
        List<Integer> first;
        Mint second;

        public Pair(List<Integer> first, Mint second) {
            this.first = first;
            this.second = second;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n = Integer.parseInt(br.readLine().trim());

        Mint[][] mat = new Mint[n][n];

        for (int i = 0; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n; j++) {
                int x = Integer.parseInt(st.nextToken());
                mat[i][j] = new Mint(x).divide(new Mint(100));
            }
        }

        List<Pair> sts = new ArrayList<>();
        sts.add(new Pair(new ArrayList<>(Arrays.asList(0)), new Mint(1)));

        for (int ph = 0; ph < n; ph++) {
            List<Pair> nsts = new ArrayList<>();
            int totalF = 1 << n;
            for (int f = 1; f < totalF; f++) {
                Mint freq = new Mint(1);
                for (int i = 0; i < n; i++) {
                    if (((f >> i) & 1) == 1) {
                        freq = freq.multiply(mat[ph][i]);
                    } else {
                        freq = freq.multiply(new Mint(1).subtract(mat[ph][i]));
                    }
                }

                for (Pair st : sts) {
                    List<Integer> nst = new ArrayList<>();
                    for (int d : st.first) {
                        for (int i = 0; i < n; i++) {
                            if (((d >> i) & 1) == 1) continue;
                            if (((f >> i) & 1) == 0) continue;
                            List<Integer> newD = new ArrayList<>(st.first);
                            newD.remove((Integer)d);
                            int newVal = d ^ (1 << i);
                            newD.add(newVal);
                            nst.addAll(newD);
                        }
                    }
                    if (nst.isEmpty()) continue;
                    Collections.sort(nst);
                    nst = new ArrayList<>(new LinkedHashSet<>(nst));
                    nsts.add(new Pair(nst, st.second.multiply(freq)));
                }
            }
            nsts.sort((a, b) -> {
                for (int i = 0; i < Math.min(a.first.size(), b.first.size()); i++) {
                    int cmp = Integer.compare(a.first.get(i), b.first.get(i));
                    if (cmp != 0) return cmp;
                }
                return Integer.compare(a.first.size(), b.first.size());
            });
            List<Pair> newSts = new ArrayList<>();
            for (Pair st : nsts) {
                if (!newSts.isEmpty() && newSts.get(newSts.size() - 1).first.equals(st.first)) {
                    newSts.get(newSts.size() - 1).second = newSts.get(newSts.size() - 1).second.add(st.second);
                } else {
                    newSts.add(new Pair(st.first, st.second));
                }
            }
            sts = newSts;
        }

        Mint ans = new Mint(0);
        if (!sts.isEmpty()) {
            ans = sts.get(0).second;
        }

        System.out.println(ans);
    }
}

