public class Main {
    static final int mod = 1000000007;

    static int add(int a, int b) {
        a += b;
        if (a >= mod) a -= mod;
        return a;
    }

    static int mult(int a, int b) {
        long t = 1L * a * b;
        if (t >= mod) t %= mod;
        return (int) t;
    }

    static int dec(int a, int b) {
        a -= b;
        if (a < 0) a += mod;
        return a;
    }

    static int power(int a, int b) {
        int out = 1;
        while (b > 0) {
            if ((b & 1) != 0) out = mult(out, a);
            a = mult(a, a);
            b >>= 1;
        }
        return out;
    }

    static int lowbit(int x) {
        return x & (-x);
    }

    static int n, a[][] = new int[10][10], idcnt = 0;
    static int[][] ch = new int[70010][128], q = new int[10][128], dp[][] = new int[10][70010];
    static Map<BitSet<Integer>, Integer> id = new HashMap<>();

    static int dfs(BitSet<Integer> s) {
        if (id.containsKey(s))
            return id.get(s);
        id.put(s, ++idcnt);
        for (int i = 0; i < (1 << n); i++) {
            BitSet<Integer> tmp = (BitSet<Integer>) s.clone();
            for (int j = 0; j < (1 << n); j++) {
                if (!tmp.get(j)) {
                    int x = i & j;
                    while (x != 0) {
                        int t = lowbit(x);
                        int index = Integer.numberOfTrailingZeros(t);
                        if (s.get(index ^ j)) {
                            tmp.set(j);
                            break;
                        }
                        x -= t;
                    }
                }
            }
            ch[id.get(s)][i] = dfs(tmp);
        }
        return id.get(s);
    }

    public static void main(String[] args) throws IOException {
