import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    static long add(long x, long y) {
        return (x + y) % MOD;
    }

    static long sub(long x, long y) {
        x -= y;
        return (x < 0) ? x + MOD : x;
    }

    static long mult(long x, long y) {
        return (x * y) % MOD;
    }

    static long modpow(long x, long p) {
        if (p == 0) return 1;
        if ((p & 1) == 1) return mult(x, modpow(x, p - 1));
        long half = modpow(x, p >> 1);
        return mult(half, half);
    }

    static long modinv(long x) {
        return modpow(x, MOD - 2);
    }

    static int n;
    static List<long[]> A = new ArrayList<>();
    static long[][][] T; // dimensions: n+1, max family size, 1<<n, 1<<n
    static List<Map<Long, Long>> DP = new ArrayList<>();
    static int[] family;
    static int[] family_id;
    static List<List<Integer>> family_mask = new ArrayList<>();

    static void calc() {
        // Initialize family_mask for sizes 0..n
        for (int i=0; i<=n; i++) {
            family_mask.add(new ArrayList<>());
        }
        family = new int[1 << n];
        family_id = new int[1 << n];

        for (int mask=1; mask < (1 << n); ++mask) {
            family[mask] = family[mask >> 1] + (mask & 1);
        }

        for (int mask=0; mask < (1 << n); ++mask) {
            int size = family[mask];
            family_id[mask] = family_mask.get(size).size();
            family_mask.get(size).add(mask);
        }

        int maxK = n;
        T = new long[maxK+1][];
        for (int k=0; k<=maxK; ++k) {
            int size = family_mask.get(k).size();
            T[k] = new long[size][1 << n];
        }

