            int maskCount = family_mask.get(k).size();
            for (int i=0; i<maskCount; ++i) {
                int cm = family_mask.get(k).get(i);
                for (int mask=0; mask<(1 << n); ++mask) {
                    long ans = 0;
                    if ((mask & cm) == mask) continue;
                    for (int x=0; x<n; ++x) {
                        if ((cm & (1 << x)) != 0) continue;
                        if (((mask & (1 << x)) ) == 0) continue;
