import java.util.*;
import java.math.BigInteger;

public class Main {
    static final int N = 100010;
    static final int mod = 1000000007;
    static Map<BigInteger, Integer> idMap = new HashMap<>();
    static int tt = 0;
    static int[][] ch;
    static int[][] p;
    static int[][] qArr;
    static int[][][] f;
    static int n;

    // Helper method for modular exponentiation
    static int qpow(int a, int b) {
        long ret = 1;
        long base = a % mod;
        int exponent = b;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                ret = (ret * base) % mod;
            }
            base = (base * base) % mod;
            exponent >>= 1;
        }
        return (int) ret;
    }

    static int dfs(BigInteger s) {
        if (idMap.containsKey(s))
            return idMap.get(s);
        tt++;
        int currentId = tt;
        idMap.put(s, currentId);
        int maskLimit = 1 << n;
        for (int i = 0; i < maskLimit; i++) {
            BigInteger t = s;
            for (int j = 0; j < maskLimit; j++) {
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) != 0 && ((i >> k) & 1) != 0 && ((s.shiftRight(j ^ (1 << k)).and(BigInteger.ONE)).intValue()) == 1) {
                        t = t.or(BigInteger.ONE.shiftLeft(j));
                    }
                }
            }
            ch[currentId][i] = dfs(t);
        }
        return currentId;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();

        ch = new int[N][(1 << n)];
        p = new int[n][n];
        qArr = new int[n][(1 << n)];
        f = new int[n + 1][N];

        // Initialize the id map
        idMap.clear();

        // Run dfs to initialize id mapping
        BigInteger startState = BigInteger.ONE;
        int totalStates = dfs(startState);

        // Read probabilities p[i][j]
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = sc.nextInt();
                p[i][j] = (int)((long) val * qpow(100, mod - 2) % mod);
            }
        }

        // Precompute q[i][j]
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                qArr[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) != 0) {
                        qArr[i][j] = (int)((long) qArr[i][j] * p[k][i] % mod);
                    } else {
                        int val = (mod + 1 - p[k][i]) % mod;
                        qArr[i][j] = (int)((long) qArr[i][j] * val % mod);
                    }
                }
            }
        }

        // Initialize f[0][1] = 1
        f[0][1] = 1;

        int totalStatesCount = totalStates;

        for (int i = 0; i < n; i++) {
            for (int j = 1; j <= totalStatesCount; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int nextState = ch[j][k];
                    f[i + 1][nextState] = (int)((f[i + 1][nextState] + (long) f[i][j] * qArr[i][k]) % mod);
                }
            }
        }

        int answerIndex;
        if (n < 6) {
            int lastStateIndex = idMap.get(BigInteger.valueOf((1L << (1 << n))) - 1);
            answerIndex = lastStateIndex;
        } else {
            BigInteger maxState = BigInteger.ONE.shiftLeft(64).subtract(BigInteger.ONE);
            answerIndex = idMap.get(maxState);
        }

        System.out.println(f[n][answerIndex]);
        sc.close();
    }
}

