import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static final int MAXN = 20;
    static int[][] a = new int[MAXN][MAXN];
    static int[] b;
    static int[] mp;
    static int[] tot;
    static int[] f;
    static int[] g;
    static int[] vmaxCount;
    static List<Integer>[] v;
    static int n;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        b = new int[n * n];
        mp = new int[1 << n];
        tot = new int[MAXN + 1];
        v = new ArrayList[MAXN];
        for(int i = 0; i <= MAXN; i++){
            v[i] = new ArrayList<>();
        }
        int N = 1 << n; // size for subproblems

        // Read input matrix
        for(int i=0; i<n; i++){
            st = new StringTokenizer(br.readLine());
            for(int j=0; j<n; j++){
                a[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        // Normalize a[i][j]
        int inv100 = pow(100, MOD - 2);
        for(int i=0; i<n; i++){
            for(int j=0; j<n; j++){
                a[i][j] = (int)(((long)a[i][j] * inv100) % MOD);
                b[i*n + j] = a[i][j];
            }
        }

        // Precompute v and mp
        for(int i=0; i<(1<<n); i++){
            int count = Integer.bitCount(i);
            v[count].add(i);
            mp[i] = tot[count];
            tot[count]++;
        }

        int m = n / 2;
        int sizeF = 1 << (m * n);
        int sizeG = 1 << ((n - m) * n);

        f = new int[sizeF];
        g = new int[sizeG];

        // Process first part
        for(int i=0; i<sizeF; i++){
            long p = 1;
            int[] S = new int[3];
            for(int j=0; j<m*n; j++){
                long val = ((i >> j) & 1) != 0 ? b[j] : (MOD + 1 - b[j]) % MOD;
                p = (p * val) % MOD;
            }
            for(int j=0; j<m; j++){
                S[j] = (i >> (j * n)) & ((1 << n) - 1);
            }
            int st = 0;
            for(int j : v[m]){
                int[] s = new int[m];
                int totS = 0;
                for(int k=j; k != 0; k &= (k - 1)){
                    s[totS++] = Integer.numberOfTrailingZeros(k);
                }
                Arrays.sort(s, 0, totS);
                do {
                    boolean ok = true;
                    for(int idx=0; idx<m; idx++){
                        if(((S[idx] >> s[idx]) & 1) == 0){
                            ok = false;
                            break;
                        }
                    }
                    if(ok){
                        st |= 1 << mp[j];
                    }
                } while(nextPermutation(s, totS));
            }
            f[st] = (int)(((long)f[st] + p) % MOD);
        }
        fwt(f, 1 << tot[m]);

        // Process second part
        int N2 = n - m;
        for(int i=0; i<sizeG; i++){
            long p = 1;
            int[] S = new int[3];
            for(int j=0; j<N2 * n; j++){
                long val = ((i >> j) & 1) != 0 ? b[j + m * n] : (MOD + 1 - b[j + m * n]) % MOD;
                p = (p * val) % MOD;
            }
            for(int j=0; j<N2; j++){
                S[j] = (i >> (j * n)) & ((1 << n) -1);
            }
            int st = 0;
            for(int j : v[n - m]){
                int[] s = new int[N2];
                int totS = 0;
                for(int k=j; k !=0; k &= (k-1)){
                    s[totS++] = Integer.numberOfTrailingZeros(k);
                }
                Arrays.sort(s, 0, totS);
                do {
                    boolean ok = true;
                    for (int idx=0; idx<N2; idx++){
                        if(((S[idx] >> s[idx]) & 1) == 0){
                            ok = false;
                            break;
                        }
                    }
                    if(ok){
                        int index = ((~j)) & ((1 << n) -1);
                        st |= 1 << mp[index];
                    }
                } while(nextPermutation(s, totS));
            }
            g[st] = (int)(((long)g[st] + p) % MOD);
        }
        fwt(g, 1 << tot[n - m]);

        // Convolution and result
        long ans = 0;
        for(int i=0; i<(1 << tot[n]); i++){
            int fi = f[i];
            int gi = g[i];
            long val = ((long)fi * gi) % MOD;
            f[i] = (int)val;
        }
        fwt2(f, 1 << tot[n]);
        for(int i=1; i<(1<<tot[n]); i++){
            ans = (ans + f[i]) % MOD;
        }
        System.out.println(ans);
    }

    static int pow(int a, int b){
        int res = 1;
        int base = a % MOD;
        while(b > 0){
            if((b & 1) == 1){
                res = (int)(((long)res * base) % MOD);
            }
            base = (int)(((long)base * base) % MOD);
            b >>=1;
        }
        return res;
    }

    static boolean nextPermutation(int[] array, int length){
        int i = length -2;
        while(i>=0 && array[i] >= array[i+1]) i--;
        if(i<0) return false;
        int j=length -1;
        while(array[j] <= array[i]) j--;
        swap(array, i, j);
        reverse(array, i+1, length-1);
        return true;
    }

    static void swap(int[] array, int i, int j){
        int temp=array[i];
        array[i]=array[j];
        array[j]=temp;
    }

    static void reverse(int[] array, int start, int end){
        while(start<end){
            swap(array, start++, end--);
        }
    }

    static void fwt(int[] a, int lim){
        int half=lim>>1;
        if(half==0) return;
        for(int i=0;i<half;++i){
            int u=a[i];
            int v=a[i+half];
            a[i]= reduce(u+v);
            a[i+half]= reduce(u-v);
        }
        fwt(a,half);
        fwt(a+half,half);
    }

    static void fwt2(int[] a, int lim){
        int half=lim>>1;
        if(half==0) return;
        for(int i=0;i<half;++i){
            int u=a[i];
            int v=a[i+half];
            a[i]= reduce(u-v);
            a[i+half]= reduce(u+v);
        }
        fwt2(a,half);
        fwt2(a+half,half);
    }

    static int reduce(int x){
        if(x<0) return x + MOD;
        if(x>=MOD) return x - MOD;
        return x;
    }
}

