            for (int i = n; i < 6; i++) {
                for (int j = 0; j < 6; j++) {
                    p[i][j] = 0;
                }
                p[i][i] = 1;
            }
            n = 6;
        }

        int A = (1 << 6) - 1;

        for (int i = 0; i < 64; i++) {
            if (Integer.bitCount(i) == 3) {
                id[i] = ki++;
            }
        }

        // Precompute A_mask for 6 bits
        for (int i = 0; i < (1 << 6); i++) {
            A_mask[i] = i;
        }

