import java.util.*;
import java.io.*;

public class Main {
    static final int mod = 1000000007;
    static final int inv = 570000004;
    static int add(int a, int b) {
        return a + b < mod ? a + b : a + b - mod;
    }
    static int sub(int a, int b) {
        return a < b ? a - b + mod : a - b;
    }
    static int mul(int a, int b) {
        return (int)((long)a * b % mod);
    }
    static Map<BitSet, Integer> name = new HashMap<>();
    static int n, dfn;
    static int[][] son;
    static int[][] p;
    static int[][] q;
    static int[][] dp;
    static final int MAX_N = 7;
    static final int MAX_DFN = 65536;

    static int dfs(BitSet s) {
        if (name.containsKey(s))
            return name.get(s);
        int ret = dfn++;
        name.put((BitSet)s.clone(), ret);
        for (int i = 0; i < (1 << n); ++i) {
            BitSet t = (BitSet)s.clone();
            for (int j = 0; j < (1 << n); ++j) {
                if (!t.get(j)) {
                    for (int k = i & j; k != 0; k ^= k & -k) {
                        int index = j ^ (k & -k);
                        if (s.get(index)) {
                            t.set(j);
                            break;
                        }
                    }
                }
            }
            son[ret][i] = dfs(t);
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        dfn = 0;
        son = new int[MAX_DFN][1 << MAX_N];
        name.clear();

        // Initialize the array sizes based on maximum n
        p = new int[n][n];
        q = new int[n][1 << n];
        dp = new int[n + 1][1 << n];

        // Read the matrix p
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                // For each row, read n values
                p[i][j] = Integer.parseInt(st.nextToken());
                p[i][j] = mul(p[i][j], inv);
            }

        // For each i,j compute q[i][j]
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                q[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    int pVal = p[k][i];
                    if (((j >> k) & 1) != 0) {
                        q[i][j] = mul(q[i][j], pVal);
                    } else {
                        q[i][j] = mul(q[i][j], sub(1, pVal));
                    }
                }
            }
        }

        // Start DFS
        BitSet startSet = new BitSet(n);
        startSet.set(0); // Initialize s with only the first bit set
        int startNode = dfs(startSet);

        // Initialize DP
        dp[0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < dfn; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int to = son[j][k];
                    dp[i + 1][to] = add(dp[i + 1][to], mul(dp[i][j], q[i][k]));
                }
            }
        }

        // Create all bits set for result
        BitSet res = new BitSet(n);
        res.set(0, n); // set all bits to 1

        System.out.println(dp[n][name.get(res)]);

    }
}

