class ModInt {
    private static final long MOD = 1000000007;
    private final long v;

    public ModInt(long v) {
        this.v = norm(v);
    }

    public static ModInt zero() {
        return new ModInt(0);
    }

    public static ModInt one() {
        return new ModInt(1);
    }

    public ModInt add(ModInt other) {
        return new ModInt(norm(this.v + other.v));
    }

    public ModInt subtract(ModInt other) {
        return new ModInt(norm(this.v - other.v));
    }

    public ModInt multiply(ModInt other) {
        return new ModInt((this.v * other.v) % MOD);
    }

    public ModInt divide(ModInt other) {
        return this.multiply(other.inv());
    }

    public ModInt inv() {
        long[] result = extendedGCD(this.v, MOD);
        long x = result[1];
        return new ModInt(norm(x));
    }

    private static long[] extendedGCD(long a, long b) {
        if (b == 0) {
            return new long[] { a, 1, 0 };
        }
        long[] res = extendedGCD(b, a % b);
        long g = res[0];
        long x1 = res[2];
        long y1 = res[1] - (a / b) * res[2];
        return new long[] { g, x1, y1 };
    }

    private static long norm(long x) {
        long r = x % MOD;
        return r < 0 ? r + MOD : r;
    }

    @Override
    public String toString() {
        return String.valueOf(v);
    }
}

