        public Matrix(int size) {
            this.n = size;
            s = new long[n][n];
        }

        public static Matrix multiply(Matrix a, Matrix b) {
            Matrix c = new Matrix(a.n);
            for (int i = 0; i < a.n; i++) {
                for (int j = 0; j < a.n; j++) {
                    c.s[i][j] = 0;
                    for (int k = 0; k < a.n; k++) {
                        c.s[i][j] = (c.s[i][j] + a.s[i][k] * b.s[k][j]) % mod;
                    }
                }
            }
            return c;
        }

        public void swapRows(int row1, int row2) {
            long[] temp = s[row1];
            s[row1] = s[row2];
            s[row2] = temp;
        }

        public void swapColumns(int col1, int col2) {
            for (int i = 0; i < n; i++) {
                long temp = s[i][col1];
                s[i][col1] = s[i][col2];
                s[i][col2] = temp;
            }
        }

        public Matrix cloneMatrix() {
            Matrix clone = new Matrix(this.n);
            for (int i = 0; i < n; i++) {
                System.arraycopy(this.s[i], 0, clone.s[i], 0, n);
            }
            return clone;
        }
    }

