        v = new long[N];
    }

    static class Node {
        long[][] v;

        Node() {
            v = new long[35][35];
            for (int i = 0; i < 35; i++)
                for (int j = 0; j < 35; j++)
                    v[i][j] = 0;
        }
    }

    static Node multiply(Node a, Node b) {
        Node c = new Node();
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    c.v[i][j] = (c.v[i][j] + a.v[i][k] * b.v[k][j] % mod) % mod;
                }
            }
        }
        return c;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        m = sc.nextInt();

        v[0] = n;
        len = 0;
        while (v[len] != 0) {
            v[len + 1] = v[len] / m;
            v[len] %= m;
            len++;
        }

        Node[][] T = new Node[N][35];
        Node[][] s1 = new Node[N][35];
        Node[][] s2 = new Node[N][35];

        for (int i = 0; i <= len; i++) {
            for (int j = 0; j <= m; j++) {
                T[i][j] = new Node();
                s1[i][j] = new Node();
                s2[i][j] = new Node();
            }
        }

