            if (i == 0) {
                for (int j = 0; j < m; j++) {
                    T[i][j].v[m][m] = 1;
                    for (int a = 0; a < m; a++) {
                        if (a != j) {
                            T[i][j].v[a][a] = 1;
                        } else {
                            for (int b = 0; b <= m; b++) {
                                T[i][j].v[a][b] = 1;
                            }
                        }
                    }
                }
