                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        res.a[i][k] = (res.a[i][k] + a[i][j] * m.a[j][k]) % P;
                    }
                }
            }
            return res;
        }

        Matrix pow(int x) {
            Matrix res = new Matrix(n, 1);
            Matrix aCopy = new Matrix(n);
            for (int i = 0; i < n; i++) {
                System.arraycopy(this.a[i], 0, aCopy.a[i], 0, n);
            }
            while (x > 0) {
                if ((x & 1) == 1) {
                    res = res.multiply(aCopy);
                }
                aCopy = aCopy.multiply(aCopy);
                x >>= 1;
            }
            return res;
        }

        long[] getRow(int index) {
            return a[index];
        }

        long[] getColumn(int index) {
            long[] col = new long[n];
            for (int i = 0; i < n; i++) {
                col[i] = a[i][index];
            }
