        String[] parts = br.readLine().split("\\s+");
        long n = Long.parseLong(parts[0]);
        int k = Integer.parseInt(parts[1]);
        final long P = (long) 1e9 + 7;

        if (n <= k) {
            System.out.println((1L << n) % P);
            return;
        }

        int logN = (int) (Math.log(n + 0.0) / Math.log(k + 0.0) + 2);

        // Initialize shift matrix
        Matrix shift = new Matrix(k + 1);
        for (int j = 0; j < k; j++) {
            shift.a[j][j] = 0;
            shift.a[(j + 1) % k][j] = 1;
        }

        List<Matrix> block = new ArrayList<>();
        // First block
        Matrix firstBlock = new Matrix(k + 1);
        for (int i = 1; i <= k; i++) {
            firstBlock.a[0][i] = 1;
        }
        block.add(firstBlock);

        // Precompute subsequent blocks
        for (int i = 1; i < logN; i++) {
            Matrix prev = block.get(i - 1);
            Matrix product = prev.multiply(shift);
            block.add(product.pow(k));
        }

        int i = 0;
        long len = 1;
        while (n / len >= k) {
            i++;
            len *= k;
        }

        Matrix m = new Matrix(k + 1);
        long remainingN = n;
        long tempLen = len;
        int tempIndex = i;

        while (remainingN > 0) {
            if (tempLen <= remainingN) {
                long x = remainingN / tempLen;
                Matrix baseMatrix = new Matrix(k + 1);
