            }
            tempIndex--;
            tempLen /= k;
        }

        long ans = 0;
        for (int iIdx = 0; iIdx <= k; iIdx++) {
            ans = (ans + m.a[iIdx][k]) % P;
        }
        System.out.println(ans);
    }
}

