            for (List<Integer> row : other) {
                this.add(new ArrayList<>(row));
            }
        }

        public Matrix shift(int shift) {
            int k = this.size() - 1;
            shift = (k - shift) % k;
            int n = this.size() - 1;
            Matrix res = new Matrix(n + 1, n + 1);
            for (int i=0; i<=n; i++) {
                for (int j=0; j<=n; j++) {
                    res.get(i).set(j, this.get((i + shift) % n).get((j + shift) % n));
                }
            }
            // last row
            for (int j=0; j<=n; j++) {
                res.get(n).set(j, this.get(n).get((j + shift) % n));
            }
            return res;
        }

        public static Matrix multiply(Matrix a, Matrix b) {
            int n = a.size() - 1;
            int k = a.get(0).size() - 1;
            int m = b.get(0).size() - 1;

            long[][] aa = new long[a.size()][a.get(0).size()];
            long[][] bb = new long[b.size()][b.get(0).size()];

            for (int i=0; i<=n; i++) {
                for (int j=0; j<=k; j++) {
                    aa[i][j] = a.get(i).get(j);
                }
            }
            for (int i=0; i<=k; i++) {
                for (int j=0; j<=m; j++) {
                    bb[j][i] = b.get(i).get(j);
                }
            }

