            for (int i=0; i<=n; i++) {
                for (int j=0; j<=m; j++) {
                    long tmpVal = 0;
                    for (int l=0; l<=k; l++) {
                        tmpVal += aa[i][l] * bb[j][l];
                    }
                    res.get(i).set(j, (int)(tmpVal % MOD));
                }
            }
            return res;
        }
    }

    public static void main(String[] args) {
