    static final int MAX_K = 32;
    static long n;
    static int k;
    static boolean eof = false;

    static class Mat extends ArrayList<long[]> {
        public Mat() {
            for (int i = 0; i <= k; i++) {
                long[] row = new long[k + 1];
                this.add(row);
            }
        }

        public static Mat identity() {
            Mat m = new Mat();
            for (int i = 0; i <= k; i++) {
                m.get(i)[i] = 1;
            }
            return m;
        }

        public static Mat multiply(Mat a, Mat b) {
            Mat c = new Mat();
            for (int i = 0; i <= k; i++)
                Arrays.fill(c.get(i), 0);
            for (int i = 0; i <= k; i++) {
                for (int j = 0; j <= k; j++) {
                    long sum = 0;
                    for (int t = 0; t <= k; t++) {
                        long val = (a.get(i)[t] * b.get(t)[j]) % MOD;
                        sum = (sum + val) % MOD;
                    }
                    c.get(i)[j] = sum;
                }
            }
            return c;
        }
    }

    static class ArrayMat extends ArrayList<Mat> {
        public ArrayMat() {
            for (int i = 0; i < 62; i++) {
                this.add(new Mat());
            }
        }
    }

    static boolean read() {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLong()) {
            n = sc.nextLong();
        } else {
            return false;
        }
        if (sc.hasNextInt()) {
            k = sc.nextInt();
            return true;
        }
        return false;
    }

    static long add(long a, long b) {
        a += b;
        if (a >= MOD)
            a -= MOD;
        return a;
    }

    static long mul(long a, long b) {
        return (a * b) % MOD;
    }

    static Map<String, Object> solve() {
        List<Long> num = new ArrayList<>();
        long tempN = n;
        while (tempN > 0) {
            num.add(tempN % k);
            tempN /= k;
        }

        // Initialize amat
        ArrayMat amat = new ArrayMat();
        for (int d = 0; d < k; d++) {
            for (int i = 0; i <= k; i++)
                Arrays.fill(amat.get(d).get(i), 0);
            for (int i = 0; i <= k; i++)
                amat.get(d).get(i)[i] = 1;
            for (int i = 0; i <= k; i++)
                amat.get(d).get(i)[d] = 1;
        }

        // Build the recursion
        for (int r = 1; r < num.size(); r++) {
            List<Mat> pr = new ArrayList<>();
            pr.add(new Mat());
            for (int i = 0; i <= k; i++)
                Arrays.fill(pr.get(0).get(i), 0);
            for (int i = 0; i <= k; i++)
                pr.get(0).get(i)[i] = 1;

            for (int i = 0; i < k; i++) {
                pr.add(Mat.multiply(pr.get(pr.size() - 1), amat.get(i)));
            }

            for (int sh = 0; sh < k; sh++) {
                Mat res = new Mat();
                for (int i = 0; i <= k; i++)
                    Arrays.fill(res.get(i), 0);
                res = pr.get(0);
                for (int i_sh = 0; i_sh < k - sh; i_sh++) {
                    res = Mat.multiply(res, amat.get((i_sh + sh) % k));
                }
                res = Mat.multiply(res, pr.get(sh));
                amat.set(sh, res);
            }
        }

        // DP
        Mat dp = new Mat();
        for (int i = 0; i <= k; i++)
            Arrays.fill(dp.get(i), 0);
        dp.get(0)[k] = 1;

        int rem = 0;
        for (int idx = num.size() - 1; idx >= 0; idx--) {
            int digit = num.get(idx).intValue();
            while (digit > 0) {
                dp = Mat.multiply(dp, amat.get(rem));
                rem = (rem + 1) % k;
                digit--;
            }
        }

        long ans = 0;
        for (int i = 0; i <= k; i++) {
            ans = add(ans, dp.get(0)[i]);
        }
        System.out.println(ans);
        Map<String, Object> result = new HashMap<>();
        result.put("answer", ans);
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            if (sc.hasNextLong()) {
                n = sc.nextLong();
            } else {
                break;
            }
            if (sc.hasNextInt()) {
                k = sc.nextInt();
            } else {
                break;
            }
            solve();
        }
    }
}

