            A = new long[n][n];
        }

        static Matrix identity(int n) {
            Matrix mat = new Matrix(n);
            for (int i = 0; i < n; i++) {
                mat.A[i][i] = 1;
            }
            return mat;
        }

        Matrix add(Matrix B) {
            int n = height(), m = width();
            Matrix res = new Matrix(n, m);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    res.A[i][j] = (this.A[i][j] + B.A[i][j]) % MOD;
                }
            }
            return res;
        }

        Matrix subtract(Matrix B) {
            int n = height(), m = width();
            Matrix res = new Matrix(n, m);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    res.A[i][j] = (this.A[i][j] - B.A[i][j] + MOD) % MOD;
                }
            }
            return res;
        }

        Matrix multiply(Matrix B) {
            int n = height(), m = B.width(), p = width();
            Matrix res = new Matrix(n, m);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    long sum = 0;
                    for (int k = 0; k < p; k++) {
                        sum += this.A[i][k] * B.A[k][j];
                    }
                    res.A[i][j] = sum % MOD;
                }
            }
            return res;
        }

        Matrix power(long k) {
            Matrix result = identity(height());
            Matrix base = this;
            while (k > 0) {
                if ((k & 1) == 1) {
                    result = result.multiply(base);
                }
                base = base.multiply(base);
                k >>= 1;
            }
            return result;
        }

        int height() {
            return A.length;
        }

        int width() {
            return A[0].length;
        }
    }

    static long beki(long a, long b) {
        long ret = 1;
        long base = a;
        long exp = b;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                ret = (ret * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return ret;
    }

