        if (t >= MOD) t %= MOD;
        return (int) t;
    }

    static class Matrix {
        int[][] dat;
        int N, M;

        Matrix(int n, int m) {
            this.N = n;
            this.M = m;
            dat = new int[N][M];
        }

        void init() {
            for (int i = 0; i < N; i++)
                Arrays.fill(dat[i], 0);
        }

        void iden() {
            init();
            int size = Math.min(N, M);
            for (int i = 0; i < size; i++) {
                dat[i][i] = 1;
            }
        }

        Matrix trans() {
            Matrix out = new Matrix(M, N);
            for (int i = 0; i < M; i++)
                for (int j = 0; j < N; j++)
                    out.dat[i][j] = dat[j][i];
            return out;
        }

        int[] getRow(int x) {
            return dat[x];
        }

        int[] getCol(int x) {
            int[] col = new int[N];
            for (int i = 0; i < N; i++) {
                col[i] = dat[i][x];
            }
