                    out.dat[i][j] = mult(this.dat[i][j], x);
            return out;
        }

        static Matrix multiply(Matrix a, Matrix b) {
            int n = a.N;
            int m = a.M;
            int p = b.M;
            Matrix out = new Matrix(n, p);
            out.init();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (a.dat[i][j] != 0) {
                        int[] bRow = b.dat[j];
                        int val = a.dat[i][j];
                        for (int k = 0; k < p; k++) {
                            if (bRow[k] != 0) {
                                out.dat[i][k] = add(out.dat[i][k], mult(val, bRow[k]));
                            }
                        }
                    }
                }
            }
            return out;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        long n = sc.nextLong();
        int K = sc.nextInt();

