            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    tmp[i][j] = 0;
                }
            }
            for (int i = 1; i <= n; i++) {
                for (int k = 1; k <= n; k++) {
                    for (int j = 1; j <= n; j++) {
                        tmp[i][j] += (long) a[i][k] * rhs.a[k][j];
                        if (tmp[i][j] >= MODLL) tmp[i][j] -= MODLL;
                    }
                }
            }
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    ans.a[i][j] = (int) (tmp[i][j] % MOD);
                }
            }
            return ans;
        }
    }

    static class Solver {
