        static Matrix[][] sump = new Matrix[80][MAXN];
        static Matrix[][] sums = new Matrix[80][MAXN];

        static void mainSolver() {
            int[] num = new int[80];
            int cnt = 0;

            long tempN = n;
            while (tempN > 0) {
                num[++cnt] = (int)(tempN % k);
                tempN /= k;
