                    f[0][i] = new Matrix();
                    f[0][i].n = k + 1;
                    f[0][i].set();
                }
                for (int j = 1; j <= k + 1; j++) {
                    f[0][i].a[j][j] = 1;
                    f[0][i].a[i + 1][j] = 1;
                }
            }
            // Initialize sump and sums for 0-th index
            for (int i = 0; i < k; i++) {
                sump[0][i] = f[0][i];
            }
            sums[0][k - 1] = f[0][k - 1];

            for (int i = 1; i < k; i++) {
                sump[0][i] = sump[0][i - 1].multiply(f[0][i]);
            }

            for (int i = k - 2; i >= 0; i--) {
                sums[0][i] = f[0][i].multiply(sums[0][i + 1]);
            }

            for (int i = 1; i < cnt; i++) {
                for (int j = 0; j < k; j++) {
