                sum += limit;
                sum %= k;
            }

            int res = 0;
            for (int i = 1; i <= k + 1; i++) {
                res = (res + ans.a[i][k + 1]) % (int)MOD;
            }

            System.out.println(res);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextInt();
        Solver.mainSolver();
        sc.close();
    }
