public class Main {
    static final int maxn = 32;
    static final int mod = 1000000007;
    static int n;

    static class Matrix {
        int[][] a;

        public Matrix() {
            a = new int[maxn][maxn];
        }

        void clear() {
            for (int i = 0; i < maxn; i++) {
                for (int j = 0; j < maxn; j++) {
                    a[i][j] = 0;
                }
            }
        }

        void output() {
            for (int i = 1; i <= n + 1; i++) {
                for (int j = 1; j <= n + 1; j++) {
                    System.out.print(a[i][j] + (j == n+1 ? "\n" : " "));
                }
            }
            System.out.println();
        }

        Matrix multiply(Matrix rhs) {
            Matrix B = new Matrix();
            B.clear();
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    for (int k = 1; k <= n; k++) {
                        add(B.a[i][j], (long) a[i][k] * rhs.a[k][j] % mod);
                    }
                }
            }
            return B;
        }
    }

    static void add(int x, int y) {
        x += y;
        if (x >= mod) x -= mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long m = sc.nextLong();
        n = sc.nextInt();

