        for (int i = 1; i <= n; i++) {
            ans.a[i][i] = 1; // Set ans as identity
        }
        ans = E;  // Initialize ans with identity

        Matrix[] A = new Matrix[maxn];
        Matrix[] pre = new Matrix[maxn];
        Matrix[] suf = new Matrix[maxn];

        for (int i = 1; i <= n; i++) {
            A[i] = new Matrix();
            A[i].clear();
            for (int j = 1; j <= n; j++) {
                A[i].a[j][j] = 1;
            }
        }

        // Initialize A for each row
        for (int i = 1; i <= n; i++) {
            // Copy identity for A[i]
            for (int j = 1; j <= n; j++) {
                A[i].a[j][j] = 1;
            }
            // Set specific element
            A[i].a[i][i] = 1;
        }

        pre[0] = new Matrix();
        pre[0].clear();
        for (int i = 1; i <= n; i++) {
            pre[i] = new Matrix();
            pre[i].clear();
            pre[i] = pre[i - 1].multiply(A[i]);
