    static class Matrix {
        int[][] v = new int[35][35];

        Matrix() {
            for (int i = 0; i < v.length; i++) {
                Arrays.fill(v[i], 0);
            }
        }

        Matrix multiply(Matrix a) {
            Matrix res = new Matrix();
            for (int k = 0; k <= K; k++) {
                for (int i = 0; i <= K; i++) {
                    if (v[i][k] != 0) {
                        for (int j = 0; j <= K; j++) {
                            if (a.v[k][j] != 0) {
                                long val = (1L * v[i][k] * a.v[k][j]) + res.v[i][j];
                                res.v[i][j] = (int) (val % Mod);
                            }
                        }
                    }
                }
            }
            return res;
        }
    }

    static Matrix[] s = new Matrix[75];
    static Matrix[] pre = new Matrix[75];
    static Matrix[] suf = new Matrix[75];
    static Matrix[] ans;

    static void addMod(int[] x, int y, int m) {
        // We can directly do modular addition
        int temp = x[0] + y;
        if (temp >= m) temp -= m;
        x[0] = temp;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        K = sc.nextInt();

        // Process n into array a
        work(n);

        ans = new Matrix[K + 1];
        for (int i = 0; i <= K; i++) {
            ans[i] = new Matrix();
        }
        // Initialize ans as identity
        for (int i = 0; i <= K; i++) {
            ans[i].v[i][i] = 1;
        }

        for (int i = 0; i < 75; i++) {
            s[i] = new Matrix();
            pre[i] = new Matrix();
            suf[i] = new Matrix();
        }

        // Initialize s[0][i]
        for (int i = 0; i < K; i++) {
            for (int j = 0; j <= K; j++) {
                s[0][i].v[j][j] = 1;
                s[0][i].v[i][j] = 1;
            }
        }

        // Build the prefix/suffix matrices
        for (int i = 1; i <= m; i++) {
            int idx = i - 1;
            System.arraycopy(s[idx], 0, pre[i - 1], 0, K); // copy array
            System.arraycopy(s[idx], 0, suf[i - 1], 0, K);
            for (int j = 1; j < K; j++) {
                pre[i - 1] = pre[i - 1].multiply(s[idx][j]);
            }
            for (int j = K - 2; j >= 0; j--) {
                suf[i - 1] = s[idx][j].multiply(suf[i - 1]);
            }
            for (int j = 0; j < K; j++) {
                if (j > 0) {
                    s[i][j] = suf[i - 1].multiply(pre[i - 1][j - 1]);
                } else {
                    s[i][j] = suf[i - 1];
                }
            }
        }

        int now = 0;
        for (int i = 1; i <= m; i++) {
            int ai = a[i];
            if (ai > 0) {
                if (now + ai - 1 >= K) {
                    for (int j = now; j < K; j++) {
                        ans = ansMultiply(ans, s[m - i][j]);
                    }
                    for (int j = 0; j <= (now + ai - 1) - K; j++) {
                        ans = ansMultiply(ans, s[m - i][j]);
                    }
                } else {
                    for (int j = now; j <= now + ai - 1; j++) {
                        ans = ansMultiply(ans, s[m - i][j]);
                    }
                }
                now = (now + ai) % K;
            }
        }

        int totalSum = 0;
