        sc.close();
    }

    static void work(long n) {
        long tmp = n;
        m = 0;
        while (tmp > 0) {
            a[++m] = (int) (tmp % K);
            tmp /= K;
        }
        // reverse array a[1..m]
        int left = 1, right = m;
        while (left < right) {
            int temp = a[left];
            a[left] = a[right];
            a[right] = temp;
            left++;
            right--;
        }
    }

    static Matrix[] ansMultiply(Matrix[] matArr, Matrix mtx) {
        Matrix[] result = new Matrix[matArr.length];
        for (int i = 0; i < matArr.length; i++) {
            result[i] = matArr[i].multiply(mtx);
        }
        return result;
    }
}

