import java.util.Scanner;

public class Main {
    static final long mod = 1000000007;
    static final int N = 33;
    static long[] bin = new long[N * 2];
    static int n, m;

    static class Matrix {
        long[][] mat = new long[N][N];

        Matrix multiply(Matrix a, int m) {
            Matrix res = new Matrix();
            for (int i = 0; i <= m; i++) {
                for (int j = 0; j <= m; j++) {
                    res.mat[i][j] = 0;
                    for (int k = 0; k <= m; k++) {
                        res.mat[i][j] = (res.mat[i][j] + this.mat[i][k] * a.mat[k][j]) % mod;
                    }
                }
            }
            return res;
        }

        static Matrix identity(int size) {
            Matrix result = new Matrix();
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    result.mat[i][j] = (i == j) ? 1 : 0;
                }
            }
            return result;
        }
    }

    public static long readLong(Scanner sc) {
        return sc.nextLong();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = (int) readLong(sc);
        m = (int) readLong(sc);
        int n2 = n;
        int len = -1;
        while (n2 > 0) {
            len++;
            bin[len] = n2 % m;
            n2 /= m;
        }
        len++;
        Matrix ans = new Matrix();
        ans.mat[0][0] = 1;
        for (int i = 0; i <= m; i++) {
            ans.mat[0][i] = 1;
        }

        Matrix[][] P = new Matrix[N * 2][N];
        Matrix[][] S = new Matrix[N * 2][N];
        Matrix[][] A = new Matrix[N * 2][N];

        for (int i = 0; i < len; i++) {
            for (int j = 0; j <= m; j++) {
                A[i][0] = new Matrix();
                for (int k = 0; k < N; k++) {
                    A[i][0].mat[k][k] = 1;
                }
            }
            if (i == 0) {
                for (int j = 0; j < m; j++) {
                    A[i][j] = new Matrix();
                    for (int k = 0; k < N; k++) {
                        for (int l = 0; l < N; l++) {
                            A[i][j].mat[k][l] = 0;
                        }
                    }
                    A[i][j].mat[m][m] = 1;
                    for (int k = 0; k < m; k++) {
                        if (k != j) {
                            A[i][j].mat[k][k] = 1;
                        } else {
                            for (int l = 0; l <= m; l++) {
                                A[i][j].mat[k][l] = 1;
                            }
                        }
                    }
                }
            } else {
                for (int j = 0; j < m; j++) {
                    if (j == 0) {
                        S[i - 1][0] = new Matrix();
                        S[i - 1][0].mat = S[i - 1][0].mat.clone(); // ensure copy
                        A[i][j] = S[i - 1][0];
                    } else {
                        // Multiplication S[i-1][j] * P[i-1][j-1]
                        A[i][j] = multiplyMatrices(S[i - 1][j], P[i - 1][j - 1], m);
                    }
                }
            }
            P[i][0] = A[i][0];
            for (int j = 1; j < m; j++) {
                P[i][j] = multiplyMatrices(P[i][j - 1], A[i][j], m);
            }
            S[i][m - 1] = A[i][m - 1];
            for (int j = m - 2; j >= 0; j--) {
                S[i][j] = multiplyMatrices(A[i][j], S[i][j + 1], m);
            }
        }

        int j = 0;
        for (int i = len - 1; i >= 0; i--) {
            while (bin[i] > 0) {
                ans = multiplyMatrices(ans, A[i][j], m);
                j++;
                if (j == m) j = 0;
                bin[i]--;
            }
        }

        System.out.println(ans.mat[0][m]);
        sc.close();
    }

    static Matrix multiplyMatrices(Matrix a, Matrix b, int m) {
        Matrix res = new Matrix();
        res = res.multiply(a, b, m);
        return res;
    }
}

