    static class Matrix {
        static class Mint {
            static final int MOD = 1000000007;
            int x;

            public Mint() {
                this.x = 0;
            }

            public Mint(int sig) {
                sig %= MOD;
                if (sig < 0) sig += MOD;
                this.x = sig;
            }

            public int get() {
                return x;
            }

            public Mint add(Mint that) {
                int res = this.x + that.x;
                if (res >= MOD)
                    res -= MOD;
                return new Mint(res);
            }

            public Mint subtract(Mint that) {
                int res = this.x - that.x;
                if (res < 0)
                    res += MOD;
                return new Mint(res);
            }

            public Mint multiply(Mint that) {
                long res = (long) this.x * that.x % MOD;
                return new Mint((int) res);
            }
        }

