        public Matrix() {
            v = new ArrayList<>();
        }

        public Matrix(int n, int m) {
            v = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                List<Mint> row = new ArrayList<>();
                for (int j = 0; j < m; j++) {
                    row.add(new Mint(0));
                }
                v.add(row);
            }
        }

        public int height() {
