            for (int i = 0; i < n; i++) {
                A.set(i, i, new Mint(1));
            }
            return A;
        }

        public Matrix multiply(Matrix B) {
            int n = this.height();
            int p = this.width();
            int m = B.width();
            int q = B.height();
            if (q != p) throw new AssertionError();

            w = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                List<Mint> row = new ArrayList<>();
                for (int j = 0; j < m; j++) {
                    row.add(new Mint(0));
                }
                w.add(row);
