            Matrix B = new Matrix();
            B.clear();
            for (int i = 1; i <= n + 1; i++) {
                for (int j = 1; j <= n + 1; j++) {
                    for (int k = 1; k <= n + 1; k++) {
                        add(B.a[i][j], (long) a[i][k] * rhs.a[k][j] % mod);
                    }
                }
            }
            return B;
        }
    }

    static int n;
    static long m;
    static Matrix ans = new Matrix();
    static Matrix E = new Matrix();
    static Matrix[] A = new Matrix[maxn];
    static Matrix[] pre = new Matrix[maxn];
    static Matrix[] suf = new Matrix[maxn];

    static void add(int x, int y) {
        x += y;
        if (x >= mod) x -= mod;
    }

    public static void main(String[] args) {
