        for (int i = 1; i <= n; i++) {
            A[i] = new Matrix();
            A[i].clear();
            for (int j = 1; j <= n; j++) {
                A[i].a[j][j] = 1;
            }
            A[i].a[i][i] = 1;
        }

        pre[0] = new Matrix();
        pre[0].clear();
        suf[n + 1] = new Matrix();
        suf[n + 1].clear();
        for (int i = 1; i <= n; i++) {
            pre[i] = new Matrix();
            pre[i].clear();
            suf[i] = new Matrix();
            suf[i].clear();
        }

        while (m != 0) {
            long u = m % n;
            long s = 0;
            long temp = m / n;
            while (temp != 0) {
                s = (s + temp % n) % n;
                temp /= n;
            }
            long u_mod = u;
            if (u_mod != 0) {
                long total = s + u_mod - 1;
                long u_idx = (total % n) + 1;
                long s_idx = s + 1;
                long u_cursor = u_idx;
                while (u_cursor != s_idx) {
