import java.util.Scanner;

public class Main {
    static int n, k, p;
    static int[][] f;
    static long[] fac, inv;

    static long fpow(long a, int b) {
        long ans = 1;
        long t = a;
        while (b > 0) {
            if ((b & 1) == 1) ans = (ans * t) % p;
            t = (t * t) % p;
            b >>= 1;
        }
        return ans;
    }

    static int lowbit(int x) {
        return x & (-x);
    }

    static void init() {
        fac = new long[n + 1];
        inv = new long[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (fac[i - 1] * i) % p;
        }
        inv[n] = fpow(fac[n], p - 2);
        for (int i = n; i >= 1; i--) {
            inv[i - 1] = (inv[i] * i) % p;
        }
    }

    static long solve(int cur, int S) {
        if (f[cur][S] != -1) {
            return f[cur][S];
        }
        if (S == 0) {
            long res = fac[n];
            for (int i = 1; i <= cur; i++) {
                res = (res * (k - i + 1)) % p;
            }
            f[cur][S] = res;
            return f[cur][S];
        }
        long res = 0;
        int U = S - lowbit(S);
        for (int T = U; T != 0; T = (T - 1) & U) {
            res = (res + (inv[S - T] * solve(cur + 1, T)) % p) % p;
        }
        res = (res + (inv[S] * solve(cur + 1, 0)) % p) % p;
        f[cur][S] = res;
        return f[cur][S];
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        k = scanner.nextInt();
        p = scanner.nextInt();

        int ans = 1;
        for (int i = 1; i <= n; i++) {
            ans = (ans * k) % p;
        }

        if (n % 2 == 0) {
            init();
            f = new int[n + 2][1 << n]; // size enough for S up to 2^n
            for (int i = 0; i <= n + 1; i++) {
                for (int j = 0; j < (1 << n); j++) {
                    f[i][j] = -1;
                }
            }
            ans = (ans - (int) solve(0, n) + p) % p;
        }
        System.out.println(ans);
        scanner.close();
    }
}

