public class Main {
    public static void main(String[] args) {
        java.util.Scanner sc = new java.util.Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int mod = sc.nextInt();

        int maxn = 270005;
        int[][] f = new int[19][maxn];
        java.util.ArrayList<Long> g = new java.util.ArrayList<>();
        int[] cnt = new int[maxn];

        int m, l = 0;

        // Function to safe modulo
        int upd(int x) {
            if (x < 0) return x + mod;
            if (x >= mod) return x - mod;
            return x;
        }

        // Add function
        void add(int[] x, int y) {
            for (int i = 0; i < x.length; i++) {
                x[i] = upd(x[i] + y);
            }
        }

        // Fast exponentiation
        int ksm(int x, int k) {
            int ans = 1;
            int base = x % mod;
            int power = k;
            while (power > 0) {
                if ((power & 1) == 1) {
                    ans = (int)((long)ans * base % mod);
                }
                base = (int)((long)base * base % mod);
                power >>= 1;
            }
            return ans;
        }

        int[] jc = new int[maxn];
        int[] inv = new int[maxn];

        // Initialize factorials and inverses
        void init(int nVal) {
            jc[0] = 1;
            for (int i = 1; i <= nVal; i++) {
                jc[i] = (int)((long)jc[i - 1] * i % mod);
            }
            inv[nVal] = ksm(jc[nVal], mod - 2);
            for (int i = nVal - 1; i >= 0; i--) {
                inv[i] = (int)((long)inv[i + 1] * (i + 1) % mod);
            }
        }

        // Function for transforming
        void F(int[] fRow, int size, int h) {
            for (int p = 1; p < size; p <<= 1) {
                for (int i = 0; i < size; i += (p << 1)) {
                    for (int k = i; k < i + p; k++) {
                        add(fRow, k + p, h * fRow[k]);
                    }
                }
            }
        }

        // Add element at position
        void add(int[] arr, int index, int val) {
            arr[index] = upd(arr[index] + val);
        }

        // Polynomial multiplication
        java.util.ArrayList<Long> multiply(java.util.ArrayList<Long> A, java.util.ArrayList<Long> B, int l) {
            java.util.ArrayList<Long> C = new java.util.ArrayList<>();
            for (int i = 0; i <= l; i++) C.add(0L);
            for (int i = 0; i <= l; i++) {
                for (int j = 0; j <= l - i; j++) {
                    long val = C.get(i + j) + A.get(i) * B.get(j);
                    C.set(i + j, val % mod);
                }
            }
            return C;
        }

        // Polynomial exponentiation
        java.util.ArrayList<Long> pksm(java.util.ArrayList<Long> A, int k, int l) {
            java.util.ArrayList<Long> C = new java.util.ArrayList<>();
            for (int i = 0; i <= l; i++) C.add(0L);
            C.set(0, 1L);
            java.util.ArrayList<Long> base = new java.util.ArrayList<>(A);
            int power = k;
            while (power > 0) {
                if ((power & 1) == 1) {
                    C = multiply(C, base, l);
                }
                base = multiply(base, base, l);
                power >>= 1;
            }
            return C;
        }

        // Read input
        init(n);
        if ((n & 1) == 1) {
            System.out.println(ksm(k, n));
            return;
        }
        m = 1;
        while (m <= n) m <<= 1;
        l = 0;

        // Calculate cnt array
        for (int i = 0; i < m; i++) {
            cnt[i] = (i >> 1) + (i & 1);
        }

        init(m);

        for (int i = 0; i < m; i++) {
            f[cnt[i]][i] = inv[i];
        }

        for (int i = 0; i < l; i++) {
            F(f[i], m, 1);
        }

        g = new java.util.ArrayList<>();
        for (int s = 0; s < m; s++) {
            g.clear();
            for (int i = 0; i <= l; i++) {
                g.add((long) f[i][s]);
            }
            g = pksm(g, k, l);
            for (int i = 0; i <= l; i++) {
                f[i][s] = g.get(i).intValue();
            }
        }

        // Apply inverse transform
        F(f[cnt[n]], m, -1);

        long ans = upd(ksm(k, n) - (long)f[cnt[n]][n] * jc[n] % mod);
        System.out.println(ans);
    }
}

