import java.util.Scanner;

public class Main {
    static int n, k, mod;
    static int[][] dp = new int[18][260000];
    static int[] list = new int[33];
    static int cnt_list;
    static int[] bi = new int[33]; // Not used in the original code
    static int cnt;
    static long[] fac = new long[260000];
    static long[] inv = new long[260000];
    static int[] len = new int[260000];
    static boolean[] vis = new boolean[260000];

    static long power(long a, int n) {
        if (n == 0)
            return 1;
        long ret = power(a, n / 2);
        ret = (ret * ret) % mod;
        if (n % 2 == 1)
            ret = (ret * a) % mod;
        return ret;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        mod = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(power(k, n) % mod);
        } else {
            // Precompute factorials
            fac[0] = 1;
            for (int i = 1; i <= n; i++) {
                fac[i] = (fac[i - 1] * i) % mod;
            }
            // Compute inverse of fac[n] using Fermat's little theorem
            inv[n] = power(fac[n], mod - 2);
            for (int i = n - 1; i >= 0; i--) {
                inv[i] = (inv[i + 1] * (i + 1)) % mod;
            }

            // List of bits in n
            int cnt_list = 0;
            for (int i = 0; (1 << i) <= n; i++) {
                if (((n >> i) & 1) == 1) {
                    list[cnt_list++] = i;
                }
            }

            // Initialize dp array
            for (int i = 0; i <= n; i++) {
                len[i] = 0;
                int j = i;
                while (j != 0) {
                    len[i]++;
                    j = (j - 1) & j;
                }
            }
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    dp[i][j] = 0;
                }
            }
            dp[0][0] = 1;

            // Compute all subsets of n and mark visited
            for (int i = 0; i <= n; i++) {
                int mask = i;
                int temp = mask;
                while (true) {
                    vis[temp] = true;
                    if (temp == 0)
                        break;
                    temp = (temp - 1) & mask;
                }
            }

            // Dynamic programming
            for (int i = 1; i <= n; i++) {
                if (vis[i]) {
                    for (int j = i; j > 0; j = (j - 1) & i) {
                        int l = Math.min(k, len[i - j] + 1);
                        for (int s = 1; s <= l; s++) {
                            if (dp[s - 1][i - j] != 0) {
                                dp[s][i] = (int)((dp[s][i] + (long)dp[s - 1][i - j] * inv[j]) % mod);
                            }
                        }
                    }
                }
            }

            // Calculate answer
            int ans = 0;
            int limit = Math.min(k, len[n]);
            for (int i = 0; i <= limit; i++) {
                if (dp[i][n] != 0) {
                    long tmp = dp[i][n] * fac[k] % mod;
                    tmp = tmp * inv[k - i] % mod;
                    tmp = tmp * inv[i] % mod;
                    tmp = tmp * fac[n] % mod;
                    ans = (int)((ans + tmp) % mod);
                }
            }

            System.out.println((int)((power(k, n) - ans + mod) % mod));
        }
        sc.close();
    }
}

