        long z = 1;
        long xx = x;
        int yy = y;
        while (yy > 0) {
            if ((yy & 1) != 0) z = (z * xx) % Mo;
            xx = (xx * xx) % Mo;
            yy >>= 1;
        }
        return (int) z;
    }

