import java.util.Scanner;

public class Main {
    static final long INF = 17446744073709551616L;
    static long mod;
    static long[][] dp = new long[18][250005];
    static long[] fac = new long[250005];
    static long[] inv = new long[250005];
    static long n, k;

    static long qpow(long a, long b) {
        long res = 1L;
        long tp = a;
        while (b > 0) {
            if ((b & 1) == 1) {
                res *= tp;
                res %= mod;
            }
            tp *= tp;
            tp %= mod;
            b >>= 1;
        }
        return res;
    }

    static long cal(int a, int b) {
        return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod;
    }

    static long calc() {
        int i, j, l;
        fac[0] = 1L;
        for (i = 1; i <= n; i++) {
            fac[i] = (fac[i - 1] * i) % mod;
        }
        inv[n] = qpow(fac[n], mod - 2);
        for (i = n - 1; i >= 0; i--) {
            inv[i] = (inv[i + 1] * (i + 1)) % mod;
        }

        for (i = 1; i <= n; i++) {
            dp[1][i] = inv[i];
        }

        long ans = (dp[1][(int) n] * cal(k, 1)) % mod;
        int t = Math.min(17, (int) k);
        for (i = 2; i <= t; i++) {
            for (j = (int) n; j > 0; j = (j - 1) & (int) n) {
                for (l = j; l > 0; l = (l - 1) & j) {
                    dp[i][j] += dp[i - 1][j ^ l] * inv[l];
                    if (dp[i][j] > INF) {
                        dp[i][j] %= mod;
                    }
                }
                dp[i][j] %= mod;
            }
            ans += dp[i][(int) n] * cal(k, i);
            ans %= mod;
        }
        ans = (ans * fac[(int) n]) % mod;
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextLong();
        mod = sc.nextLong();

        long ans = qpow(k, n);
        if ((n & 1) == 1) {
            System.out.println(ans);
            sc.close();
            return;
        }

        long result = (ans - calc() + mod) % mod;
        System.out.println(result);
        sc.close();
    }
}

