void get_ln() {
	p[0]=0;
	fo(i,1,n) {
		p[i]=h[i]*i;
		fo(j,1,i-1) p[i]-=p[j]*h[i-j]%Mo*j;
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	fo(i,0,n) h[i]=(p[i]+Mo)%Mo;
}

void get_exp() {
	p[0]=1;
	fo(i,1,n) {
		p[i]=0;
		fo(j,1,i) p[i]+=h[j]*p[i-j]%Mo*j;
		p[i]=p[i]%Mo*inv[i]%Mo;
	}
	fo(i,0,n) h[i]=p[i];
}

