public class Main {
    static final int N = 262144;
    static int L, n, k, Mo, len;
    static int[] bit = new int[20], fac = new int[N], inv = new int[N], cnt = new int[N];
    static int[][] g = new int[20][N], f = new int[20][N];
    static long[] h = new long[20], p = new long[20];

    static int pwr(int x, int y) {
        long z = 1;
        long xx = x;
        for (; y > 0; y >>= 1, xx = (xx * xx) % Mo) {
            if ((y & 1) == 1) {
                z = (z * xx) % Mo;
            }
        }
        return (int) z;
    }

    static void inc(int[] a, int[] b, int index) {
        a[index] = a[index] + b[index] >= Mo ? a[index] + b[index] - Mo : a[index] + b[index];
    }

    static void dec(int[] a, int[] b, int index) {
        a[index] = a[index] - b[index] < 0 ? a[index] - b[index] + Mo : a[index] - b[index];
    }

    static void FWT(int[] a, int len) {
        for (int i = 1; i < len; i <<= 1) {
            for (int j = 0; j < len; j += i << 1) {
                for (int k = 0; k < i; k++) {
                    inc(a, a, j + k + i);
                }
            }
        }
    }

    static void IFWT(int[] a, int len) {
        for (int i = 1; i < len; i <<= 1) {
            for (int j = 0; j < len; j += i << 1) {
                for (int k = 0; k < i; k++) {
                    dec(a, a, j + k + i);
                }
            }
        }
    }

    static void get_ln() {
        Arrays.fill(p, 0);
        for (int i = 1; i <= n; i++) {
            p[i] = h[i] * i % Mo;
            for (int j = 1; j < i; j++) {
                p[i] -= p[j] * h[i - j] % Mo * j;
            }
            p[i] = (p[i] % Mo + Mo) % Mo * inv[i] % Mo;
        }
        for (int i = 0; i <= n; i++) {
            h[i] = p[i];
        }
    }

    static void get_exp() {
        Arrays.fill(p, 0);
        p[0] = 1;
        for (int i = 1; i <= n; i++) {
            long sum = 0;
            for (int j = 1; j <= i; j++) {
                sum += h[j] * p[i - j] % Mo * j;
            }
            p[i] = sum % Mo * inv[i] % Mo;
        }
        for (int i = 0; i <= n; i++) {
            h[i] = p[i];
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        L = sc.nextInt();
        k = sc.nextInt();
        Mo = sc.nextInt();

        int all = pwr(k, L);
        if ((L & 1) == 1) {
            System.out.println(all);
            return;
        }

        fac[0] = 1;
        for (int i = 1; i <= L; i++) {
            fac[i] = (int)((long)fac[i - 1] * i % Mo);
        }
        inv[L] = pwr(fac[L], Mo - 2);
        for (int i = L - 1; i >= 0; i--) {
            inv[i] = (int)((long)inv[i + 1] * (i + 1) % Mo);
        }

        for (int s = 1; s <= L; s++) {
            cnt[s] = cnt[s ^ (s & -s)] + 1;
        }

        n = 0;
        for (int i = 0; i < 20; i++) {
            if (((L >> i) & 1) == 1) {
                bit[++n] = 1 << i;
            }
        }

        len = 1 << n;

        for (int i = 0; i < len; i++) {
            int s = 0;
            for (int j = 1; j <= n; j++) {
                if (((i >> (j - 1)) & 1) == 1) {
                    s += bit[j];
                }
            }
            g[cnt[i]][i] = inv[s];
        }

        for (int i = 2; i <= n; i++) {
            inv[i] = (int)((long)(Mo - Mo / i) * inv[Mo % i] % Mo);
        }

        for (int i = 0; i <= n; i++) {
            FWT(g[i], len);
        }

        for (int s = 0; s < len; s++) {
            for (int i = 0; i <= n; i++) {
                h[i] = g[i][s];
            }
            get_ln();
            for (int i = 0; i <= n; i++) {
                h[i] = h[i] * k % Mo;
            }
            get_exp();
            for (int i = 0; i <= n; i++) {
                f[i][s] = (int) h[i];
            }
        }

        int[] f_n = new int[len];
        for (int i = 0; i < len; i++) {
            f_n[i] = f[n][i];
        }
        IFWT(f_n, len);

        int ans = (int)((long)f_n[len - 1] * fac[L] % Mo);
        ans = (all - ans + Mo) % Mo;
        System.out.println(ans);
    }
}

