import java.util.Scanner;

public class Main {
    static final int N = 250005;
    static int n, kk, P;
    static long[] fac = new long[N], inv = new long[N];
    static long[][] dp = new long[26][N];

    static long qpow(long a, int b) {
        long ret = 1;
        while (b > 0) {
            if ((b & 1) == 1) ret = ret * a % P;
            a = a * a % P;
            b >>= 1;
        }
        return ret;
    }

    static int lowbit(int x) {
        return x & -x;
    }

    static long dfs(int cur, int msk) {
        if (dp[cur][msk] != -1) return dp[cur][msk];

        if (msk == 0) {
            dp[cur][msk] = fac[n];
            for (int i = 1; i <= cur; i++) {
                dp[cur][msk] = dp[cur][msk] * (kk - i + 1) % P;
            }
            return dp[cur][msk];
        }

        dp[cur][msk] = 0;
        int tmp = msk - lowbit(msk);
        for (int i = tmp; i > 0; i = (i - 1) & tmp)
            dp[cur][msk] = (dp[cur][msk] + inv[msk - i] * dfs(cur + 1, i)) % P;
        dp[cur][msk] = (dp[cur][msk] + inv[msk] * dfs(cur + 1, 0)) % P;

        return dp[cur][msk];
    }

    public static void main(String[] args) {
