            fac[i] = 1;
        }
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % P;
        }

        inv[n] = qpow(fac[n], P - 2);
        for (int i = n; i > 0; i--) {
            inv[i - 1] = inv[i] * i % P;
        }

        for (int i = 0; i < 26; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = -1;
            }
        }

        ans = (ans - dfs(0, n) + P) % P;
        System.out.println(ans);
        sc.close();
    }
}

