        int n = sc.nextInt();
        int k = sc.nextInt();
        mod = sc.nextInt();

        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % mod;
        }

        ifac[n] = exp(fac[n], mod - 2);
        for (int i = n - 1; i > 0; i--) {
            ifac[i] = ifac[i + 1] * (i + 1) % mod;
        }

        if ((n & 1) != 0) {
            System.out.println((int) exp(k, n, mod));
            return;
