    static int[] fac = new int[N];
    static int[] inv = new int[N];

    static long fpow(long a, int b, long c) {
        while (b > 0) {
            if ((b & 1) != 0) {
                c = c * a % P;
            }
            a = a * a % P;
            b >>= 1;
        }
        return c;
    }

    static void init(int n) {
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (int)((long)fac[i - 1] * i % P);
        }
        ifac[n] = (int) fpow(fac[n], P - 2, 1);
        for (int i = n - 1; i >= 0; i--) {
            ifac[i] = (int)((long)ifac[i + 1] * (i + 1) % P);
        }
        inv[1] = 1;
        for (int i = 2; i <= n; i++) {
            inv[i] = (int)((long)(P - P / i) * inv[P % i] % P);
        }
    }

    static void add(int[] x, int y, int index, int P) {
        x[index] += y;
        if (x[index] >= P) x[index] -= P;
    }

    static void sub(int[] x, int y, int P) {
        x[0] -= y;
        if (x[0] < 0) x[0] += P;
    }

    static int sub(int x, int P) {
        return x >= 0 ? x : x + P;
    }

    static void memcpy(int[] dest, int[] src, int count) {
        System.arraycopy(src, 0, dest, 0, count);
    }

    static void fpow(int[] f, int n, int k, int P) {
        int[] t = new int[n + 1];
        int[] g = new int[n + 1];
        memcpy(t, f, n + 1);
        f[0] = 1 - f[0];
        if (f[0] < 0) f[0] += P;
        g[0] = 0;

        for (int i = 1; i < n; ++i) {
            f[i] = 0;
            g[i] = 0;
            for (int j = 1; j < i; ++j) {
                long temp = ((long)f[i - j] * g[j]) % P;
                add(f, (int)temp, i, P);
                temp = ((long)t[i - j] * g[j]) % P;
                add(g, (int)temp, i, P);
            }
            sub(f, g[i], P);
            f[i] = (int)(((long)t[i] + (long)f[i] * inv[i]) % P * k % P);
            g[i] = (int)(((long)t[i] - (long)g[i] * inv[i]) % P * i % P);
        }
    }

    static void FMT(int[] f, int n, int P) {
        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; ++j) {
                    add(f, f[i + j], i + j + l, P);
                }
            }
        }
    }

