                for (int j = 0; j <= m; ++j) {
                    F[j] = f[j][i];
                }
                fpow(F, m + 1, k, P);
                for (int j = 0; j <= m; ++j) {
                    f[j][i] = F[j];
                }
            }

            IFMT(f[sub(n, P)], 1 << m, P);
            int term = (int)(((long)f[sub(n, P)][n] * fac[n]) % P);
            ans = (P + ans - term) % P;
        }

        System.out.println(ans);
        sc.close();
    }
}

