        return x & (-x);
    }

    static long fpow(long x, int y) {
        long res = 1;
        while (y > 0) {
            if ((y & 1) == 1) res = res * x % mod;
            x = x * x % mod;
            y >>= 1;
        }
        return res;
    }

    static void init() {
        fac = new long[n + 1];
        inv = new long[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % mod;
        }
        inv[n] = fpow(fac[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = inv[i + 1] * (i + 1) % mod;
        }
    }

    static long dfs(int x, int s) {
