        for (int t = now; t != 0; t = (t - 1) & now) {
            res = (res + dfs(x + 1, t) * inv[s - t] % mod) % mod;
        }
        res = (res + dfs(x + 1, 0) * inv[s] % mod) % mod;
        dp[x][s] = res;
        return res;
    }

