        for (int i = 0; i < MAX_N - 1; i++) {
            fact[i + 1] = new Pair(fact[i].first * (i + 1) % mod, 0);
        }
        factinv[MAX_N - 1] = new Pair(powMod(fact[MAX_N - 1].first, mod - 2), 0);
