public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int MOD = sc.nextInt();

            // Helper function to add modulo
            class Helper {
                void add(long[] x, int y) {
                    x[0] += y;
                    if (x[0] >= MOD) x[0] -= MOD;
                }
            }
            Helper helper = new Helper();

            // Compute binomial coefficients
            int[][] comb = new int[m + 1][m + 1];
            for (int i = 0; i <= m; i++) {
                comb[i][0] = 1;
                for (int j = 1; j <= i; j++) {
                    comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
                    if (comb[i][j] >= MOD) comb[i][j] -= MOD;
                }
            }

            int[] sum_n = new int[m + 1];
            sum_n[0] = 0;
            for (int i = 1; i <= m; i++) {
                sum_n[i] = i + sum_n[i - 1];
            }

            long[] ways = new long[m + 1];
            long[] sum = new long[m + 1];
            ways[0] = 1;
            for (int n_ = 1; n_ <= m; n_++) {
                for (int pos = 0; pos < n_; pos++) {
                    int a = pos, b = n_ - 1 - pos;
                    long to_ways = (ways[a] * ways[b]) % MOD;
                    helper.add(new long[]{ways[n_]}, (long) (n_ + 1) * comb[n_ - 1][pos] % MOD * to_ways % MOD);

                    long to_sum = 0;
                    to_sum += sum[a] * ways[b] % MOD;
                    to_sum %= MOD;
                    to_sum += sum[b] * ways[a] % MOD;
                    to_sum %= MOD;

                    helper.add(new long[]{sum[n_]}, (long) (n_ + 1) * comb[n_ - 1][pos] % MOD * to_sum % MOD);
                    long temp = (sum_n[a] + sum_n[b]) % MOD;
                    long to_add = to_ways * comb[n_ - 1][pos] % MOD * temp % MOD;
                    helper.add(new long[]{sum[n_]}, to_add);
                }
            }

            long[][] ways2 = new long[n + 1][m + 1];
            long[][] sum2 = new long[n + 1][m + 1];
            ways2[0][0] = 1;

            for (int i_ = 1; i_ <= n; i_++) {
                for (int j = 0; j <= Math.min(i_, m); j++) {
                    ways2[i_][j] = ways2[i_ - 1][j];
                    sum2[i_][j] = sum2[i_ - 1][j];

                    for (int k = 1; k <= j; k++) {
                        int ni = Math.max(0, i_ - k - 1);
                        int nj = j - k;
                        long[] tempWays = {ways2[i_][j]};
                        helper.add(tempWays, (long) ways[k] * ways2[ni][nj] % MOD * comb[j][k] % MOD);
                        ways2[i_][j] = tempWays[0];

                        long[] tempSum = {sum2[i_][j]};
                        long sum_k = sum[k];
                        long ways_k = ways[k];
                        long sumPart = (sum_k * ways2[ni][nj] + ways_k * sum2[ni][nj]) % MOD;
                        helper.add(tempSum, sumPart * comb[j][k] % MOD);
                        sum2[i_][j] = tempSum[0];
                    }
                }
            }

            System.out.println(sum2[n][m]);
        }
        sc.close();
    }
}

