import java.util.*;
import java.math.BigInteger;

public class Main {
    static final int MAXN = 505;
    static int n, m, mod;
    static int[] jc = new int[MAXN * 4];
    static int[] inv = new int[MAXN * 4];

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        m = scanner.nextInt();
        n = scanner.nextInt();
        mod = scanner.nextInt();

        init(m << 1);
        List<Integer> f = new ArrayList<>(Collections.nCopies(n + 1, 0));
        List<Integer> g = new ArrayList<>(Collections.nCopies(n + 1, 0));
        f.set(0, 1);
        for (int i = 1; i <= n; i++) {
            int sum = 0;
            for (int j = 0; j <= i - 1; j++) {
                sum = add(sum, multiply(multiply(f.get(j), f.get(i - 1 - j), mod), C(i - 1, j, mod), mod));
            }
            sum = multiply(sum, i + 1, mod);
            f.set(i, sum);
        }
        for (int i = 1; i <= n; i++) {
            int sumG = 0;
            for (int j = 0; j <= i - 1; j++) {
                int part1 = multiply(2, multiply(f.get(j), g.get(i - 1 - j), mod), mod);
                part1 = multiply(part1, C(i - 1, j, mod), mod);
                part1 = multiply(part1, i + 1, mod);
                int part2 = multiply(C(i -1, j, mod), add(S(j), S(i - 1 - j), mod), mod);
                part2 = multiply(part2, multiply(f.get(j), f.get(i - 1 - j), mod), mod);
                sumG = add(sumG, add(part1, part2, mod), mod);
            }
            g.set(i, sumG);
        }

        for (int i = 0; i <= n; i++) {
            g.set(i, multiply(g.get(i), inv[i], mod));
            f.set(i, multiply(f.get(i), inv[i], mod));
        }

        int ans = 0;
        for (int i = 1; i <= m - n + 1; i++) {
            int term = multiply(multiply(g.get(n), G(i + 1, m - n - i + 1, mod), mod), multiply(jc[n], i, mod), mod);
            ans = add(ans, term, mod);
            g = multLists(g, f, n + 1, mod);
        }
        System.out.println(ans);
    }

    static void init(int n) {
        jc[0] = 1;
        for (int i = 1; i <= n; i++) {
            jc[i] = multiply(jc[i - 1], i, mod);
        }
        inv[n] = ksm(jc[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = multiply(inv[i + 1], i + 1, mod);
        }
    }

    static int C(int n, int m, int mod) {
        if (n < 0 || m < 0 || n < m)
            return 0;
        return multiply(multiply(jc[n], inv[n - m], mod), inv[m], mod);
    }

    static int S(int n) {
        return n * (n + 1) / 2 % mod;
    }

    static int multiply(int a, int b, int mod) {
        long res = ((long) a * b) % mod;
        return (int) res;
    }

    static int add(int a, int b, int mod) {
        int res = a + b;
        if (res >= mod) res -= mod;
        return res;
    }

    static int ksm(int base, int exp) {
        int result = 1;
        int b = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = multiply(result, b, mod);
            }
            b = multiply(b, b, mod);
            e >>= 1;
        }
        return result;
    }

    static List<Integer> multLists(List<Integer> A, List<Integer> B, int n, int mod) {
        List<Integer> C = new ArrayList<>(Collections.nCopies(n + B.size() - 1, 0));
        for (int i = 0; i < A.size(); i++) {
            for (int j = 0; j < B.size(); j++) {
                int val = multiply(A.get(i), B.get(j), mod);
                C.set(i + j, add(C.get(i + j), val, mod));
            }
        }
        return C;
    }

    static int G(int n, int m, int mod) {
        return C(m + n - 1, n -1, mod);
    }
}

