    static int[][] binom = new int[N][N];
    static int[][] dp = new int[N][N];
    static int[][] ways = new int[N][N];

    static int mod;
    static long mul(long a, long b) {
        return (a * b) % mod;
    }
    static int add(int a, int b) {
        a += b;
        if (a >= mod) a -= mod;
        return a;
    }
    static int sub(int a, int b) {
        a -= b;
        if (a < 0) a += mod;
        return a;
    }
    static int c2(int x) {
        long res = (long) x * (x + 1) / 2;
        return (int) (res % mod);
    }

    static void calc() {
        binom[0][0] = 1;
        for (int i = 1; i < N; i++) {
            binom[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                binom[i][j] = add(binom[i - 1][j], binom[i - 1][j - 1]);
            }
        }
    }

    public static void main(String[] args) throws IOException {
