    static long[] ile;

    static void mulself(long[] a, int b) {
        for (int i = 0; i < a.length; i++) {
            a[i] = (a[i] * b) % P;
        }
    }

    static long mul(long a, long b) {
        return (a * b) % P;
    }

    static void add(long[] a, long b) {
        a[0] += b;
      if (a[0] >= P) a[0] -= P;
    }

    static void add(long a[], long b) {
        a[0] += b;
      if (a[0] >= P) a[0] -= P;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        P = sc.nextInt();

