            for (int j = 0; j <= i; j++) {
                if (j == 0) {
                    dwu[i][j] = 1;
                } else {
                    dwu[i][j] = dwu[i - 1][j];
                    dwu[i][j] = (dwu[i][j] + dwu[i - 1][j - 1]) % P;
                }
            }
        }

        dp1[0] = 0;
