import java.util.Scanner;

public class Main {
    static int n, m, md;
    static int[][] c = new int[505][505];
    static long[][] dpf = new long[505][505];
    static long[][] dpr = new long[505][505];
    static long[] f = new long[505];
    static long[] rst = new long[505];

    static long sum(long x) {
        return (x * (x + 1L)) / 2;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        md = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            c[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % md;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= i; k++) {
                long cur = c[i][k];
                long crst = 0;
                if (k > 0) {
                    crst = (crst * f[k - 1] + cur * rst[k - 1]) % md;
                    cur = (cur * f[k - 1]) % md;
                }
                if (k < i) {
                    crst = (crst * f[i - k - 1] + cur * rst[i - k - 1]) % md;
                    cur = (cur * f[i - k - 1]) % md;
                }
                rst[i] = (rst[i] + crst * (i + 2L) + cur * (sum(k) + sum(i - k))) % md;
                f[i] = (f[i] + (i + 2L) * cur) % md;
            }
        }

        dpf[0][0] = 1;

        for (int i = 1; i <= n; i++) {
