                long tempCPart1 = (((long) (i + 1) * chooseVal) % mod *
                        (((f[j] * c[i - 1 - j]) % mod + (f[i - 1 - j] * c[j]) % mod) % mod)) % mod;
                sumC = (sumC + tempCPart1) % mod;

