            Arrays.fill(dp2[k], 0);
        }

        dp1[0][0] = 1;

        int limit = Math.min(m, n);
        for (int k = 1; k <= n; k++) {
            dp1[k][0] = 1;
            for (int i = 1; i <= limit; i++) {
                dp1[k][i] = dp1[k - 1][i];
                dp2[k][i] = dp2[k - 1][i];

                for (int j = 1; j <= i; j++) {
                    long chooseVal = choose(i, j);
                    long temp1 = (f[j] * dp1[Math.max(k - j - 1, 0)][i - j]) % mod;
