                    dp2[k][i] = (dp2[k][i] + tempC2) % mod;

                    long tempF2 = (f[j] * dp2[Math.max(k - j - 1, 0)][i - j]) % mod;
                    long tempF2v = (tempF2 * chooseVal) % mod;
                    dp2[k][i] = (dp2[k][i] + tempF2v) % mod;
                }
