    static long[] f = new long[N];
    static long[] g = new long[N];
    static long[][] ff = new long[N][N];
    static long[][] gg = new long[N][N];

    static void add(int[] x, int y, int mod) {
        x[0] += y;
        if (x[0] >= mod) x[0] -= mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod;
            }
        }

        f[0] = 1;
        g[0] = 0;

        for (int i = 1; i <= n; i++) {
            f[i] = 0;
            g[i] = 0;
            for (int j = 1; j <= i; j++) {
                long term1 = (1L * f[j - 1] * f[i - j]) % mod;
                long term2 = (1L * g[j - 1] * f[i - j]) % mod;
                long term3 = (1L * g[i - j] * f[j - 1]) % mod;

                int s = 0;
                for (int k = 1; k <= i; k++) {
                    s += Math.abs(k - j);
                }

                long term4 = (1L * f[j - 1] * f[i - j]) % mod;
                term4 = (term4 * C[i - 1][j - 1]) % mod;
                term4 = (term4 * s) % mod;

