import java.util.Scanner;

public class Main {
    static final int N = 510;
    static int n, m, mod;
    static int[][] C = new int[N][N];
    static Pair[][] dp = new Pair[N][N];

    static class Pair {
        long fi;
        long se;

        Pair(long fi, long se) {
            this.fi = fi % mod;
            this.se = se % mod;
        }

        Pair add(Pair other) {
            return new Pair((this.fi + other.fi) % mod, (this.se + other.se) % mod);
        }

        Pair multiply(Pair other) {
            long fiPart = (this.fi * other.fi) % mod;
            long sePart = ((this.fi * other.se) + (this.se * other.fi)) % mod;
            return new Pair(fiPart, sePart);
        }
    }

    static int add(int a, int b) {
        int res = a + b;
        if (res >= mod) res -= mod;
        return res;
    }

    static long s1(int l, int r) {
        long sum = (long) (l + r) * (r - l + 1) / 2;
        return sum;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();

        for (int i = 0; i < N; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = add(C[i - 1][j], C[i - 1][j - 1]);
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new Pair(0, 0);
            }
            dp[i][0] = new Pair(1, 0);
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 1; j <= Math.min(i, m); j++) {
                if (i != j) {
                    for (int k = 1; k <= i; k++) {
                        Pair term = dp[k - 1][k - 1].multiply(dp[i - k][j - k + 1])
                                .multiply(new Pair(C[j][k - 1], 0));
                        dp[i][j] = dp[i][j].add(term);
                    }
                } else {
                    for (int k = 1; k <= i; k++) {
                        long factor = (i + 1) * (k * k - (long) s1(1, k) + s1(k + 1, i) - k * (i - k));
                        Pair term = dp[k - 1][k - 1].multiply(dp[i - k][i - k])
                                .multiply(new Pair(C[i - 1][k - 1], 0))
                                .multiply(new Pair(factor, 0));
                        dp[i][j] = dp[i][j].add(term);
                    }
                }
            }
        }
        System.out.println(dp[n][m].se);
        sc.close();
    }
}

