import java.util.*;

public class Main {

    static class Input {
        long mod;
        int n, m;

        boolean read(Scanner sc) {
            if (sc.hasNextInt()) {
                n = sc.nextInt();
                m = sc.nextInt();
                mod = sc.nextLong();
                return true;
            }
            return false;
        }
    }

    static class Data extends Input {
        long ans;

        void write() {
            System.out.println(ans);
        }
    }

    static class Solution extends Data {
        static final int N = 500;
        long[][] c = new long[N + 1][N + 1];
        Pair[] a = new Pair[N + 1];
        Pair[][] d = new Pair[N + 2][N + 1];

        static class Pair {
            long first;
            long second;

            Pair() {
                this.first = 0;
                this.second = 0;
            }

            Pair(long first, long second) {
                this.first = first;
                this.second = second;
            }
        }

        long pw(long x, long y) {
            long res = 1;
            while (y > 0) {
                if ((y & 1) == 1) {
                    res = res * x % mod;
                }
                x = x * x % mod;
                y >>= 1;
            }
            return res;
        }

        long inv(long x) {
            return pw(x, mod - 2);
        }

        long ss(int x) {
            return (long) x * (x + 1) / 2;
        }

        void solve() {
            // Fill c with binomial coefficients
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    if (i == 0 || j == 0) {
                        c[i][j] = 1;
                    } else {
                        c[i][j] = (c[i - 1][j] + c[i][j - 1]) % mod;
                    }
                }
            }

            for (int i = 0; i < a.length; i++) {
                a[i] = new Pair(0, 0);
            }
            a[0] = new Pair(1, 0);
            for (int i = 1; i <= m; i++) {
                for (int j = 0; j < i; j++) {
                    Pair cur = new Pair();
                    long a_j_first = a[j].first;
                    long a_j_second = a[j].second;
                    long a_i_1_j_first = a[i - 1 - j].first;
                    long a_i_1_j_second = a[i - 1 - j].second;

                    cur.first = a_j_first * a_i_1_j_first % mod;
                    cur.second = (a_j_second * a_i_1_j_first + a_j_first * a_i_1_j_second) % mod;

                    long sum_j = ss(j);
                    long sum_i_1_j = ss(i - 1 - j);

                    cur.second = (cur.second * (i + 1) + (sum_j + sum_i_1_j) * cur.first) % mod;
                    cur.first = (cur.first * (i + 1)) % mod;
                    cur.first = (cur.first * c[j][i - 1 - j]) % mod;
                    cur.second = (cur.second * c[j][i - 1 - j]) % mod;

                    a[i].first = (a[i].first + cur.first) % mod;
                    a[i].second = (a[i].second + cur.second) % mod;
                }
            }

            // Initialize d array with Pair objects
            for (int i = 0; i < d.length; i++) {
                for (int j = 0; j < d[i].length; j++) {
                    d[i][j] = new Pair(0, 0);
                }
            }
            d[0][0] = new Pair(1, 0);

            for (int i = 0; i <= n + 1; i++) {
                for (int j = 0; j <= m; j++) {
                    for (int k = 0; k <= Math.min(n - i, m - j); k++) {
                        Pair cur = new Pair();
                        long a_k_first = a[k].first;
                        long a_k_second = a[k].second;
                        long d_i_j_first = d[i][j].first;
                        long d_i_j_second = d[i][j].second;

                        cur.first = a_k_first * d_i_j_first % mod;
                        cur.second = (a_k_second * d_i_j_first + a_k_first * d_i_j_second) % mod;

                        long c_j_k = c[j][k];

                        cur.first = (cur.first * c_j_k) % mod;
                        cur.second = (cur.second * c_j_k) % mod;

                        int new_i = i + k + 1;
                        int new_j = j + k;

                        d[new_i][new_j].first = (d[new_i][new_j].first + cur.first) % mod;
                        d[new_i][new_j].second = (d[new_i][new_j].second + cur.second) % mod;
                    }
                }
            }

            this.ans = d[n + 1][m].second;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Solution sol = new Solution();
        sol.read(sc);
        sol.solve();
        sol.write();
        sc.close();
    }
}

