                    long term1 = (long) f[j - 1];
                    long term2 = g[j - 1];
                    long term3 = 1L;
                    long term4 = g[i - j];

                    long part1 = (term1 * term4) + (term2 * term3);
                    long total1 = part1 * (i + 1);

                    add(f, (int) (total1 % mod));

                    // second part (s(j-1) + s(i-j))
                    long sumS = s(j - 1) + s(i - j);
                    long part2 = sumS * coef;
                    add(f, (int) (part2 % mod));
                }
                // g[i] update
                {
                    long tmp_val = (long) coef * (i + 1);
