                add(dp2[i + 1], dp2[i][j]);
                for (int k = 1; i + k <= n && j + k <= m; k++) {
                    int tmp = C[j + k][j];

                    long val1 = (long) tmp * dp1[i][j] % mod;
                    long val2 = (long) tmp * dp2[i][j] % mod;

                    // Update dp1[i + k + 1][j + k]
                    add(dp1[i + k + 1], M(g[k], val1));
                    add(dp1[i + k + 1], M(f[k], val2));
                    // Update dp2[i + k + 1][j + k]
                    add(dp2[i + k + 1], M(g[k], val2));
                }
            }
        }

        System.out.println(dp1[n + 1][m]);
        sc.close();
    }

