                );
            }
            a[i] = tmp;
            c[i] = tmpc;
        }

        // Initialize dpc[0][0][0]=1;
        dpc[0][0][0] = new Mint(1);

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                if (j > i) continue;
