import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mo = sc.nextInt();

        int maxn = 505;
        long[] f = new long[maxn], g = new long[maxn];
        long[][] C = new long[maxn][maxn];
        long ans = 0;
        long[][] f0 = new long[maxn][maxn], g0 = new long[maxn][maxn];

        // Calculate combinations C
        C[0][0] = 1;
        for (int i = 1; i <= n + 1; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mo;
            }
        }

        // Initialize f and g
        f[0] = 1;
        g[0] = 0;
        f[1] = 2;
        g[1] = 0;

        // Compute f and g
        for (int i = 2; i <= n; i++) {
            f[i] = (f[i] + f[i - 1] * (i + 1) * 2) % mo;
            g[i] = (g[i] + f[i - 1] * i % mo * (i - 1)) % mo;
            g[i] = (g[i] + g[i - 1] * (i + 1) * 2) % mo;

            for (int j = 1; j + 1 < i; j++) {
                int k = i - j - 1;
                f[i] = (f[i] + f[j] * f[k] % mo * (j + k + 2) % mo * C[j + k][k]) % mo;
                g[i] = (g[i] + (g[j] * f[k] + g[k] * f[j]) % mo * (j + k + 2) % mo * C[j + k][k]) % mo;
                long term = ((long)(j + 1) * j / 2 + (long)(k + 1) * k / 2) % mo;
                g[i] = (g[i] + f[j] * f[k] % mo * C[j + k][k] % mo * term) % mo;
            }
        }

        // Initialize f0 and g0
        f0[0][0] = 1;
        g0[0][0] = 0;

        // Compute f0 and g0
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= m; j++) {
                if (f0[i][j] != 0) {
                    for (int k = 1; j + k <= m; k++) {
                        f0[i + 1][j + k] = (f0[i + 1][j + k] + f0[i][j] * f[k] % mo * C[j + k][k]) % mo;
                        g0[i + 1][j + k] = (g0[i + 1][j + k] + (g0[i][j] * f[k] + f0[i][j] * g[k]) % mo * C[j + k][k]) % mo;
                    }
                }
            }
        }

        // Calculate the answer
        for (int i = 1; i <= m; i++) {
            int index = n + 1 - m - i;
            if (index >= 0) {
                ans = (ans + g0[i][m] * P(n + 1 - m - i, i + 1, C, mo)) % mo;
            }
        }

        System.out.println(ans);
        sc.close();
    }

    // Similar to the macro P(n,m) in C++, calculates combination or some related value
    static long P(int n, int m, long[][] C, int mo) {
        return C[n + m - 1][m - 1];
