import java.util.*;

public class Main {
    static final int N = 500;
    static int md;
    static int[][] ch = new int[N + 1][N + 1];
    static Pair[] dp1 = new Pair[N + 1];
    static Pair[][][] dp2 = new Pair[2][N + 1][N + 1];

    static class Pair {
        long first;
        long second;

        Pair() {
            this.first = 0;
            this.second = 0;
        }
    }

    static void ad(long[] x, long y) {
        x[0] += y;
        if (x[0] >= md)
            x[0] -= md;
    }

    static long sm(int n) {
        return (long) n * (n + 1) >> 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        md = sc.nextInt();

        for (int i = 0; i <= m; i++) {
            ch[i][0] = 1;
            for (int j = 1; j <= i; j++)
                ch[i][j] = ch[i - 1][j] + ch[i - 1][j - 1] >= md ? ch[i - 1][j] + ch[i - 1][j - 1] - md : ch[i - 1][j] + ch[i - 1][j - 1];
        }

        for (int i = 0; i <= N; i++)
            dp1[i] = new Pair();

