import java.util.*;
import java.io.*;

public class Main {

    static final int MAXN = 505;
    static int n, m, mod;
    static int[][] c = new int[MAXN][MAXN];

    static class T {
        int cnt, sum;

        T() {
            this.cnt = 0;
            this.sum = 0;
        }

        T(int x) {
            this.cnt = x;
            this.sum = 0;
        }

        T(int c, int s) {
            this.cnt = c;
            this.sum = s;
        }

        T mul(T t) {
            int s = mul(this.cnt, t.sum);
            s = add(s, mul(this.sum, t.cnt));
            return new T(mul(this.cnt, t.cnt), s);
        }

        T add(T t) {
            int c = this.cnt;
            c = add(c, t.cnt);
            int s = this.sum;
            s = add(s, t.sum);
            return new T(c, s);
        }
    }

    static T[] dp = new T[MAXN];
    static T[][] pdp = new T[MAXN][MAXN];

    static int mul(int a, int b) {
        return (int) ((long) a * b % mod);
    }

    static int add(int a, int b) {
        a += b;
        if (a >= mod) a -= mod;
        return a;
    }

    static boolean read() {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) {
            return false;
        }
        n = sc.nextInt();
        if (!sc.hasNextInt()) {
            return false;
        }
        m = sc.nextInt();
        if (!sc.hasNextInt()) {
            return false;
        }
        mod = sc.nextInt();
        return true;
    }

    static void solve() {
        // Precompute binomial coefficients
        for (int i = 0; i <= m; ++i) {
            c[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                c[i][j] = c[i - 1][j - 1];
                c[i][j] = add(c[i][j], c[i - 1][j]);
            }
        }

        // Initialize dp array
        for (int i = 0; i <= m; ++i) {
            dp[i] = new T(0);
        }
        dp[0] = new T(1);

        // Compute dp[k]
        for (int k = 1; k <= m; ++k) {
            T cur = new T(0);
            for (int i = 0; i < k; ++i) {
                T x = dp[i].mul(dp[k - i - 1]);
                x = x.mul(new T(c[k - 1][i]));
                for (int j = 0; j < k; ++j) {
                    T y = x.mul(new T(1 + (j == i ? 1 : 0), Math.abs(i - j)));
                    cur = cur.add(y);
                }
            }
            dp[k] = cur;
        }

        // Initialize pdp array
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                pdp[i][j] = new T(0);
            }
        }
        pdp[0][0] = new T(1);

        // Dynamic programming for answer calculation
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= m; ++j) {
                T cur = pdp[i][j];
                if (cur.cnt == 0 && cur.sum == 0) continue;
                // Proceed without additional steps
                pdp[i + 1][j] = pdp[i + 1][j].add(cur);
                for (int k = 1; j + k <= m && i + k <= n; ++k) {
                    T toAdd = cur.mul(dp[k]).mul(new T(c[m - j][k]));
                    int ni = Math.min(n, i + k + 1);
                    int nj = j + k;
                    pdp[ni][nj] = pdp[ni][nj].add(toAdd);
                }
            }
        }

        System.out.println(pdp[n][m].sum);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            if (!read()) break;
            solve();
        }
    }
}

