import java.util.Scanner;

public class Main {
    static final int N = 577;
    static int n, m, Mod;
    static long[] dp = new long[N];
    static long[] dp2 = new long[N];
    static long[][] C = new long[N][N];
    static long[][] res = new long[N][N];
    static long[][] res2 = new long[N][N];

    static long GetSum(int l, int r) {
        long sum = ((long)(l + r) * (r - l + 1)) / 2;
        return sum % Mod;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        Mod = scanner.nextInt();

        // Initialize combination coefficients C
        for (int i = 0; i < N; i++) {
            C[i][0] = 1;
            C[i][i] = 1;
        }
        for (int i = 1; i < N; i++) {
            for (int j = 1; j < i; j++) {
                C[j][i] = (C[j][i - 1] + C[j - 1][i - 1]) % Mod;
            }
        }

        // Initialize DP arrays
        dp[0] = 1;
        dp2[0] = 0;

        // Compute dp and dp2
        for (int len = 1; len <= n; len++) {
            for (int i = 1; i <= len; i++) {
                long sm = GetSum(1, i - 1) + GetSum(1, len - i);
                int cnt = len + 1;
                long term1 = (dp[i - 1] * cnt) % Mod;
                long term2 = (dp[len - i] * term1) % Mod;
                long c = C[i - 1][len - 1];
                dp[len] = (dp[len] + term2 * c) % Mod;

                long term3 = (sm * dp[i - 1]) % Mod;
                long term4 = (dp2[i - 1] * cnt) % Mod;
                long term5 = (dp2[len - i] * cnt) % Mod;
                long term6 = (dp2[len - i] * cnt) % Mod;

                dp2[len] = (dp2[len] + term3 * dp2[len - i] * c) % Mod;
                dp2[len] = (dp2[len] + term4 * dp[len - i] * c) % Mod;
                dp2[len] = (dp2[len] + term5 * dp[i - 1] * c) % Mod;
                dp2[len] = (dp2[len] + term6 * c) % Mod; // Corrected to match the pattern in C++
            }
        }

        // Compute res and res2
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= m && j <= i; j++) {
                res[i][j] = res[i - 1][j];
                res2[i][j] = res2[i - 1][j];

                for (int h = 1; h < j; h++) {
                    long c = C[h][j];
                    long tempRes = res[i - h - 1][j - h];
                    long tempRes2 = res2[i - h - 1][j - h];

                    res[i][j] = (res[i][j] + tempRes * dp[h] % Mod * c) % Mod;
                    res2[i][j] = (res2[i][j] + tempRes2 * dp[h] % Mod * c) % Mod;
                    res2[i][j] = (res2[i][j] + res[i - h - 1][j - h] * dp2[h] % Mod * c) % Mod;
                }

                res[i][j] = (res[i][j] + dp[j]) % Mod;
                res2[i][j] = (res2[i][j] + dp2[j]) % Mod;
            }
        }

        System.out.println(res2[n][m]);
        scanner.close();
    }
}

