import java.util.Scanner;

public class Main {
    static final int maxn = 505;
    static int n, m, mod;
    static int[][] C = new int[maxn][maxn];
    static int[] f = new int[maxn], g = new int[maxn];
    static int[][] F = new int[maxn][maxn], G = new int[maxn][maxn];

    static int add(int x, int y) {
        x += y;
        return x >= mod ? x - mod : x;
    }

    static int mul(int x, int y) {
        return (int) ((long) x * y % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();

        // Compute binomial coefficients C
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = add(C[i - 1][j - 1], C[i - 1][j]);
            }
        }

        // Initialize factorial-like arrays f and g
        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                int term1 = mul(mul(f[j - 1], f[i - j]), mul(i + 1, C[i - 1][j - 1]));
                f[i] = add(f[i], term1);

                int term2 = mul(mul(f[j - 1], g[i - j]), mul(i + 1, C[i - 1][j - 1]));
                g[i] = add(g[i], term2);

                int term3 = mul(mul(g[j - 1], f[i - j]), mul(i + 1, C[i - 1][j - 1]));
                g[i] = add(g[i], term3);

                int addC2 = add(C[j][2], C[i - j + 1][2]);
                int term4 = mul(mul(f[j - 1], f[i - j]), mul(addC2, C[i - 1][j - 1]));
                g[i] = add(g[i], term4);
            }
        }

        // Initialize dynamic programming matrices F and G
        F[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            F[i][i] = f[i];
            G[i][i] = g[i];

            int minJ = Math.min(i - 1, m);
            for (int j = 0; j <= minJ; j++) {
                for (int l = 0; l <= j; l++) {
                    int termF = mul(mul(f[l], F[i - l - 1][j - l]), C[j][l]);
                    F[i][j] = add(F[i][j], termF);

                    int termG1 = mul(mul(g[l], F[i - l - 1][j - l]), C[j][l]);
                    G[i][j] = add(G[i][j], termG1);

                    int termG2 = mul(mul(f[l], G[i - l - 1][j - l]), C[j][l]);
                    G[i][j] = add(G[i][j], termG2);
                }
            }
        }

        System.out.println(G[n][m]);
        sc.close();
    }
}

