import java.util.Scanner;

public class Main {
    static int mod;
    static int[] fr;
    static int[] infr;
    static int[] inv;
    static int pn = 100000;

    static class Pt {
        long f, g;

        Pt(long f, long g) {
            this.f = f;
            this.g = g;
        }

        Pt add(Pt y) {
            return new Pt(addmod(this.f + y.f), addmod(this.g + y.g));
        }

        Pt mul(Pt y) {
            long newF = (this.f * y.f) % mod;
            long newG = (this.f * y.g + this.g * y.f) % mod;
            return new Pt(newF, newG);
        }
    }

    static int addmod(long x) {
        x %= mod;
        if (x >= mod) return (int) (x - mod);
        else return (int) x;
    }

    static int submod(long x) {
        x %= mod;
        if (x < 0) return (int) (x + mod);
        else return (int) x;
    }

    static long fpow(long x, int y) {
        long ans = 1;
        long base = x % mod;
        while (y > 0) {
            if ((y & 1) == 1) ans = (ans * base) % mod;
            base = (base * base) % mod;
            y >>= 1;
        }
        return ans;
    }

    static int F(int x) {
        return (int) ((long) x * (x + 1) / 2 % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        // Typically, mod is input or set; assuming input here for completeness:
        mod = sc.nextInt();

        fr = new int[pn + 1];
        infr = new int[pn + 1];
        inv = new int[pn + 1];

        fr[0] = 1;
        infr[0] = 1;
        for (int i = 1; i <= pn; i++) {
            fr[i] = (int) ((long) i * fr[i - 1] % mod);
            infr[i] = fpow(fr[i], mod - 2);
            inv[i] = (int) fpow(i, mod - 2);
        }

        Pt[] dp = new Pt[n + 1];
        for (int i = 0; i <= n; i++) {
            dp[i] = new Pt(0, 0);
        }
        dp[0] = new Pt(1, 0);

        for (int i = 1; i <= n; i++) {
            Pt sum = new Pt(0, 0);
            for (int j = 1; j <= i; j++) {
                Pt nw = dp[j - 1].mul(dp[i - j]);
                long nwg = nw.g;
                long nwf = nw.f;

                nwg = (nwg * (i + 1)) % mod;
                nwg = (nwg + (nwf * (addmod(F(j - 1) + F(i - j)))) % mod) % mod;
                nwg = (nwg * inv[i]) % mod;
                nw.f = (nwf * (i + 1)) % mod;
                nw.f = (nw.f * inv[i]) % mod;

                sum = sum.add(new Pt(nw.f, nwg));
            }
            dp[i] = sum;
        }

        Pt[][] up = new Pt[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                up[i][j] = new Pt(0, 0);
            }
        }
        up[0][0] = new Pt(1, 0);

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(i, m); j++) {
                if (i == j) {
                    up[i][j] = dp[i];
                }
                for (int k = 0; k < j && k < i; k++) {
                    Pt temp = up[i - k - 1][j - k].mul(dp[k]);
                    up[i][j] = up[i][j].add(temp);
                }
            }
        }

        int ans = (int) ((up[n][m].g % mod) * fr[m] % mod);
        System.out.println(ans);
        sc.close();
    }
}

