import java.util.*;
import java.io.*;

public class Main {
    static long M;
    static long[][] newt;
    static long[][] inv_newt;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int c = sc.nextInt();
        int p = sc.nextInt();
        M = sc.nextLong();

        newt = new long[c + 3][c + 3];
        inv_newt = new long[c + 3][c + 3];

        // Computing binomial coefficients
        for (int i = 0; i <= c + 2; i++) {
            newt[i][i] = 1;
            newt[i][0] = 1;
            for (int j = 1; j < i; j++) {
                newt[i][j] = (newt[i - 1][j] + newt[i - 1][j - 1]) % M;
            }
        }

        // Inverses of binomial coefficients
        for (int i = 0; i <= c + 2; i++) {
            for (int j = 0; j <= c + 2; j++) {
                inv_newt[i][j] = Inv(newt[i][j], M);
            }
        }

        long ans = f(c, p);
        ans = (ans * spow(2, p, M)) % M;

        long sum_e = 0;
        for (int i = 1; i <= p; i++) {
            long e = 0;
            for (int w = 1; w <= i - 1; w++) {
                long zioms = newt[i - 1][w] * f(w, w, M) % M
                        * f(c - w - 1, i - 1 - w, M) % M;
                zioms = zioms * Inv(spow(c + 1, i - 1, M), M) % M;
                // e += w * (w + 1) / 2 * zioms mod M; Note: division by 2 modulo M requires modular inverse
                long contrib = (w % M) * ((w + 1) % M) % M;
                contrib = (contrib * Inv(2, M)) % M;
                contrib = (contrib * zioms) % M;
                e = (e + contrib) % M;
            }
            sum_e = (sum_e + e) % M;
        }

        System.out.println((ans * sum_e) % M);
        sc.close();
    }

    static long f(int c, int p, long mod) {
        if (p == 0) return 1;
        return spow(c + 1, p - 1, mod) * (c + 1 - p + mod) % mod;
    }

    static long spow(long a, int b, long m) {
        long result = 1;
        long base = a % m;
        while (b > 0) {
            if ((b & 1) == 1)
                result = (result * base) % m;
            base = (base * base) % m;
            b >>= 1;
        }
        return result;
    }

    static long Inv(long a, long m) {
        return spow(a, m - 2, m);
    }

    static long f(long c, long p, long m) {
        if (p == 0) return 1;
        return spow(c + 1, (int)(p - 1), m) * ((c + 1 - p + m) % m) % m;
    }
}

