public class Main {
    static long mod;
    static int n, m, i, j, k;
    static int[][] c = new int[505][505];
    static long[] f = new long[505];
    static long[] g = new long[505];
    static long[][][] dp = new long[505][505][2];
    static long ans = 0;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextLong();

        c[0][0] = 1;
        for (i = 1; i <= n; i++) {
            c[i][0] = 1;
            for (j = 1; j <= i; j++) {
                c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % (int) mod;
            }
        }

        f[0] = 1;
        for (i = 1; i <= n; i++) {
            f[i] = 0;
            g[i] = 0;
        }

        for (i = 1; i <= n; i++) {
            for (j = 0; j < i; j++) {
                int kVal = i - j - 1;
                long temp1 = (f[j] * f[kVal]) % mod;
                temp1 = (temp1 * (i + 1)) % mod;
                temp1 = (temp1 * c[i - 1][j]) % mod;
                f[i] = (f[i] + temp1) % mod;

                long temp2 = (g[j] * f[kVal]) % mod;
                temp2 = (temp2 * (i + 1)) % mod;
                temp2 = (temp2 * c[i - 1][j]) % mod;
                g[i] = (g[i] + temp2) % mod;

                long temp3 = (f[j] * g[kVal]) % mod;
                temp3 = (temp3 * (i + 1)) % mod;
                temp3 = (temp3 * c[i - 1][j]) % mod;
                g[i] = (g[i] + temp3) % mod;

                long val = (j * (j + 1) / 2) + (kVal * (kVal + 1) / 2);
                long temp4 = (f[j] * f[kVal]) % mod;
                temp4 = (temp4 * c[i - 1][j]) % mod;
                temp4 = (temp4 * val) % mod;
                g[i] = (g[i] + temp4) % mod;
            }
        }

        for (i = 0; i <= n; i++) {
            for (j = 0; j <= n; j++) {
                for (int z = 0; z < 2; z++) {
                    dp[i][j][z] = 0;
                }
            }
        }

        dp[0][0][1] = 1;

        for (i = 0; i <= n; i++) {
            for (j = 0; j <= i; j++) {
                long sum0 = (dp[i][j][0] + dp[i][j][1]) % mod;
                dp[i + 1][j][1] = (dp[i + 1][j][1] + sum0) % mod;
                for (k = 1; k <= n - i; k++) {
                    long temp = (dp[i][j][1] * f[k]) % mod;
                    temp = (temp * c[j + k][j]) % mod;
                    dp[i + k][j + k][0] = (dp[i + k][j + k][0] + temp) % mod;
                }
            }
        }

        for (j = 0; j <= n; j++) {
            for (i = 0; i < j; i++) {
                int rem = m - (j - i + 1);
                if (rem < 0) continue;
