    static long gcd(long a, long b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    static int calcsum(int l, int r) {
        return (l + r) * (r - l + 1) / 2;
    }

    static Res go2(int n) {
        if (n == 1) return new Res(2, 0);
        if (done2[n]) return mem2[n];
        Res ret = new Res(0, 0);
