                              + lres.ways * msummaddness % MOD * rres.ways % MOD * mlt
                              + lres.ways * mways % MOD * rres.summaddness % MOD * mlt) % MOD;
        }
        done2[n] = true;
        mem2[n] = ret;
        return ret;
    }

    static Res go1(int at, int cnt) {
        if (ncomp - at == cnt) return go2(cnt);
        if (done1[at][cnt]) return mem1[at][cnt];
        Res ret = new Res(0, 0);
        for (int i = at; i < ncomp; i++) {
            int lcnt = i - at;
