        {
            if (j >= R - 1 && k >= R)
                break;
            if (j < R + C && pattern[j + k] != 'B')
                dp[j + 1][k] += dp[j][k];
            if (k < R + C && pattern[j + k] != 'A')
                dp[j][k + 1] += dp[j][k];
        }

    int M = N - C;
