                        bp[x+1][y].put(entry.getKey() + newarea, value + entry.getValue());
                    }
                }
                if (x + y + 1 <= d) {
                    dp[x][y].clear();
                }
                if (x + y + 1 <= 2 * n - d) {
                    bp[x][y].clear();
                }
            }
        }

        for (int x = 0; x <= n; x++) {
            int y = d - x;
            if (y < 0 || y > n) continue;
            Map<Long, Long> currentMap = dp[x][y];
